// Curved arc-shaped bracket/clip (ONE connected solid)
// Structural fixes applied:
// - Make the long central opening a CLEAR THROUGH-SLOT by cutting a radial gap (between two ribs)
// - Keep two concentric curved ribs (inner + outer) with an explicit separation
// - Slot is tapered along arc length (wider toward thin end)
// - End block + tab/peg are guaranteed to intersect the body (recalculated placement)
// - Thin end is shaved/tapered
// - All parts remain one connected solid (small overlaps)
// - Final clipped to bounding box (0.30 x 0.10 x 0.40 mm), elongated along Z

// ---------------- Parameters (mm) ----------------
bbox_x = 0.30;   // X
bbox_y = 0.10;   // Y
bbox_z = 0.40;   // Z (elongated axis)

// Arc / ribs (annular sector)
arc_outer_radius = 0.145;
arc_inner_radius = 0.115;
arc_angle_deg    = 210;      // C-like opening

rib_width_y      = bbox_y;   // full width in Y

// --- NEW: explicit rib separation via radial slot (between ribs) ---
// Two ribs: inner rib [arc_inner_radius .. rib_split_r] and outer rib [rib_split_r+slot .. arc_outer_radius]
rib_split_r      = 0.130;    // nominal split radius between ribs (must be between inner and outer)
slot_rad_start   = 0.006;    // radial slot thickness near thick end
slot_rad_end     = 0.016;    // radial slot thickness near thin end

// Slot angular span (leave material near ends)
slot_ang_start   = 10;
slot_ang_end     = arc_angle_deg - 10;

// End features
end_block_len_z   = 0.060;   // along Z
end_block_rad_thk = 0.020;   // radial thickness (X-ish)
tab_len_rad       = 0.018;   // radial protrusion
tab_w_y           = 0.014;   // Y width (slightly larger for visibility)
tab_h_z           = 0.012;   // Z height (slightly larger for visibility)

// Thin end taper (shave outer rib near end)
thin_end_taper_ang = 35;
thin_end_shave_rad = 0.020;

// Connectivity / robustness
overlap = 0.002;
$fn = 128;

// ---------------- Helpers ----------------
module overall_envelope_bounding_box() {
  cube([bbox_x, bbox_y, bbox_z], center=true);
}

// 2D annular sector in XY, spanning angle [0..ang_deg] about origin.
module annular_sector_2d(r_in, r_out, ang_deg) {
  intersection() {
    difference() {
      circle(r=r_out);
      circle(r=r_in);
    }
    polygon(points=concat(
      [[0,0]],
      [for (a=[0:1:ang_deg]) [ (r_out+1)*cos(a), (r_out+1)*sin(a) ]]
    ));
  }
}

// Extrude annular sector to 3D with width in Y, arc lying in XZ.
module sector3d_y(r_in, r_out, ang_deg, y_w) {
  rotate([90,0,0])
    linear_extrude(height=y_w, center=true, convexity=10)
      annular_sector_2d(r_in, r_out, ang_deg);
}

// Main curved body: two ribs with a clear radial separation (slot) between them.
module curved_clip_body_two_ribs() {
  // Ensure split radius is valid and leaves room for max slot
  max_slot = max(slot_rad_start, slot_rad_end);
  r_split_ok = min(max(rib_split_r, arc_inner_radius + max_slot + 0.001), arc_outer_radius - max_slot - 0.001);

  union() {
    // Inner rib
    sector3d_y(arc_inner_radius, r_split_ok - overlap, arc_angle_deg, rib_width_y);

    // Outer rib
    sector3d_y(r_split_ok + overlap, arc_outer_radius, arc_angle_deg, rib_width_y);
  }
}

// Tapered radial slot cutter: removes material between ribs, varying radial thickness along arc.
module tapered_radial_slot_cutter() {
  // Use the same guarded split radius as body
  max_slot = max(slot_rad_start, slot_rad_end);
  r_split_ok = min(max(rib_split_r, arc_inner_radius + max_slot + 0.001), arc_outer_radius - max_slot - 0.001);

  step = 3; // degrees
  union() {
    for (a=[slot_ang_start:step:slot_ang_end-step]) {
      t = (a - slot_ang_start) / max(0.0001, (slot_ang_end - slot_ang_start));
      slot_rad = slot_rad_start + (slot_rad_end - slot_rad_start) * t;

      r_in  = (r_split_ok - slot_rad/2) - overlap;
      r_out = (r_split_ok + slot_rad/2) + overlap;

      // Clamp to valid radii
      r_in_c  = max(r_in,  arc_inner_radius + overlap);
      r_out_c = min(r_out, arc_outer_radius - overlap);

      rotate([0,0,a])
        sector3d_y(r_in_c, r_out_c, step + 0.4, rib_width_y + 2*overlap);
    }
  }
}

// Thick end block at arc start (angle 0), guaranteed to intersect outer rib.
module thick_end_block() {
  a = 0;

  // Place block so its inner face penetrates the outer rib by overlap.
  // Block spans X: [x_c - thk/2 .. x_c + thk/2]
  // Want (x_c - thk/2) <= arc_outer_radius - overlap
  x_c = (arc_outer_radius - overlap) + end_block_rad_thk/2 - overlap;

  // Keep within bbox after final intersection; Z centered at 0 for robust overlap with arc.
  translate([x_c*cos(a), 0, x_c*sin(a)])
    cube([end_block_rad_thk, rib_width_y + 2*overlap, end_block_len_z], center=true);
}

// Protruding tab/peg on the thick end block, extending outward (+X), guaranteed to intersect block.
module protruding_tab_peg() {
  // End block outer face is at x = x_c + end_block_rad_thk/2
  x_c_block = (arc_outer_radius - overlap) + end_block_rad_thk/2 - overlap;
  x_outer_face = x_c_block + end_block_rad_thk/2;

  // Place tab so it overlaps the block by overlap:
  // tab spans X: [x_tab - tab/2 .. x_tab + tab/2]
  // Want (x_tab - tab/2) <= x_outer_face - overlap
  x_tab = (x_outer_face - overlap) + tab_len_rad/2 - overlap;

  translate([x_tab, 0, 0])
    cube([tab_len_rad, tab_w_y, tab_h_z], center=true);
}

// Thin end taper: shave outer radius near arc end to make it thinner/tapered.
module thin_end_taper_cut() {
  a0 = arc_angle_deg - thin_end_taper_ang;
  a1 = arc_angle_deg;

  r_cut_in  = arc_outer_radius - thin_end_shave_rad;
  r_cut_out = arc_outer_radius + 1;

  rotate([0,0,a0])
    sector3d_y(r_cut_in, r_cut_out, (a1 - a0) + 0.4, rib_width_y + 2*overlap);
}

// Assemble connected solid
module main_solid() {
  union() {
    difference() {
      curved_clip_body_two_ribs();
      // Explicit, clearly visible through-slot between ribs (tapered)
      tapered_radial_slot_cutter();
      // Thin end taper
      thin_end_taper_cut();
    }
    // Attachments on thick end (with overlap)
    thick_end_block();
    protruding_tab_peg();
  }
}

// Final: clip to bounding box to guarantee size
intersection() {
  main_solid();
  overall_envelope_bounding_box();
}

// Thin circular plate with central round through-hole and 8 hex through-holes on a bolt circle

$fn = 180;

// Parameters (meters -> 0.03 m = 30 mm)
plate_od        = 0.03;    // outer diameter
plate_thk       = 0.001;   // thickness
center_hole_d   = 0.015;   // central through-hole diameter
bolt_circle_d   = 0.022;   // bolt circle diameter (for hex hole centers)
hex_hole_af     = 0.004;   // hex across-flats
hole_count      = 8;
hex_rotation_deg = 0.0;
overlap         = 0.0005;  // extra height for clean through-cuts

// Ensure non-zero Z scale so geometry is visible
scale_xy = 1.0;
scale_z  = 1.0;

// Helpers
function clamp(x, lo, hi) = x < lo ? lo : (x > hi ? hi : x);

// Hex radius (circumradius) from across-flats: AF = sqrt(3) * R
hex_R = hex_hole_af / sqrt(3);

// Keep holes inside the plate (simple safety clamp)
bc_r_nom = bolt_circle_d / 2;
bc_r_max = plate_od/2 - hex_R - 0.0002;
bc_r     = clamp(bc_r_nom, 0, bc_r_max);

// Base shapes
module outer_disk() {
    cylinder(r = plate_od/2, h = plate_thk, center = true);
}

module center_through_hole() {
    cylinder(r = center_hole_d/2, h = plate_thk + 2*overlap, center = true);
}

module hex_through_hole() {
    // Use built-in 6-sided cylinder for a true hex profile
    rotate([0, 0, hex_rotation_deg])
        cylinder(r = hex_R, h = plate_thk + 2*overlap, center = true, $fn = 6);
}

module hex_holes_radial() {
    for (i = [0 : hole_count-1]) {
        rotate([0, 0, i * 360 / hole_count])
            translate([bc_r, 0, 0])
                hex_through_hole();
    }
}

module plate_with_holes() {
    difference() {
        outer_disk();
        center_through_hole();
        hex_holes_radial();
    }
}

// Final
scale([scale_xy, scale_xy, scale_z]) plate_with_holes();

// Prismatic L-shaped bracket-like plate with stepped recess (no holes)
// Units: mm

// Overall size (very thin plate-like solid)
L = 0.20;   // X length
W = 0.13;   // Y width
T = 0.03;   // Z thickness (non-zero)

// Stepped recess (open rectangular cutout from one corner)
notch_L = 0.12;  // X size of recess
notch_W = 0.07;  // Y size of recess

// Boolean robustness
eps = 0.001;
z_overshoot = T + 2*eps;

module base_plate() {
  cube([L, W, T], center=true);
}

// Corner recess: removes material from the (-X, +Y) corner
// This yields the L-shaped outline in plan while keeping constant thickness.
module corner_recess() {
  translate([
    -L/2 + notch_L/2,   // anchored to -X edge
     W/2 - notch_W/2,   // anchored to +Y edge
     0
  ])
    cube([notch_L, notch_W, z_overshoot], center=true);
}

difference() {
  base_plate();
  corner_recess();
}

$fn = 96;

// Parameters (mm)
L = 0.22;          // overall length target (approx)
W = 0.10;          // overall width target (approx)
T = 0.01;          // plate thickness

shank_L = 0.14;
shank_W = 0.03;

bow_OD = 0.08;
bow_ID = 0.04;

bit_L = 0.06;
bit_W = 0.04;

step1_L = 0.02;
step1_depth = 0.01;

step2_L = 0.015;
step2_depth = 0.015;

tooth_L = 0.015;
tooth_H = 0.02;

eps = 0.001;

// Derived placement (all formulas, no arbitrary offsets)
bow_cx = bow_OD/2;                 // put bow at left so total length is controlled by bit end
bow_cy = W/2;

shank_x0 = bow_cx + bow_OD/2;      // shank starts at bow outer right edge
shank_x1 = shank_x0 + shank_L;     // shank ends at bit start

bit_x0 = shank_x1;                 // bit starts at shank end
bit_x1 = bit_x0 + bit_L;           // bit ends at far right

// 2D profile of the key (flat plate), then extruded once
module key_2d() {
    difference() {
        union() {
            // Bow (outer disk)
            translate([bow_cx, bow_cy]) circle(r=bow_OD/2);

            // Shank (rectangle) - connected to bow by overlap at x = shank_x0
            translate([shank_x0 - eps, bow_cy - shank_W/2])
                square([shank_L + eps, shank_W]);

            // Bit base (rectangle) - connected to shank
            translate([bit_x0 - eps, bow_cy - bit_W/2])
                square([bit_L + eps, bit_W]);

            // Triangular tooth on upper edge near bit tip
            // Base sits on top edge of bit, protrudes upward
            polygon(points=[
                [bit_x1 - tooth_L, bow_cy + bit_W/2],
                [bit_x1,          bow_cy + bit_W/2],
                [bit_x1 - tooth_L, bow_cy + bit_W/2 + tooth_H]
            ]);
        }

        // Concentric circular through-hole in bow
        translate([bow_cx, bow_cy]) circle(r=bow_ID/2);

        // Stepped rectangular notches cut from lower edge of bit
        // Step 1 (shallower)
        translate([bit_x0, bow_cy - bit_W/2])
            square([step1_L, step1_depth]);

        // Step 2 (deeper), immediately after step 1
        translate([bit_x0 + step1_L, bow_cy - bit_W/2])
            square([step2_L, step2_depth]);
    }
}

// Final solid: single connected plate-like key
linear_extrude(height=T, center=true, convexity=10)
    key_2d();

// Thin rectangular plate with shallow triangular corner recesses on BOTH large faces.
// Units: mm

// Parameters
plate_L = 100;          // length (X)
plate_W = 50;           // width  (Y)
plate_T = 2;            // thickness (Z)

corner_cut_leg   = 6;   // triangle leg size along edges
corner_cut_depth = 0.6; // recess depth into each face

eps = 0.02;             // small overlap for robust boolean ops

// --- Helpers ---
module plate_body() {
    cube([plate_L, plate_W, plate_T], center=true);
}

// Triangular prism for subtracting a corner recess.
// Base triangle is in XY with right angle at origin, legs along +X and +Y.
// Extrudes along +Z.
module corner_relief_prism(depth) {
    linear_extrude(height=depth, center=false)
        polygon(points=[[0,0],[corner_cut_leg,0],[0,corner_cut_leg]]);
}

// Place a corner relief at corner (sx,sy) on face (sz).
// sx,sy,sz are +/-1.
module place_corner_relief(sx, sy, sz) {
    // Corner location on the plate
    x0 = sx * plate_L/2;
    y0 = sy * plate_W/2;

    // Rotation so triangle points inward from that corner
    rot = (sx > 0 && sy > 0) ? 180 :
          (sx < 0 && sy > 0) ? 270 :
          (sx < 0 && sy < 0) ? 0   : 90;

    // Z placement: cut into top or bottom face
    z0 = (sz > 0) ? (plate_T/2 - corner_cut_depth - eps) : (-plate_T/2 - eps);

    translate([x0, y0, z0])
        rotate([0, 0, rot])
            corner_relief_prism(corner_cut_depth + 2*eps);
}

module all_corner_reliefs() {
    union() {
        for (sx = [-1, 1])
            for (sy = [-1, 1]) {
                place_corner_relief(sx, sy, +1); // top face
                place_corner_relief(sx, sy, -1); // bottom face
            }
    }
}

// --- Final model ---
difference() {
    plate_body();
    all_corner_reliefs();
}

// Thin vented/stiffened plate: perimeter frame + 6 rounded-rect cutouts (3x2)
// + TWO DIAGONAL RIBS that remain visible (not cut away) by masking cutouts.
// Target bounding box: 0.20 x 0.10 x very thin. One connected solid.

$fn = 64;

// ---------- Overall size ----------
L = 0.20;          // overall length (X)
W = 0.10;          // overall width  (Y)
T = 0.001;         // very thin thickness (Z)

// ---------- Frame / layout ----------
frame_w = 0.010;   // perimeter frame width

gap_x = 0.008;     // bar between columns
gap_y = 0.008;     // bar between rows

// Openings: rounded rectangles
cutout_w  = 0.045; // opening width  (X)
cutout_h  = 0.030; // opening height (Y)
cutout_r  = 0.006; // corner radius

// Diagonal ribs/webs (make them clearly visible)
rib_w = 0.010;         // rib width
rib_angle_deg = 35;    // diagonal angle

// Small numeric epsilon to avoid coplanar artifacts
eps = 0.0005;

// ---------- Helpers ----------
module rounded_rect_2d(w, h, r) {
  rr = min(r, w/2 - 1e-6, h/2 - 1e-6);
  hull() {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*(w/2 - rr), sy*(h/2 - rr)]) circle(r=rr);
  }
}

module rounded_rect_3d(w, h, r, t) {
  linear_extrude(height=t, center=true)
    rounded_rect_2d(w, h, r);
}

module rib_bar(len, w, t) {
  cube([len, w, t], center=true);
}

// ---------- Derived grid positions (3x2) ----------
pitch_x = cutout_w + gap_x;
pitch_y = cutout_h + gap_y;

xpos = [-pitch_x, 0, pitch_x];
ypos = [ pitch_y/2, -pitch_y/2];

// ---------- Main solids ----------
module base_plate() {
  cube([L, W, T], center=true);
}

module perimeter_frame() {
  // Slight overlap in Z to avoid coplanar artifacts with base_plate
  difference() {
    cube([L, W, T + 2*eps], center=true);
    cube([L - 2*frame_w, W - 2*frame_w, T + 6*eps], center=true);
  }
}

module diagonal_ribs() {
  // Keep ribs inside the interior window so they read as interior webs
  interior_L = L - 2*frame_w;
  interior_W = W - 2*frame_w;

  rib_len = sqrt(interior_L*interior_L + interior_W*interior_W) + 4*eps;

  // Clip ribs to interior window so they don't protrude into the outer frame
  intersection() {
    cube([interior_L, interior_W, T + 8*eps], center=true);
    union() {
      rotate([0,0, rib_angle_deg])  rib_bar(rib_len, rib_w, T + 4*eps);
      rotate([0,0,-rib_angle_deg])  rib_bar(rib_len, rib_w, T + 4*eps);
    }
  }
}

module all_cutouts() {
  for (x = xpos)
    for (y = ypos)
      translate([x, y, 0])
        rounded_rect_3d(cutout_w, cutout_h, cutout_r, T + 20*eps);
}

// Mask used to keep ribs from being removed by the cutouts.
// This creates the requested "stepped/angled transitions" where ribs cross openings.
module rib_keepout_mask() {
  // Slightly wider than ribs so the ribs remain clearly visible after subtraction.
  keep_w = rib_w + 2*eps;

  interior_L = L - 2*frame_w;
  interior_W = W - 2*frame_w;
  rib_len = sqrt(interior_L*interior_L + interior_W*interior_W) + 4*eps;

  intersection() {
    cube([interior_L, interior_W, T + 30*eps], center=true);
    union() {
      rotate([0,0, rib_angle_deg])  rib_bar(rib_len, keep_w, T + 24*eps);
      rotate([0,0,-rib_angle_deg])  rib_bar(rib_len, keep_w, T + 24*eps);
    }
  }
}

// ---------- Final (one connected solid) ----------
difference() {
  union() {
    // Base plate guarantees connectivity; frame + ribs add stiffness/webs
    base_plate();
    perimeter_frame();
    diagonal_ribs();
  }

  // Subtract cutouts, but DO NOT subtract where ribs exist (so ribs remain visible across openings)
  difference() {
    all_cutouts();
    rib_keepout_mask();
  }
}

// Stepped/thickened rectangular bar (single connected solid), no holes/slots/cutouts.
// Units: mm

// Overall envelope intent: elongated along X, ~0.2 x 0.2 cross-section max.
L_total = 30.0;   // length along X
W_max   = 0.20;   // max width  along Y
H_max   = 0.20;   // max height along Z

// Segment lengths (scaled to sum exactly to L_total)
seg_L = [6, 5, 4, 6, 4, 5];  // multiple shoulders

// Segment cross-sections (rectangular), alternating wider/narrower bands
// Make steps DISTINCT so they show in orthographic projections.
seg_W = [0.20, 0.10, 0.20, 0.10, 0.20, 0.10];
seg_H = [0.20, 0.14, 0.20, 0.14, 0.20, 0.14];

// Overlap to guarantee watertight connectivity between adjacent segments.
// Keep small relative to this 0.2 mm-scale cross-section.
overlap = 0.02;

// ---- helpers ----
function sum(v, i=0) = (i >= len(v)) ? 0 : v[i] + sum(v, i+1);

module seg_at(xc, L, W, H) {
    // Centered in Y/Z so width/height changes are visible as shoulders.
    translate([xc, 0, 0])
        cube([L, W, H], center=true);
}

module stepped_bar() {
    sumL   = sum(seg_L);
    scaleL = (sumL <= 0) ? 1 : (L_total / sumL);

    union() {
        x_start = -L_total/2;
        acc = 0;

        // Place segments end-to-end along X with a small overlap so they fuse.
        for (i = [0 : len(seg_L)-1]) {
            Li = seg_L[i] * scaleL;

            // Clamp to maxima to preserve the requested bounding cross-section.
            Wi = min(seg_W[i], W_max);
            Hi = min(seg_H[i], H_max);

            // Recalculated translate: exact end-to-end placement from x_start.
            xc = x_start + acc + Li/2;

            // Add overlap in X only; keeps silhouette stepped while ensuring connectivity.
            seg_at(xc, Li + overlap, Wi, Hi);

            acc = acc + Li;
        }
    }
}

// Final output: one connected solid, stepped/thickened along length, no cutouts
stepped_bar();

// Rectangular tray-like housing with recessed panel + TRUE slot opening,
// tapered/chamfered side walls, and a slightly overhanging top flange.
// Structural fixes: ensure slot is a real cut-through into the cavity, keep all
// parts connected with small overlaps, and keep all cuts within the top surface.

$fn = 64;

// ---------- Parameters (mm) ----------
L = 60;                 // overall length (elongated axis)
W = 30;                 // overall width
H = 18;                 // overall height

wall_t = 2.2;           // side wall thickness
base_t = 2.4;           // bottom thickness

flange_overhang = 1.2;  // top flange overhang per side
flange_t = 1.6;         // flange thickness

taper_inset_bottom = 2.5; // bottom footprint inset vs top (per side)

recess_L = 44;          // recess size
recess_W = 18;
recess_depth = 2.2;     // depth of recess from top surface

slot_L = 36;            // slot size (long)
slot_W = 4.0;           // slot size (narrow)

eps = 0.05;
overlap = 1.0;          // intentional overlap for watertight unions/cuts

// ---------- Helpers ----------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Keep features within walls
recess_L2 = clamp(recess_L, 0, L - 2*(wall_t + 1));
recess_W2 = clamp(recess_W, 0, W - 2*(wall_t + 1));
slot_L2   = clamp(slot_L,   0, recess_L2 - 2);
slot_W2   = clamp(slot_W,   0, recess_W2 - 2);

// ---------- Main geometry ----------
module outer_tapered_shell()
{
    // Outer solid with tapered walls; inner cavity open at top, leaving base thickness.
    difference() {
        // Outer: top footprint is [L,W], bottom is inset by taper_inset_bottom per side.
        linear_extrude(
            height = H,
            scale = [
                (L - 2*taper_inset_bottom)/L,
                (W - 2*taper_inset_bottom)/W
            ]
        )
            square([L, W], center=true);

        // Inner cavity: starts at base_t, leaves base thickness; also tapered.
        translate([0,0,base_t])
            linear_extrude(
                height = (H - base_t) + eps,
                scale = [
                    ((L - 2*wall_t) - 2*taper_inset_bottom) / (L - 2*wall_t),
                    ((W - 2*wall_t) - 2*taper_inset_bottom) / (W - 2*wall_t)
                ]
            )
                square([L - 2*wall_t, W - 2*wall_t], center=true);
    }
}

module top_flange()
{
    // Flange overlaps downward into the shell to guarantee a single connected solid.
    // Place it so its bottom is slightly below the shell top.
    translate([0,0, H - flange_t/2 - overlap/2])
        cube([L + 2*flange_overhang, W + 2*flange_overhang, flange_t + overlap], center=true);
}

module recess_cut()
{
    // Recess cut into the top surface (not through).
    // Ensure it starts at the very top and goes down recess_depth.
    translate([0,0, H - recess_depth/2 + eps/2])
        cube([recess_L2, recess_W2, recess_depth + eps], center=true);
}

module slot_cut()
{
    // TRUE slot opening: cut from the recessed floor down into the cavity.
    // Start at the recess floor (z = H - recess_depth) and cut down past the cavity top.
    // This guarantees a visible opening in orthographic views.
    slot_h = (H - base_t) + recess_depth + 2*overlap; // plenty to reach into cavity
    z_center = (H - recess_depth) - slot_h/2 + overlap; // ensures it begins at/above recess floor

    translate([0,0, z_center])
        cube([slot_L2, slot_W2, slot_h], center=true);
}

// ---------- Final ----------
difference() {
    union() {
        outer_tapered_shell();
        top_flange();
    }
    recess_cut();
    slot_cut();
}

// U-shaped clamp / forked saddle clip (single connected solid)
// Structural fixes:
// - Ensure TWO end through-holes (one near -X end, one near +X end of main body)
// - Holes are clearly through along Y and positioned near the ends (not mid-body)
// - Keep all parts connected with small overlap
// - All translate() values derived from dimensions

$fn = 96;

// -------------------- Parameters --------------------
L = 0.06;  // overall length along X (body + prongs)
W = 0.01;  // overall width along Y
H = 0.05;  // overall height along Z

body_L = 0.034;
body_W = W;
body_H = H;

prong_L = 0.026;
prong_W = 0.0032;
prong_H = H;
gap_W   = 0.0036;

cutout_R = 0.018;          // saddle radius
cutout_center_z = 0.025;   // center height of saddle from bottom of body

hole_D = 0.0016;
// Place holes near each end, but keep them inside the chamfered body
hole_offset_from_end = 0.004;

chamfer = 0.0016;          // heavier faceting amount
overlap = 0.0010;

// -------------------- Helpers --------------------
module octahedron(r=1) {
  polyhedron(
    points=[
      [ r, 0, 0], [-r, 0, 0],
      [ 0, r, 0], [ 0,-r, 0],
      [ 0, 0, r], [ 0, 0,-r]
    ],
    faces=[
      [0,2,4],[2,1,4],[1,3,4],[3,0,4],
      [2,0,5],[1,2,5],[3,1,5],[0,3,5]
    ]
  );
}

module chamfered_box(size=[10,10,10], c=1, center=true) {
  // Faceted/chamfered look via Minkowski with an octahedron (planar facets)
  minkowski() {
    cube([max(0.001, size[0]-2*c), max(0.001, size[1]-2*c), max(0.001, size[2]-2*c)], center=center);
    octahedron(c);
  }
}

module prongs_solid() {
  // Two parallel rectangular prongs extending from +X side of body
  // Ensure they overlap into the body for a solid connection.
  x_prongs = body_L/2 + prong_L/2 - overlap;

  translate([x_prongs, 0, 0]) {
    translate([0, -(gap_W/2 + prong_W/2), 0])
      chamfered_box([prong_L, prong_W, prong_H], c=min(chamfer, prong_W/3), center=true);
    translate([0,  (gap_W/2 + prong_W/2), 0])
      chamfered_box([prong_L, prong_W, prong_H], c=min(chamfer, prong_W/3), center=true);
  }
}

module fork_gap_cut() {
  // Slot between prongs (open from +X end)
  x_gap = body_L/2 + prong_L/2 - overlap;
  translate([x_gap, 0, 0])
    cube([prong_L + 4*overlap, gap_W, prong_H + 4*overlap], center=true);
}

module u_saddle_cut() {
  // U-shaped clamp cut: cylindrical cutout that OPENS to -X side
  // Cylinder axis along Y; subtract only the upper half (semi) and only for x <= x_center.
  zc = -body_H/2 + cutout_center_z;

  // Center one radius in from the -X face so it opens to -X.
  x_center = -body_L/2 + cutout_R;

  intersection() {
    // Full cylinder through Y
    translate([x_center, 0, zc])
      rotate([90, 0, 0])
        cylinder(r=cutout_R, h=body_W + 6*overlap, center=true);

    // Keep only the top half (semi-circle)
    translate([x_center, 0, zc + cutout_R/2])
      cube([2*cutout_R + 6*overlap, body_W + 6*overlap, body_H + 2*cutout_R + 6*overlap], center=true);

    // Keep only the portion that reaches the -X face (open to -X): half-space x <= x_center
    // Implemented as a large cube whose +X face is at x_center.
    translate([x_center - (body_L + prong_L)/2, 0, 0])
      cube([body_L + prong_L + 8*overlap, body_W + 8*overlap, body_H + 8*overlap], center=true);
  }
}

module end_holes_cut() {
  // Through-holes at each end of the MAIN BODY (axis along Y)
  // Explicitly compute each end position to avoid "only one visible" ambiguity.
  x_left  = -body_L/2 + hole_offset_from_end;
  x_right =  body_L/2 - hole_offset_from_end;

  for (xpos = [x_left, x_right]) {
    translate([xpos, 0, 0])
      rotate([90, 0, 0])
        cylinder(r=hole_D/2, h=body_W + 10*overlap, center=true);
  }
}

// -------------------- Main solid --------------------
module clamp_solid() {
  union() {
    chamfered_box([body_L, body_W, body_H], c=chamfer, center=true);
    prongs_solid();

    // Optional extension to reach overall L if body_L+prong_L < L (kept connected)
    extra_L = max(0, L - (body_L + prong_L));
    if (extra_L > 0) {
      // Attach to -X side of body with overlap
      x_extra = -(body_L/2) - extra_L/2 + overlap;
      translate([x_extra, 0, 0])
        chamfered_box([extra_L + 2*overlap, body_W, body_H], c=chamfer, center=true);
    }
  }
}

// -------------------- Final boolean --------------------
difference() {
  clamp_solid();

  // Fork opening
  fork_gap_cut();

  // U-shaped saddle cutout (open to -X)
  u_saddle_cut();

  // End through-holes (both ends)
  end_holes_cut();
}

