// Elongated faceted sleeve with tapered low-poly outer surface,
// stepped boss on one end (-Y), rounded/flush opposite end (+Y),
// and a continuous hexagonal through-bore along the main axis (Y).

// ---------------- Parameters (meters; keep as given) ----------------
L = 0.04; //[0.02:0.08:0.001]                 // overall length (along Y)
body_r_max = 0.005; //[0.0025:0.01:0.0001]    // larger end outer radius (near -Y)
body_r_min = 0.0046; //[0.0023:0.0092:0.0001] // smaller end outer radius (near +Y)

boss_L = 0.006; //[0.003:0.012:0.0005]        // boss length (on -Y end)
boss_r = 0.0036; //[0.0018:0.0072:0.0001]     // boss radius (reduced diameter)

hex_af = 0.0028; //[0.0014:0.0056:0.0001]     // across flats
hex_clearance = 0.0001; //[0.0:0.0005:0.00005]

facet_count = 10; //[6:24:1]                  // low-poly outer facets
round_end_L = 0.003; //[0.0015:0.006:0.0005]  // rounded cap length (on +Y end)

overlap = 0.0005; //[0.0002:0.0015:0.0001]    // boolean overlap

// Irregular flats (subtractive "dings" along the grip)
irregular_flat_depth = 0.00025; //[0.0:0.001:0.00005]
irregular_flat_L = 0.01; //[0.005:0.02:0.0005]
irregular_count = 4; //[0:8:1]

// ---------------- Helpers ----------------
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for pointy-top hex

module hex_prism_y(af, h) {
    R = hex_R_from_AF(af);
    rotate([90,0,0])
        linear_extrude(height=h, center=true)
            polygon([ for (i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

module faceted_taper_y(r1, r2, h, fn) {
    rotate([90,0,0])
        cylinder(h=h, r1=r1, r2=r2, center=true, $fn=fn);
}

module faceted_cyl_y(r, h, fn) {
    rotate([90,0,0])
        cylinder(h=h, r=r, center=true, $fn=fn);
}

module rounded_cap_plusY(r_end, capL, fn) {
    // Rounded/flush end on +Y: short faceted section + hemisphere
    union() {
        translate([0, L/2 - capL/2, 0])
            faceted_cyl_y(r_end, capL + 2*overlap, fn);
        translate([0, L/2 - capL + overlap, 0])
            sphere(r=r_end, $fn=max(24, fn*2));
    }
}

module stepped_boss_minusY(r_boss, bossL, fn) {
    // Reduced diameter boss on -Y end, clearly stepped from main body
    translate([0, -L/2 - bossL/2 + overlap, 0])
        faceted_cyl_y(r_boss, bossL + 2*overlap, fn);
}

module irregular_flats_cuts() {
    // Shallow planar cuts to create irregular flats; ensure they actually intersect the shell.
    // Use Z-offset to hit the surface regardless of rotation about Y.
    for (i = [0:irregular_count-1]) {
        ang = i*360/max(1,irregular_count) + (i%2)*17;
        y0  = -L/2 + (i+1)*(L/(irregular_count+1));
        rotate([0, ang, 0])
            translate([0, y0, body_r_max - irregular_flat_depth/2])
                cube([2*body_r_max*2.2, irregular_flat_L, irregular_flat_depth], center=true);
    }
}

// ---------------- Model ----------------
module outer_shell() {
    // Main grip: faceted tapered sleeve body (larger at -Y, smaller at +Y)
    // Add a short transition collar so the boss reads as a step.
    collar_L = min(0.0025, boss_L*0.6);
    union() {
        // Main body
        faceted_taper_y(body_r_max, body_r_min, L, facet_count);

        // Transition collar at -Y end (slight reduction before boss)
        translate([0, -L/2 - collar_L/2 + overlap, 0])
            faceted_taper_y(body_r_max*0.98, boss_r*1.05, collar_L + 2*overlap, facet_count);

        // Boss on -Y end (stepped)
        stepped_boss_minusY(boss_r, boss_L, facet_count);

        // Rounded/flush end on +Y
        rounded_cap_plusY(body_r_min, round_end_L, facet_count);
    }
}

module outer_with_irregularity() {
    difference() {
        outer_shell();
        irregular_flats_cuts();
    }
}

module hex_through_bore() {
    // Continuous through-bore along Y, extended beyond ends for clean subtraction
    total_len = L + boss_L + 2*round_end_L + 6*overlap;
    hex_prism_y(hex_af + hex_clearance, total_len);
}

// Final: one connected solid with through-bore
difference() {
    outer_with_irregularity();
    hex_through_bore();
}

// Flat linkage bracket: central annulus + through-bore + two orthogonal forked clevis arms
// All translations are dimension-derived; model is one connected solid.

// ---------- Parameters (kept from original, but used correctly) ----------
bbox_x = 0.11;   //[0.055:0.22:0.001]
bbox_y = 0.11;   //[0.055:0.22:0.001]
bbox_z = 0.02;   //[0.01:0.04:0.001]

plate_t = 0.02;  //[0.01:0.04:0.001]

ring_od = 0.06;  //[0.03:0.11:0.001]
ring_id = 0.03;  //[0.015:0.06:0.001]
bore_d  = 0.02;  //[0.01:0.04:0.001]

arm_w   = 0.02;  //[0.01:0.04:0.001]
arm_len = 0.025; //[0.0125:0.05:0.001]

clevis_gap = 0.01;  //[0.005:0.02:0.001]
prong_w    = 0.005; //[0.0025:0.01:0.0005]

u_depth      = 0.01;  //[0.005:0.02:0.001]
u_end_radius = 0.005; //[0.0025:0.01:0.0005]

overlap = 0.001; //[0.0005:0.002:0.0001]

// ---------- Derived / safety ----------
$fn = 96;

ring_r  = ring_od/2;
arm_end = ring_r + arm_len;

// Ensure prongs exist (arm_w must be >= 2*prong_w + clevis_gap)
min_arm_w = 2*prong_w + clevis_gap;
arm_w_eff = max(arm_w, min_arm_w);

// Ensure U end radius fits inside the gap
u_r_eff = min(u_end_radius, clevis_gap/2 - 0.0001);

// ---------- Helpers ----------
module annulus(h, ro, ri) {
  difference() {
    cylinder(h=h, r=ro, center=true);
    cylinder(h=h + 2*overlap, r=ri, center=true);
  }
}

module u_slot_x() {
  // U-slot opening for +X clevis: open at the end, rounded bottom.
  // Removes material centered on X axis.
  union() {
    // rectangular throat (open end)
    translate([arm_end - u_depth/2, 0, 0])
      cube([u_depth + 2*overlap, clevis_gap, plate_t + 2*overlap], center=true);
    // rounded bottom
    translate([arm_end - u_depth, 0, 0])
      cylinder(h=plate_t + 2*overlap, r=u_r_eff, center=true);
  }
}

module u_slot_y() {
  // U-slot opening for +Y clevis: open at the end, rounded bottom.
  union() {
    translate([0, arm_end - u_depth/2, 0])
      cube([clevis_gap, u_depth + 2*overlap, plate_t + 2*overlap], center=true);
    translate([0, arm_end - u_depth, 0])
      cylinder(h=plate_t + 2*overlap, r=u_r_eff, center=true);
  }
}

module clevis_arm_x() {
  // Solid arm body (will be forked by subtracting U-slot)
  // Starts at ring outer edge and extends to arm_end.
  translate([ring_r + arm_len/2 - overlap, 0, 0])
    cube([arm_len + 2*overlap, arm_w_eff, plate_t], center=true);
}

module clevis_arm_y() {
  translate([0, ring_r + arm_len/2 - overlap, 0])
    cube([arm_w_eff, arm_len + 2*overlap, plate_t], center=true);
}

// ---------- Main geometry ----------
module main_solid() {
  // Plate-like bracket centered on annulus; no big square plate.
  union() {
    // Central ring (annulus)
    annulus(plate_t, ring_r, ring_id/2);

    // Two orthogonal arms
    clevis_arm_x();
    clevis_arm_y();
  }
}

module final_model() {
  difference() {
    main_solid();

    // Through bore
    cylinder(h=plate_t + 2*overlap, r=bore_d/2, center=true);

    // Fork openings (U-shaped) to create two-prong clevis ends
    u_slot_x();
    u_slot_y();
  }
}

// ---------- Output ----------
final_model();

// Long narrow rail with tapered web, central rounded slot, 4 diamond through-holes,
// triangular lightening cutouts, and small central diamond cutout.
// Units are mm (very small part as given).

$fn = 64;

// Parameters
L = 0.2;                 // overall length (X)
W = 0.03;                // overall width  (Y)
H = 0.06;                // overall height (Z)

beam_thk = 0.012;        // bottom flange thickness (Z)
web_base_thk = 0.01;     // web thickness (Y)
web_peak_h = 0.048;      // web peak height from bottom (Z)

slot_L = 0.11;
slot_W = 0.01;
slot_end_r = 0.005;

diamond_hole_diag_L = 0.01;
diamond_hole_diag_W = 0.006;
diamond_hole_x_offset = 0.07;
diamond_hole_y_offset = 0.008;

tri_cut_L = 0.05;
tri_cut_H = 0.03;
tri_cut_x_offset = 0.055;

small_diamond_diag = 0.008;

eps = 0.001;

// ---------- Helpers ----------
module capsule2d(len, wid, r) {
  // 2D rounded-rectangle (capsule) centered at origin, along X
  // Ensures valid geometry even if r is large.
  rr = min(r, wid/2 - 1e-9, len/2 - 1e-9);
  hull() {
    translate([-(len/2 - rr), 0]) circle(r=rr);
    translate([ (len/2 - rr), 0]) circle(r=rr);
  }
}

module diamond2d(dx, dy) {
  polygon(points=[
    [0,  dy/2],
    [dx/2, 0],
    [0, -dy/2],
    [-dx/2, 0]
  ]);
}

// ---------- Solid body ----------
module main_beam_body() {
  // Bottom flange centered in XY, sitting at bottom of overall height
  translate([0, 0, -H/2 + beam_thk/2])
    cube([L, W, beam_thk], center=true);
}

module tapered_web() {
  // Triangular web in XZ, extruded in Y to web_base_thk, centered at Y=0.
  // Base sits on top of flange.
  z0 = -H/2 + beam_thk;
  z1 = -H/2 + web_peak_h;

  translate([0, 0, 0])
    linear_extrude(height=web_base_thk, center=true)
      polygon(points=[
        [-L/2, z0],
        [ L/2, z0],
        [ 0,   z1]
      ]);
}

// ---------- Cutouts (all are true through-cuts where intended) ----------
module central_rounded_slot_cut() {
  // Through the flange (Z direction), centered at origin in XY.
  // Use a capsule so it reads as a single elongated rounded slot.
  translate([0, 0, 0])
    linear_extrude(height=H + 2*eps, center=true)
      capsule2d(slot_L, slot_W, slot_end_r);
}

module diamond_hole_cut(xo, yo) {
  // Through the flange (Z direction)
  translate([xo, yo, 0])
    linear_extrude(height=H + 2*eps, center=true)
      diamond2d(diamond_hole_diag_L, diamond_hole_diag_W);
}

module triangular_lightening_cutout(xo) {
  // Cut through the web thickness (Y direction), removing a triangular window in XZ.
  // Positioned above flange.
  z0 = -H/2 + beam_thk + eps;
  translate([xo, 0, 0])
    rotate([90, 0, 0])  // extrude along Y
      linear_extrude(height=web_base_thk + 2*eps, center=true)
        polygon(points=[
          [-tri_cut_L/2, z0],
          [ tri_cut_L/2, z0],
          [ 0,           z0 + tri_cut_H]
        ]);
}

module central_small_diamond_cutout() {
  // Small diamond window in the web, cut through Y.
  zc = -H/2 + beam_thk + tri_cut_H*0.55;
  translate([0, 0, 0])
    rotate([90, 0, 0])
      linear_extrude(height=web_base_thk + 2*eps, center=true)
        translate([0, zc])
          diamond2d(small_diamond_diag, small_diamond_diag);
}

// ---------- Final model ----------
module final_model() {
  difference() {
    union() {
      main_beam_body();
      tapered_web();
    }

    // Central elongated rounded slot (single continuous opening)
    central_rounded_slot_cut();

    // Four diamond through-holes near ends (symmetric)
    diamond_hole_cut(-diamond_hole_x_offset,  diamond_hole_y_offset);
    diamond_hole_cut( diamond_hole_x_offset,  diamond_hole_y_offset);
    diamond_hole_cut(-diamond_hole_x_offset, -diamond_hole_y_offset);
    diamond_hole_cut( diamond_hole_x_offset, -diamond_hole_y_offset);

    // Web lightening cutouts + small central diamond
    triangular_lightening_cutout(-tri_cut_x_offset);
    triangular_lightening_cutout( tri_cut_x_offset);
    central_small_diamond_cutout();
  }
}

final_model();

