$fn = 96;

// Target bounding box (mm): ~X=0.03, Y=0.32, Z=0.07
// Elongated along Y

// Overall bbox targets
bbox_x = 0.03;
bbox_y = 0.32;
bbox_z = 0.07;

// Main dimensions
shaft_len = 0.24;
shaft_w   = 0.022;
shaft_h   = 0.05;

head_len  = 0.055;
head_w    = bbox_x;   // keep within bbox_x
head_h    = bbox_z;   // keep within bbox_z

collar_len = 0.012;
collar_r   = bbox_x/2;

socket_depth  = 0.03;
socket_square = 0.016;

tip_len   = 0.025;
tip_end_w = 0.008;
tip_end_h = 0.02;

facet_chamfer = 0.002;

// Use a small overlap for watertight unions (in mm)
overlap = 0.0015;

// Helpers
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

module faceted_rect_prism(x, y, z, chamfer) {
    // Slight faceting on the XZ cross-section
    intersection() {
        cube([x, y, z], center=true);
        rotate([0, 45, 0])
            cube([x + 2*chamfer, y + 2*chamfer, z + 2*chamfer], center=true);
    }
}

module tapered_tip_prism(len, w0, h0, w1, h1) {
    // Taper along Y using hull between two thin slices
    eps = 0.001;
    hull() {
        translate([0, -len/2, 0]) cube([w0, eps, h0], center=true);
        translate([0,  len/2, 0]) cube([w1, eps, h1], center=true);
    }
}

module head_block(len, w, h) {
    cube([w, len, h], center=true);
}

module collar_hex_y(len, r) {
    // Hex collar with axis along Y
    rotate([90, 0, 0])
        cylinder(h=len, r=r, center=true, $fn=6);
}

module socket_cut_from_face(depth, sq) {
    // Cut a recessed diamond (rotated square) socket along +Y from the end face.
    // Make it slightly larger in XZ and slightly deeper to read clearly in ortho views.
    rotate([0, 45, 0])
        cube([sq, depth, sq], center=false);
}

// --- Layout along Y axis (recalculated so parts touch with overlap) ---
// Place shaft centered at origin.
y_shaft_c = 0;

// Head attaches to negative-Y end of shaft
y_head_c = -(shaft_len/2 + head_len/2 - overlap);

// Collar sits at the very negative-Y end of the head (and overlaps into it)
y_collar_c = (y_head_c - head_len/2) - collar_len/2 + overlap;

// Tip attaches to positive-Y end of shaft
y_tip_c = +(shaft_len/2 + tip_len/2 - overlap);

// Socket placement: start exactly at the outer (most negative-Y) face of the collar/head region
socket_depth_eff = clamp(socket_depth, 0.002, head_len + collar_len - 0.002);

// Outer face of collar (most negative Y)
y_outer_face = y_collar_c - collar_len/2;

// Start the cut at the outer face and push inward along +Y
// (center=false cube starts at its local origin)
y_socket_start = y_outer_face - 0.0005; // tiny bias outward to ensure a clean opening

difference() {
    union() {
        // Shaft
        faceted_rect_prism(shaft_w, shaft_len, shaft_h, facet_chamfer);

        // Head
        translate([0, y_head_c, 0])
            head_block(head_len, head_w, head_h);

        // Collar (hex) at head end
        translate([0, y_collar_c, 0])
            collar_hex_y(collar_len, collar_r);

        // Tip
        translate([0, y_tip_c, 0])
            tapered_tip_prism(tip_len, shaft_w, shaft_h, tip_end_w, tip_end_h);
    }

    // Recessed socket opening (diamond), clearly visible from the collar end
    translate([0, y_socket_start, 0])
        socket_cut_from_face(socket_depth_eff + 0.001, socket_square * 1.05);
}

// Thin rectangular plate with rounded outer corners and 4 rotated polygonal corner cutouts
// Target bounding box: 0.2 x 0.1 x (very thin) mm

$fn = 64;

// --- Parameters (mm) ---
plate_L = 0.20;
plate_W = 0.10;

// "0.0 mm" thickness is not a valid solid; use an extremely thin but nonzero thickness
plate_T = 0.001;

corner_R = 0.008;          // outer corner radius
cutout_sides = 6;          // polygonal through-hole
cutout_flat_d = 0.020;     // across diameter (approx)
cutout_rot_deg = 30;       // rotation of the polygon
cutout_offset_x = 0.018;   // from outer edge toward center
cutout_offset_y = 0.018;

eps = 0.01;                // boolean robustness

// --- Helpers ---
module rounded_rect_2d(L, W, R) {
    R2 = min(R, min(L, W)/2);
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(L/2 - R2), sy*(W/2 - R2)])
                circle(r=R2);
    }
}

module plate_solid() {
    linear_extrude(height=plate_T, center=true)
        rounded_rect_2d(plate_L, plate_W, corner_R);
}

module corner_cutout_at(sx, sy) {
    // Place cutout near each corner using dimension-based formulas
    x = sx*(plate_L/2 - cutout_offset_x);
    y = sy*(plate_W/2 - cutout_offset_y);

    translate([x, y, 0])
        rotate([0, 0, cutout_rot_deg])
            cylinder(h=plate_T + 2*eps, r=cutout_flat_d/2, center=true, $fn=cutout_sides);
}

// --- Final ---
difference() {
    plate_solid();

    // Four identical corner cutouts/through-holes
    corner_cutout_at( 1,  1);
    corner_cutout_at(-1,  1);
    corner_cutout_at(-1, -1);
    corner_cutout_at( 1, -1);
}

$fn = 64;

// -------------------- Parameters (mm) --------------------
bbox_x = 0.04;   // overall width (X)
bbox_y = 0.06;   // overall thickness (Y)
bbox_z = 0.09;   // overall length (Z)  (axial direction)

collar_h = 0.02;
collar_flat_d = 0.06;   // across flats (approx) for hex collar
hole_d = 0.02;

shank_l = 0.07;
shank_w = 0.04;
shank_t = 0.03;

slot_l = 0.03;
slot_w = 0.012;
slot_offset_x = 0.012;  // slots side-by-side in X

rib_h = 0.006;          // rib height in Y
rib_w = 0.01;           // rib width in X

overlap = 0.001;

// -------------------- Helpers --------------------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Keep everything within the requested bounding box
// Total Z = collar_h + shank_l
// Total Y = max(collar_flat_d, shank_t + rib_h)  (collar is the thickest)
shank_l_eff = clamp(shank_l, 0.001, bbox_z - collar_h);
collar_h_eff = clamp(collar_h, 0.001, bbox_z - shank_l_eff);

collar_d_eff = clamp(collar_flat_d, 0.001, min(bbox_x, bbox_y));
shank_w_eff  = clamp(shank_w, 0.001, bbox_x);
shank_t_eff  = clamp(shank_t, 0.001, bbox_y);

rib_w_eff = clamp(rib_w, 0.001, shank_w_eff);
rib_h_eff = clamp(rib_h, 0.001, bbox_y - shank_t_eff);

hole_d_eff = clamp(hole_d, 0.001, collar_d_eff * 0.9);

slot_l_eff = clamp(slot_l, 0.001, shank_l_eff * 0.9);
slot_w_eff = clamp(slot_w, 0.001, min(shank_t_eff, shank_w_eff) * 0.9);

// Slot centers in X, ensure they stay inside shank width
slot_offset_x_eff = clamp(slot_offset_x, 0, (shank_w_eff - slot_w_eff) / 2);

// -------------------- Geometry --------------------
module collar_hex() {
    // Hex-like collar/head at +Z end
    translate([0, 0, shank_l_eff + collar_h_eff/2 - overlap])
        cylinder(h=collar_h_eff, r=collar_d_eff/2, $fn=6, center=true);
}

module shank_block() {
    // Rectangular shank from Z=0..shank_l_eff
    translate([0, 0, shank_l_eff/2])
        cube([shank_w_eff, shank_t_eff, shank_l_eff], center=true);
}

module rib_fin() {
    // Central longitudinal rib on top face of shank (positive Y)
    translate([0, shank_t_eff/2 + rib_h_eff/2 - overlap, shank_l_eff/2])
        cube([rib_w_eff, rib_h_eff, shank_l_eff], center=true);
}

module through_hole() {
    // Through-opening along axis (Z)
    translate([0, 0, (shank_l_eff + collar_h_eff)/2])
        cylinder(h=shank_l_eff + collar_h_eff + 2*overlap, r=hole_d_eff/2, center=true);
}

module oval_slot_at(xc) {
    // Elongated oval slot through shank thickness (Y), oriented along Z
    // Use hull of two cylinders (axis Y) to make a capsule/oval.
    zc = shank_l_eff/2;
    dz = slot_l_eff/2 - slot_w_eff/2;
    translate([xc, 0, zc])
        hull() {
            translate([0, 0, -dz])
                rotate([90, 0, 0])
                    cylinder(h=shank_t_eff + 2*overlap, r=slot_w_eff/2, center=true);
            translate([0, 0,  dz])
                rotate([90, 0, 0])
                    cylinder(h=shank_t_eff + 2*overlap, r=slot_w_eff/2, center=true);
        }
}

// -------------------- Final solid (one connected part) --------------------
difference() {
    union() {
        shank_block();
        rib_fin();
        collar_hex();
    }

    // Cuts
    through_hole();
    oval_slot_at( slot_offset_x_eff);
    oval_slot_at(-slot_offset_x_eff);
}

