strap_hole_pitch = 0.02; //[0.01:0.04:0.001]
strap_hole_count = 7; //[3:14:1]
hole_sq = 0.006; //[0.003:0.012:0.0005]
hole_tri = 0.007; //[0.0035:0.014:0.0005]
hole_dia = 0.008; //[0.004:0.016:0.0005]

rail_L = 0.205; //[0.1025:0.41:0.001]
rail_W = 0.014; //[0.007:0.028:0.0005]
tooth_pitch = 0.01; //[0.005:0.02:0.0005]
tooth_w = 0.006; //[0.003:0.012:0.0005]
tooth_d = 0.004; //[0.002:0.008:0.0005]
tooth_count = 16; //[6:32:1]

spool_L = 0.02; //[0.01:0.04:0.001]
spool_W = 0.01; //[0.005:0.02:0.0005]
spool_web_W = 0.004; //[0.002:0.008:0.0005]

layout_margin_x = 0.007; //[0.003:0.014:0.0005]
layout_margin_y = 0.01; //[0.005:0.02:0.0005]

// ---------------- Helpers ----------------
function strapA_y() =  bb_y/2 - layout_margin_y - strap_W/2;
function strapB_y() =  bb_y/2 - layout_margin_y - strap_W - gap_y - strap_W/2;

function railA_y()  = -bb_y/2 + layout_margin_y + rail_W/2;
function railB_y()  = -bb_y/2 + layout_margin_y + rail_W + gap_y + rail_W/2;

function spool_x()  = -bb_x/2 + layout_margin_x + spool_L/2;

// ---------------- 2D primitives ----------------
module strap_2d(L, W, ch) {
  ch2 = max(0, min(ch, (min(L, W) / 2) - 1e-6));
  polygon(points=[
    [-L/2 + ch2, -W/2],
    [ L/2 - ch2, -W/2],
    [ L/2,       -W/2 + ch2],
    [ L/2,        W/2 - ch2],
    [ L/2 - ch2,  W/2],
    [-L/2 + ch2,  W/2],
    [-L/2,        W/2 - ch2],
    [-L/2,       -W/2 + ch2]
  ]);
}

module diamond_2d(d) {
  polygon(points=[[0, d/2], [d/2, 0], [0, -d/2], [-d/2, 0]]);
}

module tri_2d(s) {
  polygon(points=[[0, s/2], [s/2, -s/2], [-s/2, -s/2]]);
}

// ---------------- Parts (2D) ----------------
module straps_2d() {
  union() {
    translate([0, strapA_y()]) strap_2d(strap_L, strap_W, strap_ch);
    translate([0, strapB_y()]) strap_2d(strap_L, strap_W, strap_ch);
  }
}

module strap_holes_2d(ypos, phase=0) {
  x0 = -strap_L/2 + strap_ch + strap_hole_pitch;
  x1 =  strap_L/2 - strap_ch - strap_hole_pitch;
  n  = max(0, strap_hole_count);
  step = (n > 1) ? ((x1 - x0) / (n - 1)) : 0;

  for (i = [0:n-1]) {
    xi = x0 + i*step;
    translate([xi, ypos])
      ( ((i+phase) % 3 == 0) ? diamond_2d(hole_dia)
      : ((i+phase) % 3 == 1) ? square([hole_sq, hole_sq], center=true)
                             : tri_2d(hole_tri) );
  }
}

module strap_holes_all_2d() {
  union() {
    strap_holes_2d(strapA_y(), 0);
    strap_holes_2d(strapB_y(), 1);
  }
}

module rails_2d() {
  union() {
    translate([0, railA_y()]) square([rail_L, rail_W], center=true);
    translate([0, railB_y()]) square([rail_L, rail_W], center=true);
  }
}

module rail_notches_2d(ypos) {
  y_edge = ypos + rail_W/2;
  x0 = -rail_L/2 + tooth_pitch;
  x1 =  rail_L/2 - tooth_pitch;
  n  = max(0, tooth_count);
  step = (n > 1) ? ((x1 - x0) / (n - 1)) : 0;

  for (i = [0:n-1]) {
    xi = x0 + i*step;
    translate([xi, y_edge - tooth_d/2])
      square([tooth_w, tooth_d], center=true);
  }
}

module rail_notches_all_2d() {
  union() {
    rail_notches_2d(railA_y());
    rail_notches_2d(railB_y());
  }
}

module spool_2d() {
  y_mid = (railA_y() + railB_y())/2;
  translate([spool_x(), y_mid])
    union() {
      translate([-spool_L/3, 0]) square([spool_L/3, spool_W], center=true);
      translate([ spool_L/3, 0]) square([spool_L/3, spool_W], center=true);
      square([spool_L, spool_web_W], center=true);
    }
}

// ---------------- Connectivity bridges (2D) ----------------
module bridge_between_2d(y1, y2, x_at, w=bridge_w) {
  ymid = (y1 + y2)/2;
  h = abs(y1 - y2) + min(strap_W, rail_W) - overlap*2;
  translate([x_at, ymid]) square([w, max(0, h)], center=true);
}

module bridge_horizontal_2d(x1, x2, y_at, h=bridge_w) {
  xmid = (x1 + x2)/2;
  w = abs(x2 - x1) + overlap*2;
  translate([xmid, y_at]) square([max(0, w), h], center=true);
}

module tabs_2d() {
  union() {
    x_right = strap_L/2 - bridge_w/2 - overlap;
    bridge_between_2d(strapA_y(), strapB_y(), x_right, bridge_w);

    x_left = -strap_L/2 + bridge_w/2 + overlap;
    bridge_between_2d(strapB_y(), railB_y(), x_left, bridge_w);

    y_tab = railA_y() - rail_W/2 + bridge_w/2 - overlap;
    bridge_horizontal_2d(-rail_L/2, spool_x(), y_tab, bridge_w);
  }
}

// ---------------- Final Assembly (2D) ----------------
// Simplified: single top-level difference (avoids nested boolean complexity)
module assembly_2d() {
  difference() {
    union() {
      straps_2d();
      rails_2d();
      spool_2d();
      tabs_2d();
    }
    union() {
      strap_holes_all_2d();
      rail_notches_all_2d();
    }
  }
}

linear_extrude(height=t, center=true, convexity=5)
  assembly_2d();

// Parameters
bbox_x = 0.01; //[0.005:0.02:0.0005]
bbox_y = 0.01; //[0.005:0.02:0.0005]
bbox_z = 0.01; //[0.005:0.02:0.0005]
max_r = 0.005; //[0.0025:0.01:0.0005]
head_h = 0.0042; //[0.0021:0.0084:0.0001]
head_r = 0.005; //[0.0025:0.01:0.0005]
shank_h = 0.0058; //[0.0029:0.0116:0.0001]
shank_r = 0.0018; //[0.0009:0.0036:0.0001]
neck_h = 0.0006; //[0.0003:0.0012:0.00005]
neck_r = 0.0022; //[0.0011:0.0044:0.0001]
flange_thk = 0.00045; //[0.0002:0.0009:0.00005]
flange_r = 0.0032; //[0.0016:0.0064:0.0001]
flange1_z = 0.002; //[0.001:0.004:0.0001]
flange2_z = 0.0036; //[0.0018:0.0072:0.0001]
overlap = 0.0002; //[0.00005:0.0005:0.00005]
micro_chamfer_h = 0.00025; //[0.0001:0.0005:0.00005]
micro_chamfer_r_delta = 0.00025; //[0.0001:0.0006:0.00005]
facet_sides = 10; //[6:24:1]

// Geometry
module head_domed_conical() {
  translate([0, 0, bbox_z/2 - head_h/2])
    rotate([0, 0, 0])
      cylinder(h = head_h, r1 = min(head_r, max_r), r2 = 0, center = true, $fn = facet_sides);
}

module head_to_shank_transition_neck() {
  translate([0, 0, bbox_z/2 - head_h - neck_h/2 + overlap])
    rotate([0, 0, 0])
      cylinder(h = neck_h, r = min(neck_r, max_r), center = true, $fn = facet_sides);
}

module shank_cylinder() {
  translate([0, 0, bbox_z/2 - head_h - neck_h - shank_h/2 + overlap])
    rotate([0, 0, 0])
      cylinder(h = shank_h, r = shank_r, center = true, $fn = facet_sides);
}

module retaining_flange_1() {
  translate([0, 0, bbox_z/2 - head_h - neck_h - flange1_z + overlap])
    rotate([0, 0, 0])
      cylinder(h = flange_thk, r = min(flange_r, max_r), center = true, $fn = facet_sides);
}

module retaining_flange_2() {
  translate([0, 0, bbox_z/2 - head_h - neck_h - flange2_z + overlap])
    rotate([0, 0, 0])
      cylinder(h = flange_thk, r = min(flange_r, max_r), center = true, $fn = facet_sides);
}

module micro_chamfer_head_top() {
  translate([0, 0, bbox_z/2 - micro_chamfer_h/2])
    rotate([180, 0, 0])
      cylinder(h = micro_chamfer_h, r1 = min(head_r, max_r), r2 = min(head_r, max_r) - micro_chamfer_r_delta, center = true, $fn = facet_sides);
}

module micro_chamfer_shank_tip() {
  translate([0, 0, bbox_z/2 - head_h - neck_h - shank_h + micro_chamfer_h/2 - overlap])
    rotate([0, 0, 0])
      cylinder(h = micro_chamfer_h, r1 = shank_r, r2 = shank_r - micro_chamfer_r_delta, center = true, $fn = facet_sides);
}

module extra_faceting_control() {
  translate([0, 0, bbox_z/2 - head_h - neck_h - micro_chamfer_h/2 + overlap])
    rotate([0, 0, 0])
      cylinder(h = micro_chamfer_h, r = shank_r, center = true, $fn = facet_sides);
}

// Final Union
union() {
  head_domed_conical();
  head_to_shank_transition_neck();
  shank_cylinder();
  retaining_flange_1();
  retaining_flange_2();
  micro_chamfer_head_top();
  micro_chamfer_shank_tip();
  extra_faceting_control();
}

// Prismatic U-channel cradle with tapered inner walls, top outer chamfers,
// and a bottom relief notch (bridge-like profile).

// Parameters
L = 30;                 // length (X)
W = 20;                 // width  (Y)
H = 20;                 // height (Z)

wall_t = 3;             // minimum side wall thickness

cavity_L = 24;          // cavity length (X)
cavity_W = 14;          // cavity width at top opening (Y)
cavity_depth = 14;      // cavity depth from top (Z)

taper_delta_per_side = 0.5; // cavity narrows by this per side at the bottom (Y)

notch_L = 18;           // bottom relief notch length (X)
notch_W = 12;           // bottom relief notch width  (Y)
notch_H = 6;            // bottom relief notch height (Z)

chamfer = 1;            // outer top edge chamfer size
eps = 0.05;             // small overlap for robust booleans

// ---- Helpers ----
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// Sanitize to avoid degenerate/empty geometry
cavL     = clamp(cavity_L, 0.1, L - 2*wall_t);
cavW_top = clamp(cavity_W, 0.1, W - 2*wall_t);
cavW_bot = clamp(cavity_W - 2*taper_delta_per_side, 0.1, cavW_top);
cavD     = clamp(cavity_depth, 0.1, H - 2*eps);

notL = clamp(notch_L, 0.1, L - 2*eps);
notW = clamp(notch_W, 0.1, W - 2*eps);
notH = clamp(notch_H, 0.1, H - 2*eps);

ch = clamp(chamfer, 0.0, min(W/2 - eps, H/2 - eps));

// ---- Main solids/cutters ----
module body() {
  cube([L, W, H], center=true);
}

// Open-top cavity: extrude along X, profile in Y-Z with taper on inner faces.
// FIX: Make it a true open-top pocket by placing the cutter so its TOP is
// above the body's top face, and its bottom is below the desired pocket depth.
module cavity_cut() {
  open_over = 1.5; // 1–2mm overlap to guarantee open top in boolean
  // Pocket should start at top face (Z=+H/2) and go down cavD.
  // So cutter center Z is: top - cavD/2 + open_over/2
  zc = (H/2) - (cavD/2) + (open_over/2);

  translate([0, 0, zc])
    rotate([0, 90, 0])  // extrusion axis = X
      linear_extrude(height=cavL + 2*eps, center=true, convexity=10)
        polygon(points=[
          // Top edge of cutter is above the body top by open_over
          [-cavW_top/2,  cavD/2 + open_over/2 + eps],
          [ cavW_top/2,  cavD/2 + open_over/2 + eps],
          // Bottom edge reaches full pocket depth (plus eps)
          [ cavW_bot/2, -cavD/2 - eps],
          [-cavW_bot/2, -cavD/2 - eps]
        ]);
}

// Bottom relief notch: rectangular cut from the bottom face upward.
// FIX: Ensure it actually opens to the bottom by extending below Z=-H/2.
module bottom_notch_cut() {
  open_over = 1.5; // overlap to guarantee opening to bottom
  // Notch should start at bottom face (Z=-H/2) and go up notH.
  // So cutter center Z is: bottom + notH/2 - open_over/2
  zc = (-H/2) + (notH/2) - (open_over/2);

  translate([0, 0, zc])
    cube([notL + 2*eps, notW + 2*eps, notH + open_over + 2*eps], center=true);
}

// Outer top edge chamfers along the two long top edges (Y = +/- W/2).
// FIX: Make wedges extend slightly above the top face and slightly into the body.
module top_chamfer_cuts() {
  if (ch > 0) {
    over = 1.5; // overlap for robust subtraction
    rotate([0, 90, 0])
      linear_extrude(height=L + 2*eps, center=true, convexity=10)
        union() {
          // +Y top edge chamfer wedge (in Y-Z plane)
          polygon(points=[
            [ W/2 - ch,  H/2 + over],
            [ W/2 + over, H/2 + over],
            [ W/2 + over, H/2 - ch]
          ]);

          // -Y top edge chamfer wedge
          polygon(points=[
            [-W/2 + ch,  H/2 + over],
            [-W/2 - over, H/2 + over],
            [-W/2 - over, H/2 - ch]
          ]);
        }
  }
}

// ---- Complete model ----
// Single connected solid: body minus open-top cavity, minus bottom notch,
// minus top chamfers.
difference() {
  body();
  cavity_cut();
  bottom_notch_cut();
  top_chamfer_cuts();
}

// Compact faceted cylindrical tool body with central + peripheral hex through-holes,
// stepped collar on one end, and a domed/capped opposite end.
//
// Structural fixes applied:
// - Make the hex bores unambiguously visible on the *-X end face* by ensuring the dome/cap
//   does NOT cover that end (cap stays on +X only).
// - Ensure ALL bores are true through-holes by cutting longer than the full solid extent.
// - Recalculate all translate() placements so collar/chamfer/cap overlap the main body.
// - Keep everything as one connected solid (union) then subtract bores (difference).

// ---------- Parameters (meters; keep as provided) ----------
L = 0.03; //[0.015:0.06:0.001]          // overall length (X axis)
body_flat_d = 0.009; //[0.0045:0.018:0.0005]
facet_count = 12; //[6:24:1]

bore_hex_flat_d = 0.004; //[0.002:0.008:0.0005]
bore_clearance = 0.0; //[0.0:0.001:0.0001]

small_hex_count = 6; //[3:12:1]
small_hex_flat_d = 0.0016; //[0.0008:0.0032:0.0001]
small_hex_ring_r = 0.0032; //[0.0016:0.0064:0.0001]

collar_len = 0.004; //[0.002:0.008:0.0005]
collar_flat_d = 0.01; //[0.005:0.02:0.0005]

cap_len = 0.003; //[0.0015:0.006:0.0005]
cap_dome_r = 0.0045; //[0.002:0.009:0.0005]

overlap = 0.0012; //[0.0002:0.002:0.0001]   // ~1.2mm overlap for robust connections
chamfer_len = 0.001; //[0.0003:0.002:0.0001]

// ---------- Helpers ----------
function circumradius_from_flat(flat_d) = flat_d/sqrt(3); // center->vertex

module hex2d_from_flat(flat_d) {
  r = circumradius_from_flat(flat_d);
  polygon(points=[ for (a=[0:60:300]) [ r*cos(a), r*sin(a) ] ]);
}

module faceted_cyl_x(len, flat_d, facets) {
  // Faceted outer profile extruded along X
  rotate([0,90,0])
    linear_extrude(height=len, center=true)
      polygon(points=[ for (i=[0:facets-1])
        [ (flat_d/2)*cos(i*360/facets), (flat_d/2)*sin(i*360/facets) ]
      ]);
}

module hex_bore_x(len, flat_d) {
  rotate([0,90,0])
    linear_extrude(height=len, center=true)
      hex2d_from_flat(flat_d);
}

module small_hex_bore_x(len, flat_d, ang_deg) {
  translate([0, small_hex_ring_r*cos(ang_deg), small_hex_ring_r*sin(ang_deg)])
    rotate([0,90,0])
      linear_extrude(height=len, center=true)
        hex2d_from_flat(flat_d);
}

module end_chamfer_x(x_plane, flat_d, chamfer) {
  // Bevel ring centered on the end plane (x_plane), overlapping the body
  translate([x_plane,0,0])
    rotate([0,90,0])
      cylinder(
        h = 2*chamfer + 2*overlap,
        r1 = flat_d/2 + chamfer,
        r2 = max(0.0005, flat_d/2 - chamfer),
        center = true,
        $fn = facet_count
      );
}

module domed_cap_x(x_end, body_r) {
  // Cap only on +X end. It overlaps the main body by 'overlap' so it is connected.
  // Cylinder spans [x_end - cap_len - overlap, x_end + overlap]
  x_cyl_len    = cap_len + 2*overlap;
  x_cyl_center = x_end - cap_len/2; // gives overlap on both sides of the join plane

  union() {
    // Short cylindrical collar under the dome
    translate([x_cyl_center,0,0])
      rotate([0,90,0])
        cylinder(h=x_cyl_len, r=body_r, center=true, $fn=facet_count);

    // Dome: keep only the portion beyond the plane at x = x_end - cap_len
    intersection() {
      // Sphere center chosen so dome protrudes beyond x_end
      translate([x_end - cap_len + cap_dome_r - overlap, 0, 0])
        sphere(r=cap_dome_r, $fn=96);

      // Clip volume: keep x >= (x_end - cap_len - overlap)
      translate([x_end - cap_len - overlap, -cap_dome_r - overlap, -cap_dome_r - overlap])
        cube([cap_len + 2*cap_dome_r + 3*overlap,
              2*cap_dome_r + 2*overlap,
              2*cap_dome_r + 2*overlap], center=false);
    }
  }
}

// ---------- Build ----------
module final_geometry() {
  x_end_pos =  L/2;
  x_end_neg = -L/2;

  body_r = body_flat_d/2;

  // Conservative solid extents along X (include collar and dome)
  x_min = x_end_neg - collar_len - 2*overlap;
  x_max = x_end_pos + cap_dome_r + 2*overlap;
  total_cut_len = (x_max - x_min) + 6*overlap; // extra margin so bores are guaranteed through

  difference() {
    union() {
      // Main faceted body (centered)
      faceted_cyl_x(L, body_flat_d, facet_count);

      // Stepped collar near -X end:
      // Collar spans [x_end_neg - overlap, x_end_neg + collar_len + overlap]
      x_collar_len    = collar_len + 2*overlap;
      x_collar_center = x_end_neg + collar_len/2; // attaches at -L/2 with overlap
      translate([x_collar_center, 0, 0])
        faceted_cyl_x(x_collar_len, collar_flat_d, facet_count);

      // Small chamfer at -X end plane (kept connected by overlap)
      end_chamfer_x(x_end_neg, body_flat_d, chamfer_len);

      // Domed/capped +X end (connected)
      domed_cap_x(x_end_pos, body_r);
    }

    // Through bores: cut through entire solid so they open on BOTH ends.
    // This makes the -X end face clearly show the central hex + ring of smaller hex holes.
    union() {
      hex_bore_x(total_cut_len, bore_hex_flat_d + bore_clearance);

      for (i=[0:small_hex_count-1]) {
        ang = i*360/small_hex_count;
        small_hex_bore_x(total_cut_len, small_hex_flat_d, ang);
      }
    }
  }
}

color([0.85, 0.85, 0.8])
final_geometry();

// Thick annular ring (washer/bushing-like) with circular through-bore
// Faceted, slightly irregular outer surface
// Bounding box target: 0.1 x 0.1 x 0.1 mm

// ---------- Parameters ----------
bbox = 0.1;                 // mm (target overall X/Y/Z)
height = bbox;              // mm

outer_radius_max = bbox/2;  // 0.05 mm -> overall diameter 0.1 mm
bore_radius = 0.02;         // circular through-bore radius (mm)

facet_count = 12;           // exterior faceting
facet_radial_depth = 0.003; // how much the facets cut in (mm)
irregularity_amp = 0.001;   // slight irregularity (mm)

chamfer_z = 0.006;          // mm
chamfer_radial = 0.002;     // mm

bore_clearance = 0.002;     // extra height for clean subtraction (mm)

// ---------- Helpers ----------
function clamp(x, a, b) = x < a ? a : (x > b ? b : x);

// Ensure outer radius never exceeds bbox/2 after any operation
outer_r = outer_radius_max;
inner_r = clamp(bore_radius, 0, outer_r - 0.001);

// ---------- Geometry ----------
module outer_faceted_irregular_shell() {
    // Start from a true circular cylinder at max radius (guarantees bbox),
    // then subtract shallow "facet" cutters and add tiny irregular bumps.
    difference() {
        // Base outer cylinder (true circle)
        cylinder(h=height, r=outer_r, center=true, $fn=128);

        // Facet cutters: subtract shallow wedges around the perimeter
        // (creates polygonal/faceted exterior while keeping max radius)
        for (i = [0:facet_count-1]) {
            ang = i * 360 / facet_count;

            // Slight per-facet variation (deterministic, no randomness)
            d = facet_radial_depth + irregularity_amp * sin(ang*3);

            // Cutter is a tall box tangent to the cylinder, removing a flat
            rotate([0,0,ang])
                translate([outer_r - d/2, 0, 0])
                    cube([d, 2*outer_r*1.2, height + 2*bore_clearance], center=true);
        }
    }
}

module edge_chamfers() {
    // Subtract small conical frustums at top and bottom outer edge
    union() {
        translate([0, 0, height/2 - chamfer_z/2])
            cylinder(h=chamfer_z, r1=outer_r, r2=outer_r - chamfer_radial, center=true, $fn=96);

        translate([0, 0, -height/2 + chamfer_z/2])
            cylinder(h=chamfer_z, r1=outer_r, r2=outer_r - chamfer_radial, center=true, $fn=96);
    }
}

module circular_through_bore() {
    // Force a truly circular bore with high $fn
    cylinder(h=height + 2*bore_clearance, r=inner_r, center=true, $fn=128);
}

// ---------- Final Solid ----------
difference() {
    // Outer body with faceted/irregular exterior and chamfered edges
    difference() {
        outer_faceted_irregular_shell();
        edge_chamfers();
    }

    // Circular through-hole
    circular_through_bore();
}

// Parameters
L = 0.09; //[0.045:0.18:0.001]
W = 0.04; //[0.02:0.08:0.001]
T = 0.04; //[0.02:0.08:0.001]
