T = 0.01; //[0.005:0.02:0.001]
nose_L = 0.02; //[0.01:0.04:0.001]
nose_tip_W = 0.02; //[0.01:0.04:0.001]
nose_tip_T = 0.006; //[0.003:0.012:0.001]
mount_L = 0.03; //[0.015:0.06:0.001]
mid_L = 0.06; //[0.03:0.12:0.001]
mid_W = 0.06; //[0.03:0.12:0.001]
step_pos_from_mount = 0.03; //[0.015:0.06:0.001]
step_W_drop = 0.03; //[0.015:0.06:0.001]
facet_depth = 0.004; //[0.002:0.008:0.001]
slot_depth = 0.02; //[0.01:0.04:0.001]
slot_width = 0.03; //[0.015:0.06:0.001]
slot_opening_W = 0.04; //[0.02:0.08:0.001]
fork_leg_W = 0.015; //[0.0075:0.03:0.001]
hole_d = 0.003; //[0.0015:0.006:0.0005]
hole_spacing = 0.01; //[0.005:0.02:0.001]
hole_edge_margin = 0.008; //[0.004:0.016:0.001]
overlap = 0.001; //[0.0005:0.002:0.0005]
csk_d = 0.006; //[0.003:0.012:0.0005]
csk_h = 0.002; //[0.001:0.004:0.0005]
edge_chamfer = 0.0015; //[0.0005:0.003:0.0005]
bevel_depth = 0.001; //[0.0005:0.002:0.0005]

// Main Prismatic Body
module main_prismatic_body() {
  translate([0, 0, -L/2 + mount_L/2])
    cube([W_max, T, mount_L], center=true);
}

// Stepped Transition Section
module stepped_transition_section() {
  translate([0, 0, -L/2 + mount_L + mid_L/2 - overlap])
    cube([W_max - step_W_drop, T, mid_L], center=true);
}

// Forked U-Slot End
module forked_u_slot_end() {
  translate([0, 0, -L/2 + mount_L + mid_L + (L - mount_L - mid_L)/2 - overlap])
    cube([slot_opening_W, T, L - mount_L - mid_L], center=true);
}

// Tapered Chamfered Nose End
module tapered_chamfered_nose_end() {
  translate([0, 0, L/2 - nose_L/2 + overlap])
    rotate([90, 0, 0])
    cylinder(h=nose_L, r1=slot_opening_W/2, r2=nose_tip_W/2, center=true);
}

// U-Slot Cut
module u_slot_cut() {
  translate([0, 0, -L/2 + mount_L + mid_L + (L - mount_L - mid_L) - slot_depth/2 + overlap])
    cube([slot_width, T + 2*overlap, slot_depth], center=true);
}

// Angular Flats Facets
module angular_flats_facets() {
  difference() {
    union() {
      translate([-(W_max/2 - facet_depth), 0, 0])
        rotate([0, 0, 25])
        cube([facet_depth*2, T + 2*overlap, L], center=true);
      translate([W_max/2 - facet_depth, 0, 0])
        rotate([0, 0, -25])
        cube([facet_depth*2, T + 2*overlap, L], center=true);
      translate([-((W_max - step_W_drop)/2 - facet_depth), 0, -L/2 + mount_L + mid_L/2])
        rotate([0, 0, 35])
        cube([facet_depth*2, T + 2*overlap, mid_L], center=true);
      translate([((W_max - step_W_drop)/2 - facet_depth), 0, -L/2 + mount_L + mid_L/2])
        rotate([0, 0, -35])
        cube([facet_depth*2, T + 2*overlap, mid_L], center=true);
    }
  }
}

// Three Through Holes on Mount Face
module three_through_holes_on_mount_face() {
  for (i = [0:2]) {
    translate([0, 0, -L/2 + hole_edge_margin + i*hole_spacing])
      rotate([90, 0, 0])
      cylinder(h=T + 2*overlap, r=hole_d/2, center=true);
  }
}

// Hole Countersinks
module hole_countersinks() {
  for (i = [0:2]) {
    translate([0, T/2 - csk_h/2 + overlap, -L/2 + hole_edge_margin + i*hole_spacing])
      rotate([90, 0, 0])
      cylinder(h=csk_h, r1=csk_d/2, r2=hole_d/2, center=true);
  }
}

// Edge Chamfers Fillets
module edge_chamfers_fillets() {
  difference() {
    union() {
      translate([-(W_max/2 - edge_chamfer), 0, 0])
        rotate([0, 0, 45])
        cube([edge_chamfer*2, T + 2*overlap, L], center=true);
      translate([W_max/2 - edge_chamfer, 0, 0])
        rotate([0, 0, -45])
        cube([edge_chamfer*2, T + 2*overlap, L], center=true);
    }
  }
}

// Cosmetic Face Bevels
module cosmetic_face_bevels() {
  difference() {
    union() {
      translate([0, T/2 - bevel_depth, 0])
        rotate([10, 0, 0])
        cube([W_max + 2*overlap, bevel_depth*2, L + 2*overlap], center=true);
      translate([0, -T/2 + bevel_depth, 0])
        rotate([-10, 0, 0])
        cube([W_max + 2*overlap, bevel_depth*2, L + 2*overlap], center=true);
    }
  }
}

// Final Geometry
difference() {
  union() {
    main_prismatic_body();
    stepped_transition_section();
    forked_u_slot_end();
    tapered_chamfered_nose_end();
  }
  u_slot_cut();
  angular_flats_facets();
  three_through_holes_on_mount_face();
  hole_countersinks();
  edge_chamfers_fillets();
  cosmetic_face_bevels();
}

// U-shaped bent strap with cylindrical end bosses and recessed hex sockets
// One connected solid, constant thickness in Z, elongated in X.

$fn = 96;

// ---------- Parameters (mm) ----------
bbox_x = 0.10;          // overall length (X)
bbox_y = 0.10;          // overall span (Y)
bbox_z = 0.001;         // very thin thickness (Z)

strap_thk_z = bbox_z;   // constant thickness
strap_w_y   = 0.012;    // strap width (in Y)

u_outer_len_x  = bbox_x;
u_outer_span_y = bbox_y;

// U geometry: open end at +X, closed bend at -X
leg_len_x = 0.030;          // length of each leg from open end toward bend
bend_radius_inner = 0.018;  // inner bend radius

// End bosses at the open ends (+X), centered on each leg centerline
boss_d_y   = 0.020;     // boss diameter
boss_len_x = 0.012;     // boss length along X

// Hex socket (female) recessed into each boss along the boss axis (X)
hex_af      = 0.010;    // across flats
hex_depth_x = 0.008;    // recess depth along X
hex_entry_chamfer_x = 0.0015;

overlap = 0.0015;       // ensure connectivity / clean booleans

// ---------- Helpers ----------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// across-flats -> circumradius for regular hex
function hex_R_from_af(af) = af / sqrt(3);

// 2D hex polygon (flat-to-flat = af), centered at origin
module hex2d(af){
  R = hex_R_from_af(af);
  polygon(points=[ for(i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

// ---------- Strap (2D in XY), then extrude in Z ----------
module u_strap_2d(){
  // Fit bend within span
  r_in  = clamp(bend_radius_inner, 0.001, (u_outer_span_y/2 - strap_w_y - 0.001));
  r_out = r_in + strap_w_y;

  x_open    =  u_outer_len_x/2;
  x_leg_end =  x_open - leg_len_x;     // where straight legs meet the bend
  x_c       =  x_leg_end;              // bend center x

  y_leg = u_outer_span_y/2 - strap_w_y/2;

  union(){
    // Top leg
    translate([x_leg_end - overlap, y_leg - strap_w_y/2])
      square([leg_len_x + overlap, strap_w_y], center=false);

    // Bottom leg
    translate([x_leg_end - overlap, -y_leg - strap_w_y/2])
      square([leg_len_x + overlap, strap_w_y], center=false);

    // Left-side U-bend: annular half-ring (left half)
    translate([x_c, 0])
      intersection(){
        difference(){
          circle(r=r_out);
          circle(r=r_in);
        }
        // keep only left half (x <= 0 in local coords)
        translate([-r_out - 2*overlap, -r_out - 2*overlap])
          square([r_out + 2*overlap, 2*r_out + 4*overlap], center=false);
      }
  }
}

module u_strap_3d(){
  linear_extrude(height=strap_thk_z, center=true)
    u_strap_2d();
}

// ---------- End bosses (cylinders along X) ----------
module end_boss_at(yc){
  x_open = u_outer_len_x/2;

  // Place boss so its OUTER face is at x_open, and it overlaps into the strap by `overlap`
  // Cylinder is centered, so outer face = x_boss_c + boss_len_x/2
  x_boss_c = x_open - boss_len_x/2 + overlap;

  translate([x_boss_c, yc, 0])
    rotate([0,90,0])
      cylinder(h=boss_len_x, r=boss_d_y/2, center=true);
}

module bosses(){
  y_leg = u_outer_span_y/2 - strap_w_y/2;
  union(){
    end_boss_at( y_leg);
    end_boss_at(-y_leg);
  }
}

// ---------- Hex sockets (subtract) ----------
module hex_socket_at(yc){
  x_open = u_outer_len_x/2;

  // Recessed hex prism:
  // Make the MOUTH exactly at x_open and extend inward by hex_depth_x.
  // Use center=false so placement is unambiguous and the opening is clearly visible.
  translate([x_open - hex_depth_x - overlap, yc, 0])
    rotate([0,90,0])
      linear_extrude(height=hex_depth_x + overlap, center=false)
        hex2d(hex_af);

  // Entry chamfer (slight countersink) at the mouth to read clearly in ortho views
  Rhex = hex_R_from_af(hex_af);
  translate([x_open - hex_entry_chamfer_x - overlap, yc, 0])
    rotate([0,90,0])
      cylinder(
        h  = hex_entry_chamfer_x + overlap,
        r1 = Rhex*1.30,   // larger at the mouth
        r2 = Rhex*1.02,   // transitions toward the hex pocket
        center=false
      );
}

module sockets(){
  y_leg = u_outer_span_y/2 - strap_w_y/2;
  union(){
    hex_socket_at( y_leg);
    hex_socket_at(-y_leg);
  }
}

// ---------- Final model ----------
difference(){
  union(){
    u_strap_3d();
    bosses();
  }
  sockets();
}

// Spur-gear-like wheel with external teeth and central hex through-bore
// Single connected solid, constant thickness, flat parallel faces

$fn = 128;

// -------------------- Parameters (mm) --------------------
thickness = 24;                 // make clearly elongated along Z (constant thickness)
tooth_count = 12;

root_diam  = 60;                // diameter of main circular body (tooth roots)
outer_diam = 72;                // diameter at tooth tips

tooth_radial = (outer_diam - root_diam)/2;   // radial tooth height
tooth_width_tangential = 10;                 // tooth width (tangential)

hex_flat_to_flat = 20;          // hex bore size (across flats)
hex_clearance = 0.25;           // clearance on flats

eps = 0.2;                      // small overlap to ensure watertight unions/differences

// -------------------- Helpers --------------------
function hex_R_from_flat(flat) = flat / sqrt(3); // circumradius for a hex with given flat-to-flat

module hex2d(flat) {
    R = hex_R_from_flat(flat);
    polygon(points=[ for (k=[0:5]) [ R*cos(60*k), R*sin(60*k) ] ]);
}

// -------------------- Geometry --------------------
module gear_body_disc() {
    cylinder(h=thickness, r=root_diam/2, center=true);
}

module tooth_3d() {
    // X = radial length, Y = tangential width, Z = thickness
    cube([tooth_radial + 2*eps, tooth_width_tangential, thickness], center=true);
}

module external_teeth_array() {
    // Teeth protrude outward; inner edge overlaps into the hub by eps
    for (i = [0:tooth_count-1]) {
        rotate([0, 0, i*360/tooth_count])
            translate([root_diam/2 + tooth_radial/2 - eps, 0, 0])
                tooth_3d();
    }
}

module gear_plus_teeth() {
    union() {
        gear_body_disc();
        external_teeth_array();
    }
}

module central_hex_through_bore() {
    // Through-bore along Z; slightly taller to guarantee clean subtraction
    linear_extrude(height=thickness + 2*eps, center=true)
        hex2d(hex_flat_to_flat + hex_clearance);
}

difference() {
    gear_plus_teeth();
    central_hex_through_bore();
}

// Thin elongated plate with 4 asymmetric bosses on ONE face only
// Units: mm

// Plate (elongated along X)
plate_L = 0.10;
plate_W = 0.06;
plate_T = 0.004;

// Bosses
boss_L  = 0.012;
boss_W  = 0.008;
boss_H  = 0.003;

// Asymmetric boss locations (kept within plate extents)
boss1_x = -plate_L*0.30; boss1_y = -plate_W*0.25;
boss2_x =  plate_L*0.10; boss2_y = -plate_W*0.10;
boss3_x = -plate_L*0.05; boss3_y =  plate_W*0.28;
boss4_x =  plate_L*0.32; boss4_y =  plate_W*0.18;

overlap = 0.001; // positive overlap to guarantee manifold connection

module plate_body() {
    // Plate spans Z=[0..plate_T] so the bottom face is perfectly smooth at Z=0
    translate([0, 0, plate_T/2])
        cube([plate_L, plate_W, plate_T], center=true);
}

module boss_at(x, y) {
    // Bosses protrude only upward from the top face (Z=plate_T)
    translate([x, y, plate_T + boss_H/2 - overlap])
        cube([boss_L, boss_W, boss_H], center=true);
}

union() {
    plate_body();
    boss_at(boss1_x, boss1_y);
    boss_at(boss2_x, boss2_y);
    boss_at(boss3_x, boss3_y);
    boss_at(boss4_x, boss4_y);
}

// Thin faceted washer ring with circular inner opening,
// 8 evenly spaced square through-holes (one per facet),
// and segmented beveled/chamfered faces.
//
// Units: mm

$fn = 128;

// ---- Parameters (kept near original scale) ----
outer_flat_to_flat = 0.09;     // across flats of outer octagon
inner_d            = 0.045;    // circular inner opening diameter
thk                = 0.01;     // plate thickness

hole_count         = 8;
hole_size          = 0.008;    // square through-hole size
hole_radial_pos    = 0.036;    // radius to hole centers (near perimeter)

bevel_h            = 0.002;    // height of top/bottom bevel band
bevel_inset        = 0.003;    // inset of bevel band from outer edge

seg_depth          = 0.0012;   // shallow segmentation grooves depth (per face)
seg_width          = 0.006;    // groove width along tangent

overlap            = 0.001;    // boolean overlap

// ---- Helpers ----
function oct_r_from_flat(flat) = flat/(2*cos(180/8)); // circumradius for regular octagon

module octagon2d(flat) {
    r = oct_r_from_flat(flat);
    polygon(points=[ for(i=[0:7]) [ r*cos(45*i), r*sin(45*i) ] ]);
}

module ring_base() {
    // Outer octagon minus circular inner opening
    difference() {
        linear_extrude(height=thk, center=true) octagon2d(outer_flat_to_flat);
        cylinder(d=inner_d, h=thk + 2*overlap, center=true);
    }
}

module square_holes() {
    // 8 square through-holes, centered on each facet normal direction
    union() {
        for (i=[0:hole_count-1]) {
            rotate([0,0,i*360/hole_count])
                translate([hole_radial_pos, 0, 0])
                    cube([hole_size, hole_size, thk + 2*overlap], center=true);
        }
    }
}

module bevel_band_solid() {
    // Solid "band" near the outer edge used to carve a chamfer-like step
    // (difference of two octagons), then placed at top and bottom.
    difference() {
        linear_extrude(height=bevel_h, center=true) octagon2d(outer_flat_to_flat);
        linear_extrude(height=bevel_h + 2*overlap, center=true) octagon2d(outer_flat_to_flat - 2*bevel_inset);
    }
}

module top_bottom_bevel_cuts() {
    union() {
        translate([0,0, thk/2 - bevel_h/2]) bevel_band_solid();
        translate([0,0,-thk/2 + bevel_h/2]) bevel_band_solid();
    }
}

module facet_segmentation_grooves() {
    // Shallow grooves centered on each facet to give segmented/beveled appearance.
    // These are cuts (subtracted) and do not break connectivity.
    union() {
        // Place grooves at radius near outer edge but inside it
        r_outer = oct_r_from_flat(outer_flat_to_flat);
        r_g = r_outer - bevel_inset*0.6;

        for (i=[0:hole_count-1]) {
            rotate([0,0,i*360/hole_count]) {
                // Groove aligned with facet (tangent direction = Y in local frame)
                translate([r_g, 0, 0])
                    cube([seg_depth + 2*overlap, seg_width, thk + 2*overlap], center=true);
            }
        }
    }
}

// ---- Final model ----
difference() {
    // One connected solid
    difference() {
        ring_base();
        square_holes();
    }

    // Carve top/bottom bevel steps and segmentation grooves
    top_bottom_bevel_cuts();
    facet_segmentation_grooves();
}

// Thin rectangular mounting plate with rounded corners, 4 corner through-holes,
// stepped side notch on one edge, and mirrored engraved text on both faces.

// ---------- Parameters (mm) ----------
L = 0.10;                 // overall length (elongated axis)
W = 0.06;                 // overall width
T = 0.001;                // thickness

corner_r = 0.006;         // corner radius
hole_d = 0.006;           // through-hole diameter
hole_edge_offset_L = 0.010;
hole_edge_offset_W = 0.010;

notch_edge = "W+";        // "W+", "W-", "L+", "L-"
notch_len = 0.030;
notch_depth1 = 0.012;
notch_depth2 = 0.006;
notch_step_len = 0.012;
notch_edge_margin = 0.010;

engrave_depth = 0.00035;
text_size = 0.010;
text_str = "Sleepy Pi 2";

$fn = 32;

// ---------- Helpers ----------
module rounded_rect_2d(l, w, r) {
    // Fast rounded rectangle: hull of 4 circles
    rr = min(r, min(l, w)/2);
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(l/2-rr), sy*(w/2-rr)]) circle(r=rr);
    }
}

module plate_solid() {
    linear_extrude(height=T, center=true, convexity=5)
        rounded_rect_2d(L, W, corner_r);
}

module holes_4x() {
    h = T + 0.01; // generous to avoid coplanar issues
    for (sx = [-1, 1], sy = [-1, 1]) {
        translate([sx*(L/2 - hole_edge_offset_L), sy*(W/2 - hole_edge_offset_W), 0])
            cylinder(h=h, r=hole_d/2, center=true);
    }
}

module stepped_notch_cutout() {
    // Base notch defined for edge "W+" (top edge, +Y)
    u0 = -L/2 + notch_edge_margin;
    u1 = u0 + notch_len;
    us0 = u0;
    us1 = us0 + notch_step_len;

    primary_size = [notch_len, notch_depth1, T + 0.01];
    primary_ctr  = [ (u0+u1)/2,  W/2 - notch_depth1/2, 0 ];

    step_size    = [notch_step_len, notch_depth1 + notch_depth2, T + 0.01];
    step_ctr     = [ (us0+us1)/2,   W/2 - (notch_depth1 + notch_depth2)/2, 0 ];

    module notch_Wplus() {
        union() {
            translate(primary_ctr) cube(primary_size, center=true);
            translate(step_ctr)    cube(step_size, center=true);
        }
    }

    if (notch_edge == "W+") {
        notch_Wplus();
    } else if (notch_edge == "W-") {
        rotate([0,0,180]) notch_Wplus();
    } else if (notch_edge == "L+") {
        rotate([0,0,-90]) notch_Wplus();
    } else if (notch_edge == "L-") {
        rotate([0,0,90]) notch_Wplus();
    } else {
        notch_Wplus();
    }
}

module engraved_text_both_faces() {
    // Use direct text() in each extrude (avoid assigning 2D geometry to a variable)
    h = engrave_depth + 0.0002;

    // Top face engraving
    translate([0, 0,  T/2 - engrave_depth/2])
        linear_extrude(height=h, center=true, convexity=10)
            text(text_str, size=text_size, halign="center", valign="center");

    // Bottom face engraving (mirrored)
    translate([0, 0, -T/2 + engrave_depth/2])
        mirror([1,0,0])
            linear_extrude(height=h, center=true, convexity=10)
                text(text_str, size=text_size, halign="center", valign="center");
}

// ---------- Final Model ----------
difference() {
    plate_solid();
    holes_4x();
    stepped_notch_cutout();
    engraved_text_both_faces();
}

// Long prismatic bar with recessed panels, perimeter chamfer/mitre,
// and shallow arched (concave) top/bottom with a central rectangular rib/step.
// Bounding box target: ~0.1 x 0.4 x 0.1 mm (X x Y x Z)

L = 0.40;   // length (Y)
W = 0.10;   // width  (X)
H = 0.10;   // height (Z)

panel_margin_L = 0.03;   // margin from ends (Y)
panel_margin_W = 0.015;  // margin from sides (X)
panel_depth    = 0.010;  // recess depth into face (Z)

rib_W = 0.030;  // central rib width across X
rib_H = 0.010;  // rib height above top face and below bottom face

// Make the arched/concave curvature clearly visible in orthographic views
arch_sag = 0.012; // concave sag into the face (Z) (increased for recognizability)
arch_R   = 0.45;  // large radius for shallow concavity

chamfer = 0.006;  // perimeter chamfer amount (45deg)

recess_corner_r = 0.004; // rounded corners for recessed panel
$fn = 128;

eps = 0.0005;
overlap = 0.0015; // small overlap to guarantee watertight unions/differences

// ---------- Helpers ----------
module rounded_rect_prism(size=[10,10,1], r=1, center=true) {
  x = size[0]; y = size[1]; z = size[2];
  r2 = max(0, min(r, x/2 - eps, y/2 - eps));
  linear_extrude(height=z, center=center)
    offset(r=r2)
      square([x-2*r2, y-2*r2], center=true);
}

module base_bar() {
  cube([W, L, H], center=true);
}

module top_rib() {
  // Overlap slightly into the base so it is unquestionably connected
  translate([0, 0, H/2 + rib_H/2 - overlap])
    cube([rib_W, L, rib_H + 2*overlap], center=true);
}

module bottom_rib() {
  // Overlap slightly into the base so it is unquestionably connected
  translate([0, 0, -H/2 - rib_H/2 + overlap])
    cube([rib_W, L, rib_H + 2*overlap], center=true);
}

module recessed_panel_top() {
  // Cut into the top face (do not reach the rib peak)
  translate([0, 0, H/2 - panel_depth/2 + overlap])
    rounded_rect_prism(
      size=[W - 2*panel_margin_W, L - 2*panel_margin_L, panel_depth + 2*overlap],
      r=recess_corner_r,
      center=true
    );
}

module recessed_panel_bottom() {
  // Cut into the bottom face (do not reach the rib peak)
  translate([0, 0, -H/2 + panel_depth/2 - overlap])
    rounded_rect_prism(
      size=[W - 2*panel_margin_W, L - 2*panel_margin_L, panel_depth + 2*overlap],
      r=recess_corner_r,
      center=true
    );
}

module concave_cutter_top() {
  // Cylinder axis along Y; subtract to create shallow concavity across X on top.
  // Positioned so the cylinder intrudes by arch_sag at the top face (z=+H/2).
  rotate([90, 0, 0])
    translate([0, 0, H/2 + arch_R - arch_sag])
      cylinder(r=arch_R, h=L + 6*overlap, center=true);
}

module concave_cutter_bottom() {
  // Cylinder axis along Y; subtract to create shallow concavity across X on bottom.
  rotate([90, 0, 0])
    translate([0, 0, -H/2 - arch_R + arch_sag])
      cylinder(r=arch_R, h=L + 6*overlap, center=true);
}

module chamfered_box_mask() {
  // Chamfered prism mask (trims edges/corners) using Minkowski with an octahedron.
  ztot = H + 2*rib_H;
  c = chamfer;

  ix = max(eps, W - 2*c);
  iy = max(eps, L - 2*c);
  iz = max(eps, ztot - 2*c);

  minkowski() {
    cube([ix, iy, iz], center=true);
    polyhedron(
      points=[
        [ c, 0, 0], [-c, 0, 0],
        [ 0, c, 0], [ 0,-c, 0],
        [ 0, 0, c], [ 0, 0,-c]
      ],
      faces=[
        [0,2,4],[2,1,4],[1,3,4],[3,0,4],
        [2,0,5],[1,2,5],[3,1,5],[0,3,5]
      ]
    );
  }
}

// ---------- Model ----------
module model() {
  // Build bar + ribs, carve recesses and concavity, then apply chamfer mask.
  intersection() {
    difference() {
      union() {
        base_bar();
        top_rib();
        bottom_rib();
      }

      // Decorative recessed panels on broad faces
      recessed_panel_top();
      recessed_panel_bottom();

      // Shallow concave curvature across width on top/bottom
      // (kept after ribs are added so the rib remains as a central step)
      concave_cutter_top();
      concave_cutter_bottom();
    }

    // Apply chamfer/mitre around the perimeter (including rib height)
    chamfered_box_mask();
  }
}

