elbow_r = 0.03; //[0.015:0.06:0.001]
arm_leg1_len = 0.05; //[0.025:0.1:0.001]
arm_leg2_len = 0.05; //[0.025:0.1:0.001]
end_pad_x = 0.03; //[0.015:0.06:0.001]
end_pad_y = 0.04; //[0.02:0.08:0.001]
end_pad_z = 0.02; //[0.01:0.04:0.001]
