boss1_y = 0.02; //[0.01:0.04:0.001]
boss1_z = 0.01; //[0.005:0.02:0.001]
boss2_x = 0.02; //[0.01:0.04:0.001]
boss2_y = 0.02; //[0.01:0.04:0.001]
boss2_z = 0.01; //[0.005:0.02:0.001]
