// Base rounded rectangle
module base_block_rounded_rect() {
  hull() {
    translate([-base_x/2 + base_corner_r, base_y/2 - base_corner_r, 0])
      cylinder(r=base_corner_r, h=base_z, center=true);
    translate([base_x/2 - base_corner_r, base_y/2 - base_corner_r, 0])
      cylinder(r=base_corner_r, h=base_z, center=true);
    translate([-base_x/2 + base_corner_r, -base_y/2 + base_corner_r, 0])
      cylinder(r=base_corner_r, h=base_z, center=true);
    translate([base_x/2 - base_corner_r, -base_y/2 + base_corner_r, 0])
      cylinder(r=base_corner_r, h=base_z, center=true);
  }
}

// Cantilever arm with elbow
module cantilever_arm() {
  // Arm leg 1
  translate([0, 0, base_z/2 + arm_leg1_len/2 - overlap])
    cube([arm_thk_z, arm_w, arm_leg1_len], center=true);

  // Arm leg 2
  translate([arm_leg2_len/2 - overlap, 0, base_z/2 + arm_leg1_len - arm_thk_z/2])
    cube([arm_leg2_len, arm_w, arm_thk_z], center=true);

  // Elbow
  difference() {
    intersection() {
      translate([0, 0, base_z/2 + arm_leg1_len - elbow_r])
        rotate([90, 0, 0])
        cylinder(r=elbow_r + arm_thk_z/2, h=arm_w, center=true);
      translate([(elbow_r + arm_thk_z)/2 - overlap, 0, base_z/2 + arm_leg1_len - elbow_r + (elbow_r + arm_thk_z)/2 - overlap])
        cube([elbow_r + arm_thk_z, arm_w + 2*overlap, elbow_r + arm_thk_z], center=true);
    }
    translate([0, 0, base_z/2 + arm_leg1_len - elbow_r])
      rotate([90, 0, 0])
      cylinder(r=elbow_r - arm_thk_z/2, h=arm_w + 2*overlap, center=true);
  }
}

// End pad
module end_pad() {
  translate([arm_leg2_len - overlap + end_pad_x/2, 0, base_z/2 + arm_leg1_len - arm_thk_z/2])
    cube([end_pad_x, end_pad_y, end_pad_z], center=true);
}

// Bosses
module bosses() {
  // Boss near junction
  translate([0, 0, base_z/2 + boss1_z/2 - overlap])
    cube([boss1_x, boss1_y, boss1_z], center=true);

  // Boss near end pad
  translate([arm_leg2_len - overlap + end_pad_x/2, 0, base_z/2 + arm_leg1_len - arm_thk_z/2 + end_pad_z/2 - overlap])
    cube([boss2_x, boss2_y, boss2_z], center=true);
}

// Mounting holes
module mounting_holes() {
  translate([-mount_hole_offset_x, 0, 0])
    cylinder(r=mount_hole_r, h=base_z + 2*overlap, center=true);
  translate([mount_hole_offset_x, 0, 0])
    cylinder(r=mount_hole_r, h=base_z + 2*overlap, center=true);
}

// Chamfers
module chamfers() {
  translate([-base_x/2 + chamfer_depth/2, 0, base_z/2 - chamfer_depth/2])
    rotate([0, 45, 0])
    cube([chamfer_depth, base_y + 2*overlap, chamfer_depth], center=true);
  translate([base_x/2 - chamfer_depth/2, 0, base_z/2 - chamfer_depth/2])
    rotate([0, 45, 0])
    cube([chamfer_depth, base_y + 2*overlap, chamfer_depth], center=true);
}

// Final assembly
difference() {
  union() {
    base_block_rounded_rect();
    bosses();
    minkowski() {
      union() {
        cantilever_arm();
        end_pad();
      }
      sphere(r=fillet_r, center=true);
    }
  }
  chamfers();
  mounting_holes();
}

// Faceted lantern/pendant shell with deep cutouts (render-safe, no minkowski)

$fn = 48;

// -------------------- Parameters (mm) --------------------
shell_h = 50;
outer_r = 18;                 // overall "sphere-ish" radius
facet_sides = 8;              // low-poly feel
wall_t = 1.6;

taper_top_r = 16;
taper_bottom_r = 13;

cap_h = 6;
cap_sides = 6;

tip_h = 10;
tip_base_r = 9;

overlap = 0.6;                // boolean overlap (slightly larger for robustness)

// Openings
slot_h = 6;
slot_w = 30;
slot_depth = 44;              // exceed diameter to cut through
slot_z = 0;                   // centered

cutout_count = 6;
cutout_w = 5;
cutout_h = 34;
cutout_depth = 54;
cutout_tilt_deg = 22;

// Grooves (recessed pockets)
groove_w = 2.2;
groove_h = 3.0;
groove_depth = 10;

// Eyelet
eyelet_major_r = 4.2;         // ring centerline radius
eyelet_tube_r  = 1.4;         // ring thickness
eyelet_clear_r = 1.0;         // inner hole radius (subtracted)

// -------------------- Helpers --------------------
module ngon2d(r, n) {
  polygon(points=[for (i=[0:n-1]) [r*cos(360*i/n), r*sin(360*i/n)]]);
}

// Faceted "spherical" body: hull of three thin extrusions (tapered + bulge)
module faceted_body_outer() {
  hull() {
    translate([0,0, shell_h/2 - overlap])
      linear_extrude(height=overlap*2, center=true)
        ngon2d(taper_top_r, facet_sides);

    translate([0,0,-shell_h/2 + overlap])
      linear_extrude(height=overlap*2, center=true)
        ngon2d(taper_bottom_r, facet_sides);

    linear_extrude(height=overlap*2, center=true)
      ngon2d(outer_r, facet_sides);
  }
}

module faceted_body_inner() {
  inner_h = shell_h - 2*wall_t;
  hull() {
    translate([0,0, inner_h/2 - overlap])
      linear_extrude(height=overlap*2, center=true)
        ngon2d(max(taper_top_r - wall_t, 0.2), facet_sides);

    translate([0,0,-inner_h/2 + overlap])
      linear_extrude(height=overlap*2, center=true)
        ngon2d(max(taper_bottom_r - wall_t, 0.2), facet_sides);

    linear_extrude(height=overlap*2, center=true)
      ngon2d(max(outer_r - wall_t, 0.2), facet_sides);
  }
}

module main_shell() {
  difference() {
    faceted_body_outer();
    faceted_body_inner();
  }
}

// -------------------- Add-ons (cap, tip, eyelet) --------------------
module top_polygonal_cap() {
  translate([0,0, shell_h/2 - cap_h/2 - overlap])
    linear_extrude(height=cap_h, center=true)
      ngon2d(taper_top_r*0.92, cap_sides);
}

module bottom_pyramidal_tip() {
  translate([0,0, -shell_h/2 - tip_h/2 + overlap])
    cylinder(h=tip_h, r1=tip_base_r, r2=0, center=true, $fn=cap_sides);
}

module hanging_loop_eyelet() {
  z0 = shell_h/2 + eyelet_tube_r + overlap;
  difference() {
    translate([0,0,z0])
      rotate([90,0,0])
        rotate_extrude($fn=64)
          translate([eyelet_major_r,0,0])
            circle(r=eyelet_tube_r, $fn=24);

    translate([0,0,z0])
      rotate([90,0,0])
        rotate_extrude($fn=64)
          translate([eyelet_major_r,0,0])
            circle(r=eyelet_clear_r, $fn=24);
  }
}

// -------------------- Subtractive openings --------------------
module primary_horizontal_slot_cut() {
  translate([0,0,slot_z])
    cube([slot_w, slot_depth, slot_h], center=true);
}

module vertical_planar_cutouts() {
  union() {
    for (i=[0:cutout_count-1]) {
      ang = i*360/cutout_count;
      rotate([0,0,ang])
        translate([outer_r*0.55, 0, 0])
          cube([cutout_w, cutout_depth, cutout_h], center=true);
    }

    rotate([ cutout_tilt_deg, 0, 30])
      cube([cutout_w, cutout_depth, cutout_h*1.05], center=true);

    rotate([-cutout_tilt_deg, 0, 110])
      cube([cutout_w, cutout_depth, cutout_h*1.05], center=true);
  }
}

module recessed_grooves() {
  union() {
    translate([0,0,-shell_h/2 + tip_h + groove_h/2 + wall_t])
      cube([outer_r*1.6, groove_depth, groove_h], center=true);

    translate([0,0, shell_h/2 - cap_h - groove_h/2 - wall_t])
      cube([outer_r*1.6, groove_depth, groove_h], center=true);

    translate([outer_r*0.75, 0, 0])
      cube([groove_w, outer_r*1.6, cutout_h*0.7], center=true);
  }
}

module all_openings() {
  union() {
    primary_horizontal_slot_cut();
    vertical_planar_cutouts();
    recessed_grooves();
  }
}

// -------------------- Assembly --------------------
module lantern() {
  union() {
    difference() {
      main_shell();
      all_openings();
    }
    top_polygonal_cap();
    bottom_pyramidal_tip();
    hanging_loop_eyelet();
  }
}

// -------------------- Final (no minkowski) --------------------
lantern();

