}

// Assemble the clevis/fork bracket
module clevis_fork_bracket() {
  // Body with rounded end
  union() {
    main_prismatic_body();
    rounded_end_cap();
  }

  // Tine tip rounding
  hull() {
    tine_tip_rounding_left_sphere();
    tine_tip_rounding_left_sphere_back();
  }

  hull() {
    tine_tip_rounding_right_sphere();
    tine_tip_rounding_right_sphere_back();
  }

  // Body with tip rounding
  union() {
    main_prismatic_body();
    rounded_end_cap();
    hull() {
      tine_tip_rounding_left_sphere();
      tine_tip_rounding_left_sphere_back();
    }
    hull() {
      tine_tip_rounding_right_sphere();
      tine_tip_rounding_right_sphere_back();
    }
  }

  // Body minus slot
  difference() {
    union() {
      main_prismatic_body();
      rounded_end_cap();
      hull() {
        tine_tip_rounding_left_sphere();
        tine_tip_rounding_left_sphere_back();
      }
      hull() {
        tine_tip_rounding_right_sphere();
        tine_tip_rounding_right_sphere_back();
      }
    }
    rectangular_through_slot_two_tines();
  }

  // Body minus slot and taper
  difference() {
    difference() {
      union() {
        main_prismatic_body();
        rounded_end_cap();
        hull() {
          tine_tip_rounding_left_sphere();
          tine_tip_rounding_left_sphere_back();
        }
        hull() {
          tine_tip_rounding_right_sphere();
          tine_tip_rounding_right_sphere_back();
        }
      }
      rectangular_through_slot_two_tines();
    }
    chamfered_tapered_end();
  }

  // Body minus hex main
  difference() {
    difference() {
      difference() {
        union() {
          main_prismatic_body();
          rounded_end_cap();
          hull() {
            tine_tip_rounding_left_sphere();
            tine_tip_rounding_left_sphere_back();
          }
          hull() {
            tine_tip_rounding_right_sphere();
            tine_tip_rounding_right_sphere_back();
          }
        }
        rectangular_through_slot_two_tines();
      }
      chamfered_tapered_end();
    }
    transverse_hex_through_hole();
  }

  // Body minus hex with lead-ins
  difference() {
    difference() {
      difference() {
        difference() {
          union() {
            main_prismatic_body();
            rounded_end_cap();
            hull() {
              tine_tip_rounding_left_sphere();
              tine_tip_rounding_left_sphere_back();
            }
            hull() {
              tine_tip_rounding_right_sphere();
              tine_tip_rounding_right_sphere_back();
            }
          }
          rectangular_through_slot_two_tines();
        }
        chamfered_tapered_end();
      }
      transverse_hex_through_hole();
    }
    small_lead_in_chamfers_on_hole_left();
    small_lead_in_chamfers_on_hole_right();
  }

  // Edge fillets
  minkowski() {
    difference() {
      difference() {
        difference() {
          difference() {
            union() {
              main_prismatic_body();
              rounded_end_cap();
              hull() {
                tine_tip_rounding_left_sphere();
                tine_tip_rounding_left_sphere_back();
              }
              hull() {
                tine_tip_rounding_right_sphere();
                tine_tip_rounding_right_sphere_back();
              }
            }
            rectangular_through_slot_two_tines();
          }
          chamfered_tapered_end();
        }
        transverse_hex_through_hole();
      }
      small_lead_in_chamfers_on_hole_left();
      small_lead_in_chamfers_on_hole_right();
    }
    edge_fillets_sphere();
  }
}

// Render the final clevis/fork bracket
clevis_fork_bracket();

// L-shaped right-angle mounting bracket with flange/lip, internal fillet, rounded outer corners,
// bend relief, and one through-hole in the upright leg.
// Bounding box target: 0.1 x 0.1 x 0.1 mm

$fn = 96;

// ---------------- Parameters (mm) ----------------
bbox_X = 0.10;
bbox_Y = 0.10;
bbox_Z = 0.10;

plate_t = 0.012;

base_Lx = 0.090;
base_Ly = 0.090;

upright_Lx = 0.090;
upright_Hz = 0.080;

fillet_r = 0.020;

hole_d = 0.012;
hole_center_from_top  = 0.025;  // from top edge of upright down
hole_center_from_side = 0.045;  // from left edge of upright in +X

flange_w = 0.012;
flange_t_add = 0.006;

outer_corner_r = 0.004;

bevel_L = 0.020;
bevel_depth = 0.006;

eps = 0.0005;

// Slight overlap for robust unions (scaled to this tiny model)
overlap = 0.0015; // ensures parts touch/merge

// ---------------- Helpers ----------------
module rounded_box(size=[10,10,10], r=1, center=true) {
    sx = size[0]; sy = size[1]; sz = size[2];
    rr = max(0, min(r, sx/2 - eps, sy/2 - eps, sz/2 - eps));
    hull() {
        for (x = [-1, 1], y = [-1, 1], z = [-1, 1])
            translate([x*(sx/2-rr), y*(sy/2-rr), z*(sz/2-rr)])
                sphere(r=rr);
    }
}

// ---------------- Parts ----------------
module base_plate() {
    // Base lies in XY, thickness in Z, bottom at Z=0
    translate([0, 0, plate_t/2])
        rounded_box([base_Lx, base_Ly, plate_t], r=outer_corner_r, center=true);
}

module upright_plate() {
    // Upright lies in XZ, thickness in Y.
    // Place it so its bottom sits on the base top (Z=plate_t) with overlap,
    // and its back face aligns to the base -Y edge (Y=-base_Ly/2) with overlap.
    y_center = -base_Ly/2 + (plate_t + overlap)/2;
    z_center = plate_t + upright_Hz/2 - overlap/2;

    translate([0, y_center, z_center])
        rounded_box([upright_Lx, plate_t + overlap, upright_Hz + overlap], r=outer_corner_r, center=true);
}

module internal_fillet() {
    // Large internal fillet at inside corner between:
    // - base top surface at Z=plate_t
    // - upright inner face at Y=-base_Ly/2 + plate_t
    // Create a quarter-cylinder (along X) and clip to the inside corner region.
    y0 = -base_Ly/2 + plate_t; // inside face of upright (toward +Y)
    z0 = plate_t;              // top face of base

    intersection() {
        // Cylinder along X, positioned so its tangent planes are at y=y0 and z=z0
        translate([0, y0 + fillet_r, z0 + fillet_r])
            rotate([0, 90, 0])
                cylinder(r=fillet_r, h=upright_Lx + 2*overlap, center=true);

        // Clip to the quarter region and slightly intrude into both plates for a solid merge
        translate([0, y0 + fillet_r/2 - overlap/2, z0 + fillet_r/2 - overlap/2])
            cube([upright_Lx + 2*overlap, fillet_r + overlap, fillet_r + overlap], center=true);
    }
}

module flange_lip() {
    // Thickened flange along one edge of base (positive Y edge).
    // Overlap slightly into the base so it is definitely connected.
    y_center = base_Ly/2 - (flange_w + overlap)/2;
    z_center = (plate_t + flange_t_add)/2;

    translate([0, y_center, z_center])
        rounded_box([base_Lx, flange_w + overlap, plate_t + flange_t_add], r=outer_corner_r, center=true);
}

module bend_relief_cut() {
    // Small beveled/relieved region near the bend on the inside corner.
    // Cut a rotated wedge that intersects both the base top and upright inner face.
    y0 = -base_Ly/2 + plate_t;
    z0 = plate_t;

    // Center the wedge right at the inside corner; ensure it reaches into both plates.
    translate([0, y0 + bevel_depth/2, z0 + bevel_depth/2])
        rotate([0, 0, 45])
            cube([bevel_L, bevel_depth*1.8, bevel_depth*1.8], center=true);
}

module through_hole_cut() {
    // Through-hole in upright leg (through Y thickness), explicitly located on upright.
    hole_x = -upright_Lx/2 + hole_center_from_side;
    hole_z = (plate_t + upright_Hz) - hole_center_from_top; // upright top is at plate_t+upright_Hz

    // Upright Y center matches upright_plate()
    y_center = -base_Ly/2 + (plate_t + overlap)/2;

    translate([hole_x, y_center, hole_z])
        rotate([90, 0, 0])
            cylinder(d=hole_d, h=(plate_t + overlap) + 10*eps, center=true);
}

// ---------------- Model ----------------
module bracket_solid() {
    union() {
        base_plate();
        upright_plate();
        internal_fillet();
        flange_lip();
    }
}

module complete_model() {
    difference() {
        bracket_solid();
        bend_relief_cut();
        through_hole_cut();
    }
}

// ---------------- Fit to bounding box ----------------
// Keep the part within bbox_Z by shifting in Z only (X/Y already centered).
z_max = max(plate_t + upright_Hz, plate_t + flange_t_add);
z_shift = (bbox_Z/2) - (z_max/2) - eps;

color("Silver")
translate([0, 0, z_shift])
    complete_model();

// Flat circular disk with thick outer rim, recessed inner face,
// five octagonal through-holes on a bolt circle, and a central square through-hole.

// ---------------- Parameters (meters) ----------------
D = 0.04;                 //[0.02:0.08:0.001] overall diameter
T = 0.01;                 //[0.005:0.02:0.001] overall thickness
rim_radial_w = 0.006;     //[0.003:0.012:0.001] rim radial width
pocket_depth = 0.003;     //[0.001:0.006:0.001] recess depth from top face
bolt_circle_d = 0.022;    //[0.011:0.044:0.001] bolt circle diameter
oct_hole_flat_d = 0.006;  //[0.003:0.012:0.001] octagon across flats
center_square_w = 0.004;  //[0.002:0.008:0.001] center square width
oct_hole_count = 5;       //[3:12:1]
oct_hole_rotation_deg = 0;//[-180:180:1]
eps_overlap = 0.001;      //[0.0005:0.002:0.0005]

// ---------------- Derived ----------------
R = D/2;
inner_R = max(0.001, R - rim_radial_w);
pocket_depth_clamped = min(pocket_depth, T - 2*eps_overlap);

// ---------------- Helpers ----------------
module octagon_2d(across_flats) {
    // Regular octagon with given across-flats dimension.
    // For a regular n-gon, apothem a = across_flats/2, circumradius r = a / cos(180/n).
    n = 8;
    a = across_flats/2;
    r = a / cos(180/n);
    polygon(points=[ for (i=[0:n-1]) [ r*cos(i*360/n), r*sin(i*360/n) ] ]);
}

module oct_hole_at(x, y, rot=0) {
    translate([x, y, 0])
        rotate([0, 0, rot])
            linear_extrude(height=T + 2*eps_overlap, center=true)
                octagon_2d(oct_hole_flat_d);
}

module all_through_holes() {
    union() {
        // Central square through-hole
        cube([center_square_w, center_square_w, T + 2*eps_overlap], center=true);

        // Octagonal holes on bolt circle
        for (i = [0:oct_hole_count-1]) {
            ang = i * 360 / oct_hole_count + oct_hole_rotation_deg;
            x = (bolt_circle_d/2) * cos(ang);
            y = (bolt_circle_d/2) * sin(ang);
            oct_hole_at(x, y, ang);
        }
    }
}

// ---------------- Model ----------------
module disk_with_recess_and_holes() {
    difference() {
        // Base disk (axially symmetric)
        cylinder(h=T, r=R, center=true, $fn=180);

        // Recessed inner pocket from the TOP face only (leaves thick outer rim)
        // Pocket occupies z in [T/2 - pocket_depth, T/2]
        translate([0, 0, T/2 - pocket_depth_clamped/2 + eps_overlap/2])
            cylinder(h=pocket_depth_clamped + eps_overlap, r=inner_R, center=true, $fn=180);

        // Through-holes
        all_through_holes();
    }
}

// Final output: one connected solid
disk_with_recess_and_holes();

// Low-poly armored vehicle / tank-like model
// Fixes:
// - Ensures visible geometry (no degenerate/near-zero dimensions)
// - Adds TWO large cylindrical end pods clearly at both ends
// - Ensures ONE connected solid via calculated placements + small overlaps
// - Keeps elongated along X axis
// Note: A true 0.0mm bounding-box dimension is impossible for a solid; model has non-zero thickness.

// -------------------- Parameters (mm) --------------------
bbox_L = 0.1;
bbox_W = 0.1;
bbox_H = 0.04;          // non-zero thickness required for a solid

hull_L = 0.072;
hull_W = 0.030;
hull_H = 0.018;

pod_R = 0.015;          // large end pods
pod_L = 0.022;
pod_overlap_into_hull = 0.004;  // how much pod intrudes into hull for connectivity

turret_L = 0.040;
turret_W = 0.026;
turret_H = 0.014;

barrel_R = 0.004;
barrel_L = 0.018;

fin_L = 0.012;
fin_T = 0.003;
fin_H = 0.006;
fin_x_pos = 0.0;

overlap = 0.001;

chamfer_T = 0.003;

panel_T = 0.0012;
greeble_R = 0.0012;
greeble_H = 0.002;

antenna_R = 0.001;
antenna_H = 0.01;

// -------------------- Helpers --------------------
module clamp_bbox() {
  // Scale the whole model to fit within bbox_L x bbox_W x bbox_H
  // Compute current extents conservatively from parameters.
  // X extent includes barrel.
  cur_L = max(hull_L + 2*pod_R, hull_L + barrel_L); // conservative
  cur_W = max(hull_W, 2*pod_R, turret_W);
  cur_H = max(hull_H + turret_H + antenna_H, 2*pod_R);

  s = min(bbox_L/cur_L, bbox_W/cur_W, bbox_H/cur_H);
  scale([s, s, s]) children();
}

// -------------------- Base Shapes --------------------
module hull_main() {
  cube([hull_L, hull_W, hull_H], center=true);
}

module end_pod_raw() {
  // Cylinder axis along X
  rotate([0, 90, 0])
    cylinder(r=pod_R, h=pod_L, center=true, $fn=18);
}

module turret_roof() {
  // Faceted trapezoid roof, extruded in Z
  linear_extrude(height=turret_H, center=true, convexity=10)
    polygon(points=[
      [-turret_L/2, -turret_W/2],
      [ turret_L/2, -turret_W/2],
      [ turret_L/2 - turret_L*0.18,  turret_W/2],
      [-turret_L/2 + turret_L*0.18,  turret_W/2]
    ]);
}

module barrel_raw() {
  rotate([0, 90, 0])
    cylinder(r=barrel_R, h=barrel_L, center=true, $fn=16);
}

module fin_raw() {
  // Thin fin plate extruded in Z; will be rotated to stick out sideways
  linear_extrude(height=fin_T, center=true, convexity=10)
    polygon(points=[
      [-fin_L/2, 0],
      [ fin_L/2, 0],
      [ fin_L/2 - fin_L*0.35, fin_H],
      [-fin_L/2 + fin_L*0.15, fin_H*0.75]
    ]);
}

module chamfer_cut() {
  cube([chamfer_T, hull_W + overlap*4, hull_H/2 + overlap*2], center=true);
}

module panel_facet_top() {
  cube([hull_L*0.55, hull_W*0.65, panel_T], center=true);
}

module panel_facet_front() {
  rotate([0, 0, 90])
    cube([hull_L*0.18, hull_W*0.55, panel_T], center=true);
}

module surface_greeble() {
  cylinder(r=greeble_R, h=greeble_H, center=true, $fn=14);
}

module antenna_stub_raw() {
  cylinder(r=antenna_R, h=antenna_H, center=true, $fn=12);
}

// -------------------- Operations / Placement --------------------
module end_pod_front() {
  // Place so pod overlaps into hull by pod_overlap_into_hull
  // Pod center at: hull end + pod half - overlap_into_hull
  translate([ hull_L/2 + pod_L/2 - pod_overlap_into_hull, 0, 0 ])
    end_pod_raw();
}

module end_pod_rear() {
  translate([ -(hull_L/2 + pod_L/2 - pod_overlap_into_hull), 0, 0 ])
    end_pod_raw();
}

module turret_roof_pos() {
  translate([0, 0, hull_H/2 + turret_H/2 - overlap])
    turret_roof();
}

module barrel() {
  // Barrel protrudes from FRONT pod/hull end; ensure it intersects pod slightly
  // Front-most solid is pod front face at: (hull_L/2 + pod_L - pod_overlap_into_hull)
  front_face_x = hull_L/2 + pod_L - pod_overlap_into_hull;
  translate([ front_face_x + barrel_L/2 - overlap, 0, hull_H/2 + turret_H*0.25 ])
    barrel_raw();
}

module left_fin() {
  // Rotate so fin extrude thickness (Z) becomes lateral thickness (Y)
  translate([fin_x_pos, hull_W/2 + fin_T/2 - overlap, -hull_H*0.05])
    rotate([90, 0, 0])
      fin_raw();
}

module right_fin() {
  translate([fin_x_pos, -(hull_W/2 + fin_T/2 - overlap), -hull_H*0.05])
    rotate([-90, 0, 0])
      fin_raw();
}

module chamfer_cut_front_top_pos() {
  translate([ hull_L/2 - chamfer_T/2 + overlap, 0, hull_H/2 - hull_H/4 ])
    rotate([0, 45, 0])
      chamfer_cut();
}

module chamfer_cut_rear_top_pos() {
  translate([ -(hull_L/2 - chamfer_T/2 + overlap), 0, hull_H/2 - hull_H/4 ])
    rotate([0, -45, 0])
      chamfer_cut();
}

module hull_chamfers() {
  difference() {
    hull_main();
    chamfer_cut_front_top_pos();
    chamfer_cut_rear_top_pos();
  }
}

module panel_facet_top_pos() {
  translate([0, 0, hull_H/2 + panel_T/2 - overlap])
    panel_facet_top();
}

module panel_facet_front_pos() {
  translate([hull_L*0.22, 0, hull_H*0.05])
    panel_facet_front();
}

module surface_greeble_1_pos() {
  translate([-hull_L*0.12, hull_W*0.18, hull_H/2 + greeble_H/2 - overlap])
    surface_greeble();
}

module surface_greeble_2_pos() {
  translate([hull_L*0.08, -hull_W*0.22, hull_H/2 + greeble_H/2 - overlap])
    surface_greeble();
}

module antenna_stub() {
  translate([-turret_L*0.18, turret_W*0.18, hull_H/2 + turret_H - overlap + antenna_H/2])
    antenna_stub_raw();
}

// -------------------- Final Vehicle Model --------------------
module vehicle_union_main() {
  union() {
    hull_chamfers();

    // Two large cylindrical end pods (clearly present)
    end_pod_front();
    end_pod_rear();

    // Faceted turret/roof
    turret_roof_pos();

    // Barrel protruding from one end
    barrel();

    // Lateral fins/winglets
    left_fin();
    right_fin();

    // Surface facets / greebles (kept connected via overlap)
    panel_facet_top_pos();
    panel_facet_front_pos();
    surface_greeble_1_pos();
    surface_greeble_2_pos();

    // Antenna
    antenna_stub();
  }
}

// Render (scaled to requested bbox limits as closely as possible)
clamp_bbox() vehicle_union_main();

// Parameters
bbox_x = 0.08; //[0.04:0.16:0.001]
bbox_y = 0.06; //[0.03:0.12:0.001]
thickness_z = 0.04; //[0.02:0.08:0.001]
