    polygon(points=[
      [-bbox_x/2 + outline_margin_x, 0],
      [-bbox_x/2 + outline_margin_x + small_lobe_len_x*0.25, neck_min_width_y*0.50],
      [-bbox_x/2 + outline_margin_x + small_lobe_len_x*0.75, neck_min_width_y*0.50],
