// Compact symmetric bracket-like block with wedge wings, stepped pockets/slots,
// diamond through-holes on wings, and a V-notch along one edge.
// Scaled small but non-zero so geometry renders robustly.

$fn = 48;

// -------------------- Parameters --------------------
bb_x = 0.07;
bb_y = 0.05;
bb_z = 0.04;

body_x = 0.032;
body_y = 0.028;
body_z = bb_z;

wing_span_x_each = (bb_x - body_x)/2;          // overall X matches bb_x
wing_flare_y_at_body = body_y;
wing_flare_y_at_tip  = bb_y;
wing_z = bb_z;

step1_depth_z = 0.008;
step1_x = 0.024;
step1_y = 0.020;

step2_depth_z = 0.006;
step2_x = 0.018;
step2_y = 0.014;

slot_w = 0.004;
slot_l = 0.014;
slot_depth_z = 0.010;
slot_spacing_x = 0.006;

v_notch_depth_x = 0.010;
v_notch_opening_y = 0.016;

diamond_hole_flat = 0.004;
diamond_hole_angle_deg = 45;
diamond_hole_offset_x_from_center = body_x/2 + wing_span_x_each*0.62; // on wing region
diamond_hole_offset_y = bb_y*0.28;

pocket_depth_z = 0.004;

eps = 0.001;                 // increased for robust booleans at tiny scale
cut_through = bb_z + 4*eps;

// -------------------- Helpers --------------------
module wing_wedge(sign=1) {
    // Build wedge in +X, then mirror for left side to avoid self-crossing polygons.
    // Attached to body with slight overlap.
    if (sign < 0) {
        mirror([1,0,0]) wing_wedge(1);
    } else {
        translate([body_x/2 - eps, 0, 0])
            linear_extrude(height=wing_z, center=true)
                polygon(points=[
                    [0, -wing_flare_y_at_body/2],
                    [wing_span_x_each, -wing_flare_y_at_tip/2],
                    [wing_span_x_each,  wing_flare_y_at_tip/2],
                    [0,  wing_flare_y_at_body/2]
                ]);
    }
}

module base_solid() {
    union() {
        cube([body_x, body_y, body_z], center=true);
        wing_wedge(-1);
        wing_wedge(+1);
    }
}

// Stepped recesses on the TOP face (subtract)
module top_step_recesses() {
    translate([0, 0, body_z/2 - step1_depth_z/2 + eps])
        cube([step1_x, step1_y, step1_depth_z + 2*eps], center=true);

    translate([0, 0, body_z/2 - step1_depth_z - step2_depth_z/2 + eps])
        cube([step2_x, step2_y, step2_depth_z + 2*eps], center=true);
}

// Three rectangular slots/pockets on the TOP face (subtract)
module top_slots() {
    for (sx = [-slot_spacing_x, 0, slot_spacing_x]) {
        translate([sx, 0, body_z/2 - slot_depth_z/2 + eps])
            cube([slot_l, slot_w, slot_depth_z + 2*eps], center=true);
    }
}

// Additional small bottom pocket (subtract)
module bottom_pocket() {
    translate([0, 0, -body_z/2 + pocket_depth_z/2 - eps])
        cube([step2_x*0.55, step2_y*0.55, pocket_depth_z + 2*eps], center=true);
}

// V-notch along the +X outer edge (subtract), visible in top/bottom views
module v_notch() {
    // Use a centered 2D triangle and place it so its left edge sits on +X outer face.
    translate([bb_x/2 - v_notch_depth_x/2, 0, 0])
        linear_extrude(height=cut_through, center=true)
            polygon(points=[
                [-v_notch_depth_x/2, -v_notch_opening_y/2],
                [ v_notch_depth_x/2,  0],
                [-v_notch_depth_x/2,  v_notch_opening_y/2]
            ]);
}

// Diamond/square through-holes on wing regions (subtract)
module diamond_holes() {
    for (sx = [-1, 1]) {
        translate([sx*diamond_hole_offset_x_from_center, sx*diamond_hole_offset_y, 0])
            rotate([0, 0, diamond_hole_angle_deg])
                cube([diamond_hole_flat, diamond_hole_flat, cut_through], center=true);
    }
}

// -------------------- Final Model --------------------
difference() {
    base_solid();

    top_step_recesses();
    top_slots();
    bottom_pocket();
    v_notch();
    diamond_holes();
}

// Handwheel / hub with rim, 4 curved rectangular cutouts, raised hub, hex through-bore, and short post
// Units: mm

$fn = 128;

// -------------------- Parameters --------------------
disk_D = 30;
disk_t = 12;

rim_radial_w = 3;     // radial thickness of rim ring
rim_extra_t  = 4;     // extra thickness on one face (top)

hub_D = 14;
hub_h = 4;

post_D = 8;
post_h = 4;

hex_flat_AF = 6;      // across flats

cutout_count = 4;
cutout_len_tangential = 8;
cutout_w_radial = 3;
cutout_depth_z = 20;  // must exceed total thickness to guarantee through-cut
cutout_corner_r = 1;

cutout_radial_pos = (disk_D/2 - rim_radial_w/2); // near perimeter, centered in rim

overlap = 0.2;        // small overlap to ensure watertight unions/differences

// -------------------- Helpers --------------------
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for a regular hex given across-flats

module rounded_rect_2d(w, h, r) {
  r2 = min(r, min(w, h)/2);
  hull() {
    translate([ w/2 - r2,  h/2 - r2]) circle(r=r2);
    translate([-w/2 + r2,  h/2 - r2]) circle(r=r2);
    translate([-w/2 + r2, -h/2 + r2]) circle(r=r2);
    translate([ w/2 - r2, -h/2 + r2]) circle(r=r2);
  }
}

module hex_prism_through(h) {
  R = hex_R_from_AF(hex_flat_AF);
  linear_extrude(height=h, center=true)
    polygon(points=[ for(i=[0:5]) [ R*cos(60*i), R*sin(60*i) ] ]);
}

// -------------------- Main solids --------------------
module base_disk() {
  cylinder(r=disk_D/2, h=disk_t, center=true);
}

module top_rim_ring() {
  // ring sits on top face of disk
  zc = disk_t/2 + rim_extra_t/2 - overlap;
  difference() {
    translate([0,0,zc]) cylinder(r=disk_D/2, h=rim_extra_t, center=true);
    translate([0,0,zc]) cylinder(r=disk_D/2 - rim_radial_w, h=rim_extra_t + 2*overlap, center=true);
  }
}

module raised_hub() {
  zc = disk_t/2 + hub_h/2 - overlap;
  translate([0,0,zc]) cylinder(r=hub_D/2, h=hub_h, center=true);
}

module bottom_post() {
  zc = -disk_t/2 - post_h/2 + overlap;
  translate([0,0,zc]) cylinder(r=post_D/2, h=post_h, center=true);
}

module curved_cutout() {
  // A rounded rectangle placed tangentially, then slightly curved by intersecting with an annulus sector
  // (keeps it "curved rectangular" near the perimeter)
  zc = 0;
  translate([0,0,zc])
    linear_extrude(height=cutout_depth_z, center=true)
      intersection() {
        // rounded rectangle in local coordinates
        translate([cutout_radial_pos, 0, 0])
          rounded_rect_2d(cutout_w_radial, cutout_len_tangential, cutout_corner_r);

        // annulus band to impart curvature (keeps cutout near rim)
        difference() {
          circle(r=disk_D/2 - rim_radial_w*0.15);
          circle(r=disk_D/2 - rim_radial_w*1.85);
        }
      }
}

module all_cutouts() {
  for (i = [0:cutout_count-1])
    rotate([0,0,i*360/cutout_count]) curved_cutout();
}

// -------------------- Final model --------------------
module model() {
  total_h = disk_t + rim_extra_t + hub_h + post_h + 10;

  difference() {
    union() {
      base_disk();
      top_rim_ring();
      raised_hub();
      bottom_post();
    }

    // four perimeter cutouts
    all_cutouts();

    // through hex bore
    hex_prism_through(total_h);
  }
}

model();

// Prismatic stepped L-shaped block with large side notch + rear U-pocket (forked), with chamfers
// Bounding box enforced: 0.1 x 0.1 x 0.1 mm

$fn = 48;

// ---------- Global ----------
bbox = [0.1, 0.1, 0.1];   // X,Y,Z (mm)
eps  = 0.0005;           // small overlap to avoid coincident faces

X = bbox[0];
Y = bbox[1];
Z = bbox[2];

// ---------- Primary proportions (kept within bbox) ----------
leg_w = 0.045;           // X thickness of vertical leg
arm_d = 0.040;           // Y thickness of horizontal arm

// Step feature (small ledge on the inside corner)
step_w = 0.018;          // X extent
step_d = 0.018;          // Y extent
step_h = 0.030;          // Z extent

// Side rectangular notch (large cutout on one side) - cut from +Y side
notch_w = 0.040;         // X
notch_d = 0.030;         // Y depth from +Y
notch_h = 0.060;         // Z
notch_x0 = 0.020;        // start X from -X face
notch_z0 = 0.020;        // start Z from -Z face

// Rear U-shaped recess (visible from back, forked pocket) - open to -Y
u_w    = 0.060;          // X overall pocket width
u_d    = 0.030;          // Y depth from -Y face
u_h    = 0.060;          // Z height
u_x0   = 0.015;          // start X from -X face
u_z0   = 0.020;          // start Z from -Z face
u_wall = 0.010;          // side wall thickness (fork tines)
u_floor= 0.010;          // bottom thickness inside pocket

// Chamfers
ch_ext = 0.006;          // external chamfer size
ch_int = 0.006;          // internal chamfer size

// ---------- Helpers ----------
module chamfer_wedge_Z(size, zspan, corner=[1,1]) {
    // corner: [sx,sy] where sx,sy are +1 or -1 indicating which XY corner
    sx = corner[0];
    sy = corner[1];
    linear_extrude(height=zspan, center=true)
        polygon(points=[
            [0,0],
            [sx*size,0],
            [0,sy*size]
        ]);
}

module chamfer_wedge_X(size, xspan, corner=[1,1]) {
    // corner: [sy,sz] in YZ plane
    sy = corner[0];
    sz = corner[1];
    rotate([0,90,0])
        linear_extrude(height=xspan, center=true)
            polygon(points=[
                [0,0],
                [sy*size,0],
                [0,sz*size]
            ]);
}

// ---------- Base solid (connected) ----------
module base_L() {
    union() {
        // Vertical leg: X in [-X/2, -X/2+leg_w], full Y, full Z
        translate([-X/2 + leg_w/2, 0, 0])
            cube([leg_w, Y, Z], center=true);

        // Horizontal arm: full X, Y in [-Y/2, -Y/2+arm_d], full Z
        translate([0, -Y/2 + arm_d/2, 0])
            cube([X, arm_d, Z], center=true);

        // Step/ledge near inside corner (adds a small boss)
        // Ensure it actually intersects both leg and arm with a tiny overlap (eps)
        translate([
            (-X/2 + leg_w) + step_w/2 - eps,
            (-Y/2 + arm_d) + step_d/2 - eps,
            -Z/2 + step_h/2
        ])
            cube([step_w + 2*eps, step_d + 2*eps, step_h], center=true);
    }
}

// ---------- Cuts ----------
module side_notch_cut() {
    // Cut from +Y side into the part (clearly side-opening)
    // Place so its +Y face is slightly beyond +Y/2 to guarantee opening.
    translate([
        -X/2 + notch_x0 + notch_w/2,
        (Y/2) - (notch_d/2) + eps,
        -Z/2 + notch_z0 + notch_h/2
    ])
        cube([notch_w, notch_d + 2*eps, notch_h], center=true);
}

module rear_U_fork_cut() {
    // Create a forked U-pocket open to -Y by subtracting:
    // 1) an outer pocket volume (opens to -Y)
    // 2) an inner slot volume (leaves two tines + a floor)
    x_c = -X/2 + u_x0 + u_w/2;
    y_c = -Y/2 + u_d/2 - eps;   // pushes slightly out of -Y face to ensure opening
    z_c = -Z/2 + u_z0 + u_h/2;

    // Outer pocket volume
    translate([x_c, y_c, z_c])
        cube([u_w, u_d + 2*eps, u_h], center=true);

    // Inner slot (removes center, leaving fork tines and floor)
    // Make it slightly deeper to avoid coplanar faces with outer pocket.
    translate([x_c, y_c - eps, z_c + u_floor/2])
        cube([u_w - 2*u_wall, u_d + 4*eps, u_h - u_floor], center=true);
}

module internal_chamfer_cut() {
    // Chamfer an internal corner of the inner slot (machined detail).
    // Target: inside top-back corner of the inner slot (open side is -Y),
    // so chamfer at Y = (-Y/2 + u_d) and Z = (-Z/2 + u_z0 + u_h).
    xspan = (u_w - 2*u_wall) + 2*eps;

    x_c    = -X/2 + u_x0 + u_w/2;
    y_back = (-Y/2 + u_d) - eps;          // back wall of pocket (inside)
    z_top  = (-Z/2 + u_z0 + u_h) - eps;   // top of pocket

    translate([x_c, y_back, z_top])
        chamfer_wedge_X(ch_int, xspan, corner=[-1,-1]);
}

module external_chamfers_cut() {
    zspan = Z + 2*eps;

    // XY vertical edge breaks (all four outer corners)
    translate([ X/2,  Y/2, 0]) chamfer_wedge_Z(ch_ext, zspan, corner=[-1,-1]);
    translate([-X/2,  Y/2, 0]) chamfer_wedge_Z(ch_ext, zspan, corner=[ 1,-1]);
    translate([ X/2, -Y/2, 0]) chamfer_wedge_Z(ch_ext, zspan, corner=[-1, 1]);
    translate([-X/2, -Y/2, 0]) chamfer_wedge_Z(ch_ext, zspan, corner=[ 1, 1]);
}

module top_edge_break_cut() {
    // Break along top front edge (Y = +Y/2, Z = +Z/2), spanning full X
    xspan = X + 2*eps;
    translate([0, Y/2, Z/2])
        chamfer_wedge_X(ch_ext, xspan, corner=[-1,-1]);
}

// ---------- Final model ----------
difference() {
    base_L();

    // Primary cuts (side notch + rear forked U-pocket)
    side_notch_cut();
    rear_U_fork_cut();

    // Chamfers
    internal_chamfer_cut();
    external_chamfers_cut();
    top_edge_break_cut();
}

// Thin faceplate with rounded-rect plate, 4 corner holes,
// 2 opposite diamond tabs with holes, and a raised octagonal bezel
// around a recessed rectangular pocket.
//
// Bounding box target: 0.2 x 0.3 x ~0 (very thin / plate-like)

$fn = 64;

// --- Target overall size (X x Y) ---
L = 0.30;          // overall length (X)
W = 0.20;          // overall width  (Y)

// --- Thicknesses (keep very thin) ---
T = 0.004;         // base plate thickness (near-zero but renderable)
bezel_h = 0.002;   // raised bezel height above plate
pocket_depth = 0.002; // recessed pocket depth into plate

// --- Plate corner rounding ---
corner_r = 0.015;

// --- Corner fastener holes ---
hole_d = 0.010;
hole_edge_offset_L = 0.025;  // from left/right edges
hole_edge_offset_W = 0.020;  // from top/bottom edges

// --- Diamond tabs (on midpoints of two opposite sides: +/-Y) ---
tab_out = 0.020;        // how far tab protrudes beyond plate edge (Y direction)
tab_half_width = 0.020; // half width of diamond (X direction)
tab_thickness = T;      // same as plate thickness
tab_hole_d = 0.010;

// --- Central bezel (octagon) and pocket ---
bezel_flat_to_flat = 0.090; // outer octagon flat-to-flat
bezel_wall = 0.010;         // ring wall thickness (flat-to-flat difference/2 approx)
pocket_L = 0.090;
pocket_W = 0.050;

eps = 0.0005;

// ---------- Helpers ----------
function clamp(x,a,b) = x < a ? a : (x > b ? b : x);

// Regular octagon points for a given circumradius
module octagon_2d(R){
    polygon(points=[
        [ R, 0],
        [ R*0.70710678,  R*0.70710678],
        [ 0,  R],
        [-R*0.70710678,  R*0.70710678],
        [-R, 0],
        [-R*0.70710678, -R*0.70710678],
        [ 0, -R],
        [ R*0.70710678, -R*0.70710678]
    ]);
}

// Rounded rectangle 2D (robust, no skew/chamfer artifacts)
module rounded_rect_2d(l, w, r){
    r2 = clamp(r, 0, min(l,w)/2 - eps);
    hull(){
        for (sx=[-1,1], sy=[-1,1])
            translate([sx*(l/2 - r2), sy*(w/2 - r2)])
                circle(r=r2);
    }
}

// Diamond tab 2D (pointing outward in +Y by default)
module diamond_2d(half_w, out){
    polygon(points=[
        [ half_w, 0],
        [ 0, out],
        [-half_w, 0],
        [ 0,-out]
    ]);
}

// ---------- Main solids ----------
module plate_with_tabs_solid(){
    union(){
        // Main rounded rectangle plate
        linear_extrude(height=T, center=true)
            rounded_rect_2d(L, W, corner_r);

        // Two opposite diamond tabs centered on midpoints of +/-Y sides
        // Place so inner diamond vertex slightly overlaps plate edge for connectivity.
        tab_center_y = W/2 + tab_out/2 - eps;

        for (sy=[-1,1])
            translate([0, sy*tab_center_y, 0])
                linear_extrude(height=tab_thickness, center=true)
                    diamond_2d(tab_half_width, tab_out);
    }
}

module all_through_holes_cut(){
    union(){
        // 4 corner holes (near corners of the rounded rectangle)
        xh = L/2 - hole_edge_offset_L;
        yh = W/2 - hole_edge_offset_W;

        for (sx=[-1,1], sy=[-1,1])
            translate([sx*xh, sy*yh, 0])
                cylinder(d=hole_d, h=T + 6*eps, center=true);

        // Tab holes (centered in each diamond tab)
        tab_center_y = W/2 + tab_out/2 - eps;
        for (sy=[-1,1])
            translate([0, sy*tab_center_y, 0])
                cylinder(d=tab_hole_d, h=T + 6*eps, center=true);
    }
}

module bezel_ring_solid(){
    // Convert flat-to-flat to circumradius: R = (flat/2)/cos(22.5°)
    // cos(22.5)=0.9238795325
    outer_R = (bezel_flat_to_flat/2) / 0.9238795325;
    inner_flat = bezel_flat_to_flat - 2*bezel_wall;
    inner_R = ((inner_flat/2) / 0.9238795325);

    translate([0,0, T/2 + bezel_h/2 - eps])  // sit on top of plate with slight overlap
    linear_extrude(height=bezel_h, center=true)
        difference(){
            octagon_2d(outer_R);
            octagon_2d(inner_R);
        }
}

module pocket_cut(){
    // Recessed rectangular pocket inside the bezel (cut down from top surface)
    // Ensure it doesn't cut through the whole plate.
    d = clamp(pocket_depth, eps, T - eps);

    translate([0,0, T/2 - d/2 + eps])
        cube([pocket_L, pocket_W, d + 4*eps], center=true);
}

// ---------- Final ----------
difference(){
    union(){
        difference(){
            plate_with_tabs_solid();
            all_through_holes_cut();
        }
        bezel_ring_solid();
    }
    pocket_cut();
}

// Thin elongated plate with rounded ends, one large octagonal through-hole near one end,
// and four evenly spaced T-shaped through-slots along the centerline.

// ---------- Parameters (mm) ----------
L = 0.11;                 // overall length
W = 0.04;                 // overall width
T = 0.01;                 // thickness (plate-like)
end_r = W/2;              // capsule ends (true rounded ends)

hole_flat_d = 0.02;       // octagon "across flats" diameter
hole_sides = 8;           // octagon
hole_offset_from_end = 0.022; // from LEFT end to hole center along X (kept consistent)

t_count = 4;
t_pitch = 0.018;          // spacing between T-slot centers
t_stem_w = 0.006;
t_stem_l = 0.012;
t_head_w = 0.018;
t_head_l = 0.006;

t_centerline_y = 0.0;
slot_layout_center_x = 0.0;

overlap = 0.001;          // ensures clean through-cuts

$fn = 96;

// ---------- Helpers ----------
module capsule_plate_2d(len, wid, r) {
    // 2D capsule using hull of two circles; r should be wid/2 for true rounded ends
    hull() {
        translate([-(len/2 - r), 0]) circle(r=r);
        translate([ (len/2 - r), 0]) circle(r=r);
    }
}

module octagon_2d(flat_d, sides=8) {
    // Across-flats = 2*apothem = 2*R*cos(pi/n) => R = flat_d/(2*cos(pi/n))
    R = flat_d / (2*cos(180/sides));
    rotate(180/sides) circle(r=R, $fn=sides);
}

module t_slot_2d() {
    // T shape centered at origin, stem along +X, head at +X end of stem
    union() {
        square([t_stem_l, t_stem_w], center=true);
        translate([t_stem_l/2 - t_head_l/2, 0])
            square([t_head_l, t_head_w], center=true);
    }
}

module t_slots_2d(count, pitch, center_x=0, y=0) {
    for (i = [0:count-1]) {
        x = center_x + (i - (count-1)/2) * pitch;
        translate([x, y]) t_slot_2d();
    }
}

// ---------- Model ----------
module plate_solid() {
    linear_extrude(height=T, center=true)
        capsule_plate_2d(L, W, end_r);
}

module cutouts() {
    linear_extrude(height=T + 2*overlap, center=true) {
        // Large octagonal hole near LEFT end (fixed orientation/placement)
        translate([-(L/2) + hole_offset_from_end, 0])
            octagon_2d(hole_flat_d, hole_sides);

        // Four repeated T-shaped slots along centerline
        translate([0, t_centerline_y])
            t_slots_2d(t_count, t_pitch, slot_layout_center_x, 0);
    }
}

difference() {
    plate_solid();
    cutouts();
}

// Flat rosette/gear-like disk with evenly spaced triangular teeth
// Target: uniform thin plate, circular core, no cutouts, one connected solid

$fn = 180;

// Parameters (mm)
bbox_x = 0.09;                 //[0.045:0.18:0.001]
bbox_y = 0.09;                 //[0.045:0.18:0.001]
thickness_z = 0.003;           //[0.001:0.01:0.0005]  // thin, constant thickness

tooth_count = 24;              //[6:96:1]
tooth_depth = 0.009;           //[0.0045:0.018:0.0005]
tooth_half_width = 0.004;      //[0.001:0.01:0.0005]
overlap = 0.001;               //[0.0005:0.002:0.0001]

// Derived radii to respect bounding box (outer diameter = min(bbox_x,bbox_y))
outer_radius = min(bbox_x, bbox_y) / 2;
core_radius  = outer_radius - tooth_depth;

// 2D tooth (triangle) placed so it overlaps into the core for guaranteed connectivity
module tooth_2d() {
    polygon(points=[
        [core_radius - overlap, -tooth_half_width],
        [core_radius - overlap,  tooth_half_width],
        [outer_radius,           0]
    ]);
}

// 2D outline: circular disk + radial teeth
module rosette_2d() {
    union() {
        circle(r=core_radius);
        for (i = [0:tooth_count-1])
            rotate(i * 360 / tooth_count)
                tooth_2d();
    }
}

// Final solid: uniform extrusion (flat plate)
linear_extrude(height=thickness_z, center=true, convexity=10)
    rosette_2d();

// Rotationally symmetric knob with scalloped rim, faceted barrel, rounded shoulder,
// coaxial boss, and a CENTRAL SQUARE THROUGH-HOLE (true through-cut).

// ---------------- Parameters ----------------
main_d = 0.01;          //[0.005:0.02:0.0001]
main_h = 0.022;         //[0.011:0.044:0.0001]
boss_d = 0.006;         //[0.003:0.012:0.0001]
boss_h = 0.008;         //[0.004:0.016:0.0001]
square_hole_w = 0.003;  //[0.0015:0.006:0.0001]

shoulder_h = 0.002;     //[0.001:0.004:0.0001]
facet_count = 8;        //[4:24:1]

scallop_count = 24;     //[8:64:1]
scallop_depth = 0.0008; //[0.0002:0.0012:0.00005]

overlap = 0.001;        //[0.0002:0.002:0.00005]  // ~1mm overlap for robust connectivity
micro_fillet_r = 0.00025; //[0.0001:0.0006:0.00005]

// ---------------- Derived ----------------
main_r  = main_d/2;
boss_r  = boss_d/2;

// Total height of the *outer* solid (used for through-hole length)
outer_total_h = main_h + boss_h;

$fn = 128;

// ---------------- Base geometry ----------------
module faceted_main_barrel() {
  // Faceted sides (polygonal cylinder), centered at origin
  rotate([0,0,180/facet_count])
    cylinder(h=main_h, r=main_r, center=true, $fn=facet_count);
}

module scalloped_band_cutters(rim_h, rim_z) {
  // Subtractive "bites" to form scallops around the circumference
  bite_r = scallop_depth * 1.6;
  bite_center_r = main_r + bite_r * 0.65;

  for (i = [0:scallop_count-1]) {
    rotate([0,0,i*360/scallop_count])
      translate([bite_center_r, 0, rim_z])
        cylinder(h=rim_h + 2*overlap, r=bite_r, center=true, $fn=48);
  }
}

module scalloped_main_barrel() {
  // Scalloped/serrated band near the bottom of the main barrel
  rim_h = main_h * 0.28;
  rim_z = -main_h/2 + rim_h/2;

  difference() {
    faceted_main_barrel();
    scalloped_band_cutters(rim_h, rim_z);
  }
}

module rounded_shoulder() {
  // Rounded transition from main barrel to boss via hull.
  // Recalculated to guarantee overlap into BOTH parts.
  // Main barrel spans: z = [-main_h/2, +main_h/2]
  // Boss spans (with overlap): centered at z = main_h/2 + boss_h/2 - overlap
  // so its bottom is at z = main_h/2 - overlap.
  z_main =  main_h/2 - shoulder_h/2;                 // inside main barrel top
  z_boss =  main_h/2 - overlap + shoulder_h/2;       // inside boss bottom

  hull() {
    translate([0,0,z_main])
      cylinder(h=shoulder_h, r=main_r, center=true, $fn=96);
    translate([0,0,z_boss])
      cylinder(h=shoulder_h, r=boss_r, center=true, $fn=96);
  }
}

module coaxial_boss() {
  // Boss on top end, overlapped into shoulder/main
  translate([0,0, main_h/2 + boss_h/2 - overlap])
    cylinder(h=boss_h, r=boss_r, center=true, $fn=96);
}

module outer_body() {
  union() {
    scalloped_main_barrel();
    rounded_shoulder();
    coaxial_boss();
  }
}

// ---------------- Subtractions ----------------
module square_through_hole() {
  // True square through-hole along Z, long enough to cut through filleted outer body.
  // Keep axis-aligned so it reads as a square in orthographic end views.
  hole_h = outer_total_h + 12*overlap + 2*micro_fillet_r;
  cube([square_hole_w, square_hole_w, hole_h], center=true);
}

// ---------------- Final ----------------
difference() {
  // Fillet outer body only, then cut the square hole through everything.
  minkowski() {
    outer_body();
    sphere(r=micro_fillet_r, $fn=32);
  }
  square_through_hole();
}

// Rectangular prismatic block with clipped (chamfered) corners on top/bottom faces,
// centered through octagonal bore (opens on the smaller side faces), top recessed slot + 4 corner recesses.

// ---------------- Parameters (mm) ----------------
L = 0.05; //[0.025:0.1:0.001]
W = 0.03; //[0.015:0.06:0.001]
H = 0.03; //[0.015:0.06:0.001]

chamfer = 0.003; //[0.0015:0.006:0.0005]   // corner clip size on top/bottom faces

bore_flat_d = 0.016; //[0.008:0.032:0.001] // across flats (octagon)
bore_lead_in = 0.001; //[0.0005:0.002:0.00025]
bore_lead_scale = 1.15; //[1.05:1.4:0.01]

slot_L = 0.04; //[0.02:0.08:0.001]
slot_W = 0.004; //[0.002:0.008:0.0005]
slot_depth = 0.0015; //[0.0005:0.003:0.00025]

corner_feat_size = 0.004; //[0.002:0.008:0.0005]
corner_feat_depth = 0.001; //[0.0005:0.002:0.00025]
corner_feat_offset_x = 0.006; //[0.003:0.012:0.0005]
corner_feat_offset_y = 0.006; //[0.003:0.012:0.0005]

edge_fillet_r = 0.0005; //[0.0:0.0015:0.00025]

// Robust overlap for booleans (small relative to part, but ensures clean cuts)
eps = 0.001; //[0.0002:0.002:0.0001]

// ---------------- Helpers ----------------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

// keep features valid
ch  = clamp(chamfer, 0, min(L, W)/2 - eps);

sfL = clamp(slot_L, eps, L - 2*eps);
sfW = clamp(slot_W, eps, W - 2*eps);
sd  = clamp(slot_depth, eps, H/2 - eps);

cfS = clamp(corner_feat_size, eps, min(L, W)/2 - eps);
cfD = clamp(corner_feat_depth, eps, H/2 - eps);
cfx = clamp(corner_feat_offset_x, cfS/2 + eps, L/2 - cfS/2 - eps);
cfy = clamp(corner_feat_offset_y, cfS/2 + eps, W/2 - cfS/2 - eps);

efr = clamp(edge_fillet_r, 0, min(L, W, H)/10);

// Regular octagon points for given across-flats dimension (flat-to-flat)
module octagon2d(af) {
  // For a regular octagon: across-flats = 2 * R * cos(22.5°)
  R = af / (2 * cos(22.5));
  polygon(points=[ for (i=[0:7]) [ R*cos(22.5 + i*45), R*sin(22.5 + i*45) ] ]);
}

// ---------------- Base body with clipped corners on top/bottom faces ----------------
module body_with_face_corner_clips() {
  // Clip corners on the large faces by subtracting corner prisms that extend through full thickness.
  difference() {
    cube([L, W, H], center=true);

    // Corner clips: place triangles at each XY corner and extrude through full thickness.
    for (sx=[-1,1], sy=[-1,1]) {
      translate([sx*(L/2 - ch), sy*(W/2 - ch), 0])
        scale([sx, sy, 1])
          linear_extrude(height=H + 4*eps, center=true)
            polygon(points=[[0,0],[ch,0],[0,ch]]);
    }
  }
}

// ---------------- Through octagonal bore (ALONG Y, opens on smaller side faces) ----------------
module through_oct_bore_with_leads() {
  // The bore must open on the smaller side faces (the XZ faces), so it runs along Y.
  // Extrude longer than W to guarantee a clean through-cut.
  union() {
    // Main through bore
    rotate([90,0,0])  // make extrusion axis = Y
      linear_extrude(height=W + 6*eps, center=true)
        octagon2d(bore_flat_d);

    // Lead-in at +Y end (slightly larger)
    rotate([90,0,0])
      translate([0, (W/2 - bore_lead_in/2), 0])
        linear_extrude(height=bore_lead_in + 6*eps, center=true)
          octagon2d(bore_flat_d * bore_lead_scale);

    // Lead-in at -Y end (slightly larger)
    rotate([90,0,0])
      translate([0, -(W/2 - bore_lead_in/2), 0])
        linear_extrude(height=bore_lead_in + 6*eps, center=true)
          octagon2d(bore_flat_d * bore_lead_scale);
  }
}

// ---------------- Top surface recess features (on +Z face) ----------------
module top_slot_recess() {
  // Cut from the top face downward; extend slightly above the face for reliable subtraction.
  translate([0, 0, H/2 - sd/2])
    cube([sfL, sfW, sd + 6*eps], center=true);
}

module top_corner_square_recesses() {
  for (sx=[-1,1], sy=[-1,1]) {
    translate([sx*(L/2 - cfx), sy*(W/2 - cfy), H/2 - cfD/2])
      cube([cfS, cfS, cfD + 6*eps], center=true);
  }
}

// ---------------- Final geometry (one connected solid) ----------------
module part_core() {
  difference() {
    body_with_face_corner_clips();

    // Subtractive features
    through_oct_bore_with_leads();   // now correctly opens on the smaller side faces
    top_slot_recess();
    top_corner_square_recesses();
  }
}

if (efr > 0) {
  // Rounded edges via Minkowski; keep as one connected solid.
  minkowski() {
    part_core();
    sphere(r=efr, $fn=32);
  }
} else {
  part_core();
}

// Parameters
bbox_x = 0.04; //[0.02:0.08:0.001]
bbox_y = 0.03; //[0.015:0.06:0.001]
bbox_z = 0.16; //[0.08:0.32:0.001]
body_len = 0.16; //[0.08:0.32:0.001]
body_w = 0.04; //[0.02:0.08:0.001]
body_t = 0.03; //[0.015:0.06:0.001]
corner_r = 0.004; //[0.002:0.008:0.0005]
curve_sag = 0.004; //[0.0:0.008:0.0005]
reinforce_len = 0.05; //[0.025:0.1:0.001]
reinforce_w = 0.038; //[0.019:0.076:0.001]
reinforce_t = 0.03; //[0.015:0.06:0.001]
window_len = 0.045; //[0.0225:0.09:0.001]
window_w = 0.022; //[0.011:0.044:0.001]
window_t = 0.032; //[0.016:0.064:0.001]
window_gap = 0.01; //[0.005:0.02:0.001]
end_margin = 0.015; //[0.0075:0.03:0.001]
end_hole_d = 0.006; //[0.003:0.012:0.0005]
end_chamfer = 0.004; //[0.002:0.008:0.0005]
overlap = 0.001; //[0.0005:0.002:0.0005]
facet_z = 0.04; //[0.02:0.08:0.005]
bevel = 0.0015; //[0.0005:0.003:0.0005]

// Main strap body
module main_strap_body() {
  cube([body_w - 2*corner_r, body_t - 2*corner_r, body_len - 2*corner_r], center=true);
}

// Edge fillets sphere
module edge_fillets_sphere() {
  sphere(r=corner_r, center=true);
}

// Central thickened reinforcement
module central_thickened_reinforcement() {
  cube([reinforce_w - 2*corner_r, reinforce_t - 2*corner_r, reinforce_len - 2*corner_r], center=true);
}

// Window cutouts
module window_cutout_1() {
  translate([0, 0, -(window_gap/2 + window_len/2)])
    cube([window_w, window_t, window_len], center=true);
}

module window_cutout_2() {
  translate([0, 0, (window_gap/2 + window_len/2)])
    cube([window_w, window_t, window_len], center=true);
}

// Cosmetic bevels on windows
module cosmetic_bevels_on_windows_1() {
  translate([0, 0, -(window_gap/2 + window_len/2)])
    cube([window_w + 2*bevel, window_t + 2*bevel, window_len + 2*bevel], center=true);
}

module cosmetic_bevels_on_windows_2() {
  translate([0, 0, (window_gap/2 + window_len/2)])
    cube([window_w + 2*bevel, window_t + 2*bevel, window_len + 2*bevel], center=true);
}

// End holes
module end_hole_1() {
  translate([0, 0, -(body_len/2 - end_margin)])
    rotate([90, 0, 0])
      cylinder(r=end_hole_d/2, h=body_t + 2*overlap, center=true);
}

module end_hole_2() {
  translate([0, 0, (body_len/2 - end_margin)])
    rotate([90, 0, 0])
      cylinder(r=end_hole_d/2, h=body_t + 2*overlap, center=true);
}

// End chamfers or rounds
module end_chamfers_or_rounds_wedge_pos() {
  translate([0, 0, (body_len/2 - end_chamfer/2)])
    rotate([0, 45, 0])
      cube([body_w + 2*overlap, body_t + 2*overlap, end_chamfer*2], center=true);
}

module end_chamfers_or_rounds_wedge_neg() {
  translate([0, 0, -(body_len/2 - end_chamfer/2)])
    rotate([0, -45, 0])
      cube([body_w + 2*overlap, body_t + 2*overlap, end_chamfer*2], center=true);
}

// Midsection faceted steps
module midsection_faceted_steps_seg1() {
  translate([0, curve_sag, -facet_z])
    cube([body_w - 2*corner_r, body_t - 2*corner_r, facet_z], center=true);
}

module midsection_faceted_steps_seg2() {
  translate([0, curve_sag/2, 0])
    cube([body_w - 2*corner_r, body_t - 2*corner_r, facet_z], center=true);
}

module midsection_faceted_steps_seg3() {
  translate([0, curve_sag, facet_z])
    cube([body_w - 2*corner_r, body_t - 2*corner_r, facet_z], center=true);
}

// Main body with edge fillets
module main_body_with_edge_fillets() {
  minkowski() {
    main_strap_body();
    edge_fillets_sphere();
  }
}

// Reinforcement with edge fillets
module reinforcement_with_edge_fillets() {
  minkowski() {
    central_thickened_reinforcement();
    edge_fillets_sphere();
  }
}

// Overall curvature
module overall_curvature() {
  hull() {
    midsection_faceted_steps_seg1();
    midsection_faceted_steps_seg2();
    midsection_faceted_steps_seg3();
  }
}

// Final model
module final_model() {
  difference() {
    union() {
      union() {
        main_body_with_edge_fillets();
        overall_curvature();
      }
      reinforcement_with_edge_fillets();
    }
    window_cutout_1();
    window_cutout_2();
    cosmetic_bevels_on_windows_1();
    cosmetic_bevels_on_windows_2();
    end_hole_1();
    end_hole_2();
    end_chamfers_or_rounds_wedge_pos();
    end_chamfers_or_rounds_wedge_neg();
  }
}

// Render the final model
color("Silver") final_model();

// Long rectangular prismatic block with a stepped (L-shaped) planform
// and two centered U-shaped notches cut into opposite end faces.
//
// Structural fixes applied:
// - Make the planform clearly L-shaped (union of two overlapping prisms).
// - Cut TWO centered U-shaped notches on the +/-X end faces.
//   These read as centered rectangular recesses on end views and as edge cutouts in side views.
// - All translate() values are derived from dimensions (no arbitrary offsets).
// - Use small eps overlaps for robust booleans.
// - Single connected solid (one difference of one connected union).

$fn = 64;

// -------------------- Parameters (mm) --------------------
L = 0.13;   // overall length (X)  elongated axis
W = 0.07;   // overall width  (Y)
H = 0.04;   // overall height (Z)

// L-step definition (planform): remove the (+X,+Y) corner region
step_L = 0.045; // X-length of removed corner region
step_W = 0.025; // Y-width  of removed corner region

// U-notch parameters (cut into +/-X end faces)
notch_depth  = 0.02; // depth into end face (along X)
notch_width  = 0.03; // overall notch opening width (along Y)
notch_height = 0.02; // overall notch opening height (along Z)

// Remaining material for the U profile
notch_side_wall = 0.006; // remaining side wall thickness (Y)
notch_top_wall  = 0.006; // remaining top wall thickness (Z)

eps = 0.001; // small overlap for robust booleans

// -------------------- Helpers --------------------
function clamp(v, lo, hi) = min(max(v, lo), hi);

// -------------------- Derived / clamped --------------------
step_Lc = clamp(step_L, 0, L - 2*eps);
step_Wc = clamp(step_W, 0, W - 2*eps);

notch_depth_c  = clamp(notch_depth,  0, L/2 - 2*eps);
notch_width_c  = clamp(notch_width,  0, W   - 2*eps);
notch_height_c = clamp(notch_height, 0, H   - 2*eps);

side_wall = clamp(notch_side_wall, 0, notch_width_c/2 - eps);
top_wall  = clamp(notch_top_wall,  0, notch_height_c  - eps);

// Inner slot that creates the U (opens to bottom)
inner_w = max(notch_width_c  - 2*side_wall, eps);
inner_h = max(notch_height_c - top_wall,    eps);

// -------------------- Geometry --------------------
module stepped_L_block() {
    // L-shaped planform via union of two prisms that overlap (single connected solid).
    // A) Left strip: (L - step_Lc) x W
    // B) Bottom strip: L x (W - step_Wc)
    union() {
        // A) Left strip (shifted toward -X so the removed corner is at +X)
        translate([-(step_Lc/2), 0, 0])
            cube([L - step_Lc, W, H], center=true);

        // B) Bottom strip (shifted toward -Y so the removed corner is at +Y)
        translate([0, -(step_Wc/2), 0])
            cube([L, W - step_Wc, H], center=true);
    }
}

module u_notch_cut(sign=1) {
    // sign = +1 for +X end, -1 for -X end
    // Cut a U-shaped recess into the end face:
    // - Outer pocket is removed.
    // - Inner slot is subtracted from the pocket (so it is NOT removed from the body),
    //   leaving side walls + top wall (U profile).
    x_face = sign * (L/2);
    x_ctr  = x_face - sign * (notch_depth_c/2);

    translate([x_ctr, 0, 0]) {
        difference() {
            // Outer pocket to remove (slightly extended in X for clean boolean)
            cube([notch_depth_c + 2*eps, notch_width_c, notch_height_c], center=true);

            // Inner slot (keeps side walls + top wall). Make it open to the bottom:
            // extend below the pocket bottom by eps.
            // Align inner slot top with pocket top so top_wall remains.
            z_inner_ctr = (notch_height_c/2) - (inner_h/2);

            translate([0, 0, z_inner_ctr - eps])
                cube([notch_depth_c + 4*eps, inner_w, inner_h + 4*eps], center=true);
        }
    }
}

module final_model() {
    difference() {
        stepped_L_block();

        // Two centered U-notches on opposite end faces
        u_notch_cut(+1);
        u_notch_cut(-1);
    }
}

