        translate([xpos, 0, 0])
            rotate([0,90,0])
                translate([small_cutout_radial_offset*cos(ang), small_cutout_radial_offset*sin(ang), 0])
                    cylinder(r=small_cutout_r, h=plate_t + 2*overlap, center=true);
