}

// Thin tapered ID/mounting plate with concave semicircular cutout, 4 through-slots,
// stencil-style cut-through text "EEZYbot ARM MK2", and TWO underside mounting feet.
// Structural fixes applied:
// - Slots are guaranteed to be inside the plate (and not inside the cutout) by computing
//   the local plate half-width at the slot X positions and clamping Y positions.
// - Two underside feet are created and forced to intersect the plate with overlap.
// - All translate() values are derived from dimensions (no arbitrary offsets).

$fn = 96;

// -------------------- Parameters (mm-ish units; keep small as provided) --------------------
plate_L        = 0.078;
plate_W_wide   = 0.078;
plate_W_narrow = 0.050;
plate_t        = 0.006;

cutout_r = 0.022;                 // concave semicircle radius at the narrow end

slot_L = 0.018;
slot_W = 0.003;
slot_pair_spacing = 0.010;        // spacing between the two slot rows (Y)
slot_edge_margin  = 0.006;        // keep slots away from cutout opening
slot_col_spacing  = 0.012;        // separation between the two columns (X)
slot_y_margin     = 0.002;        // keep slots away from plate edges

foot_L = 0.012;
foot_W = 0.008;
foot_drop = 0.004;
foot_from_cutout_end = 0.060;     // from cutout end along +X
foot_lateral_offset = 0.018;

overlap = 0.0015;                 // small overlap to guarantee connectivity

// Text (cut-through)
text_str = "EEZYbot ARM MK2";
text_size = 0.010;
text_spacing = 1.0;
text_font = "Liberation Sans:style=Bold";
text_y_offset = 0;
text_x_offset = 0.010;

// Stencil bridges
bridge_w = 0.0012;
bridge_h = 0.0040;
bridge_count = 14;

// -------------------- Helpers --------------------
function clamp(v, lo, hi) = (v < lo) ? lo : (v > hi) ? hi : v;

// Linear taper: half-width at a given x along the plate
function plate_halfW_at_x(x) =
    let(t = (x + plate_L/2) / plate_L)  // 0 at narrow end (-L/2), 1 at wide end (+L/2)
    (plate_W_narrow/2) + t * ((plate_W_wide - plate_W_narrow)/2);

module tapered_plate_2d() {
    polygon(points = [
        [-plate_L/2, -plate_W_narrow/2],
        [-plate_L/2,  plate_W_narrow/2],
        [ plate_L/2,  plate_W_wide/2],
        [ plate_L/2, -plate_W_wide/2]
    ]);
}

// Concave semicircular cutout that opens into the plate from the narrow end.
module concave_semicircular_end_cutout_2d() {
    end_x = -plate_L/2;
    cx = end_x; // center on the end line for a clean semicircle opening

    intersection() {
        translate([cx, 0]) circle(r = cutout_r);
        // Keep x >= end_x portion of the circle (the part overlapping the plate)
        translate([end_x - overlap, -2*cutout_r])
            square([2*cutout_r + 4*overlap, 4*cutout_r], center=false);
    }
}

module rounded_slot_2d(cx, cy, L, W) {
    r = max(W/2, 0.0001);
    hull() {
        translate([cx - L/2, cy]) circle(r = r);
        translate([cx + L/2, cy]) circle(r = r);
    }
}

module all_slots_2d() {
    end_x = -plate_L/2;

    // Place slots just past the cutout opening, clearly within the plate
    x1 = end_x + cutout_r + slot_edge_margin + slot_L/2;
    x2 = x1 + slot_col_spacing;

    // Compute safe Y positions based on local plate width at each column X
    // so slots cannot end up outside the tapered outline.
    y_lim1 = plate_halfW_at_x(x1) - (slot_W/2) - slot_y_margin;
    y_lim2 = plate_halfW_at_x(x2) - (slot_W/2) - slot_y_margin;

    // Desired pair positions, then clamped to fit both columns
    y_des = slot_pair_spacing/2;
    y1 = clamp( y_des, 0, min(y_lim1, y_lim2));
    y2 = -y1;

    union() {
        rounded_slot_2d(x1, y1, slot_L, slot_W);
        rounded_slot_2d(x2, y1, slot_L, slot_W);
        rounded_slot_2d(x1, y2, slot_L, slot_W);
        rounded_slot_2d(x2, y2, slot_L, slot_W);
    }
}

module stencil_text_minus_bridges_2d() {
    approx_w = max(text_size * len(text_str) * 0.58, text_size*2);
    x_min = -approx_w/2 + text_x_offset;

    difference() {
        translate([text_x_offset, text_y_offset])
            text(text_str, size=text_size, font=text_font, spacing=text_spacing,
                 halign="center", valign="center");

        for (i = [0:bridge_count-1]) {
            xi = x_min + (i + 0.5) * (approx_w / bridge_count);
            translate([xi, text_y_offset])
                square([bridge_w, bridge_h], center=true);
        }
    }
}

module plate_solid() {
    difference() {
        linear_extrude(height = plate_t, center = true, convexity=10)
            tapered_plate_2d();

        // Concave semicircular bite (horn corners)
        linear_extrude(height = plate_t + 2*overlap, center = true, convexity=10)
            concave_semicircular_end_cutout_2d();

        // Four through-slots near cutout end
        linear_extrude(height = plate_t + 2*overlap, center = true, convexity=10)
            all_slots_2d();

        // Cut-through stencil text
        linear_extrude(height = plate_t + 2*overlap, center = true, convexity=10)
            stencil_text_minus_bridges_2d();
    }
}

module underside_foot(x, y) {
    // Intersect the plate by 'overlap' to guarantee a single connected solid
    translate([x, y, -(plate_t/2 + foot_drop/2) + overlap])
        cube([foot_L, foot_W, foot_drop], center=true);
}

module final_plate_with_feet() {
    end_x = -plate_L/2;
    foot_x = end_x + foot_from_cutout_end;

    // Ensure feet are within the local plate width at foot_x
    y_lim = plate_halfW_at_x(foot_x) - foot_W/2 - overlap;
    foot_y = clamp(foot_lateral_offset, 0, y_lim);

    union() {
        plate_solid();

        // TWO feet/tabs (symmetrical), both connected
        underside_foot(foot_x,  foot_y);
        underside_foot(foot_x, -foot_y);
    }
}

// Render
color("Silver") final_plate_with_feet();

// Thin nameplate/keychain tag with chamfered ends, a DISTINCT circular boss at one end,
// a DIAMOND-shaped through-hole inside that boss, raised "ASTRID" text, and a small
// geometric logo near the holed end. One connected solid (minus the through-hole).

// ---------- Parameters (mm) ----------
bbox_L = 0.1;    // overall length target (approx)
bbox_W = 0.02;   // overall width target (approx)
bbox_H = 0.01;   // overall thickness target (approx)

plate_L = 0.082;
plate_W = 0.018;
plate_T = 0.006;

chamfer_L = 0.006;

boss_D = 0.018;          // circular boss diameter
boss_T = 0.006;          // boss thickness (same as plate for flat tag)
boss_overlap_xy = 0.002; // how much boss overlaps into plate in X (ensures connection)

hole_diamond_flat_to_flat = 0.008;
hole_clearance = 0.0002;

text_H = 0.0012;
text_size = 0.010;
text_margin_side = 0.002;
text_margin_end  = 0.020;

logo_size = 0.004;
logo_H = 0.001;

eps = 0.0005;

// ---------- Quality ----------
$fn = 128;

// ---------- Helpers ----------
function clamp(x, a, b) = min(max(x, a), b);

// Chamfer wedge used to cut the plate ends (in XY, extruded in Z)
module chamfer_wedge(w, chamfer_len, h) {
    linear_extrude(height=h, center=true)
        polygon(points=[
            [0,  w/2 + eps],
            [0, -w/2 - eps],
            [chamfer_len + eps, 0]
        ]);
}

// Diamond hole (flat-to-flat = dff)
module diamond_hole(dff, h) {
    d = dff/2;
    linear_extrude(height=h, center=true)
        polygon(points=[[0,d],[d,0],[0,-d],[-d,0]]);
}

// Small geometric logo: outlined diamond + 2 bars (embossed)
module small_logo(size, h) {
    // Outline diamond (ring)
    difference() {
        linear_extrude(height=h, center=false)
            polygon(points=[[0,size],[size,0],[0,-size],[-size,0]]);
        translate([0,0,-eps])
            linear_extrude(height=h+2*eps, center=false)
                polygon(points=[[0,size*0.62],[size*0.62,0],[0,-size*0.62],[-size*0.62,0]]);
    }
    // Two small bars above the diamond
    for (yy = [size*0.95, size*1.35]) {
        translate([0, yy, h/2])
            cube([size*1.6, size*0.22, h], center=true);
    }
}

// ---------- Main solids ----------
module plate_body() {
    // Base plate with chamfered ends
    difference() {
        cube([plate_L, plate_W, plate_T], center=true);

        // Right end chamfer
        translate([ plate_L/2 - chamfer_L, 0, 0])
            chamfer_wedge(plate_W, chamfer_L, plate_T + 4*eps);

        // Left end chamfer
        translate([-plate_L/2 + chamfer_L, 0, 0])
            rotate([0,0,180])
                chamfer_wedge(plate_W, chamfer_L, plate_T + 4*eps);
    }
}

module boss_solid() {
    // Boss center placed so the boss is clearly round and protrudes beyond the plate end,
    // while still overlapping the plate by boss_overlap_xy to guarantee connectivity.
    boss_cx = plate_L/2 + boss_D/2 - boss_overlap_xy;
    translate([boss_cx, 0, 0])
        cylinder(h=boss_T, r=boss_D/2, center=true);
}

module embossed_text() {
    usable_L = plate_L - 2*text_margin_end;
    usable_W = plate_W - 2*text_margin_side;

    // Rough width estimate for "ASTRID"
    est_text_w = text_size * 6 * 0.62;
    scale_x = clamp(usable_L / max(est_text_w, 1e-9), 0.6, 1.2);
    scale_y = clamp(usable_W / max(text_size, 1e-9), 0.7, 1.1);

    // Shift text away from boss end so it stays on the rectangular plate area
    tx = -plate_L*0.06;

    translate([tx, 0, plate_T/2 - eps])
        linear_extrude(height=text_H + eps, center=false)
            scale([scale_x, scale_y, 1])
                text("ASTRID",
                     size=text_size,
                     halign="center",
                     valign="center",
                     font="Liberation Sans:style=Bold");
}

module embossed_logo() {
    boss_cx = plate_L/2 + boss_D/2 - boss_overlap_xy;

    // Place logo on plate near boss, but not on the hole center
    lx = boss_cx - boss_D*0.70;
    ly = plate_W*0.18;

    translate([lx, ly, plate_T/2 - eps])
        small_logo(logo_size, logo_H + eps);
}

module tag_solid() {
    union() {
        plate_body();
        boss_solid();
        embossed_text();
        embossed_logo();
    }
}

module final_model() {
    boss_cx = plate_L/2 + boss_D/2 - boss_overlap_xy;

    difference() {
        tag_solid();

        // Diamond through-hole centered in the circular boss
        translate([boss_cx, 0, 0])
            rotate([0,0,45])
                diamond_hole(hole_diamond_flat_to_flat + hole_clearance,
                             max(plate_T, boss_T) + 6*eps);
    }
}

// ---------- Render ----------
final_model();

// Clean, connected mounting block with symmetric through-hole pattern
// Units: meters (as in original). Keep geometry simple and readable.

$fn = 64;

// Parameters
L = 0.04; //[0.02:0.08:0.001]
W = 0.02; //[0.01:0.04:0.001]
T = 0.006; //[0.003:0.009:0.001]

overlap = 0.001; //[0.0005:0.002:0.0005]   // 1–2mm overlap for robust unions
ear_chamfer = 0.002; //[0.001:0.004:0.0005]

boss_d = 0.008; //[0.004:0.016:0.0005]
boss_h = 0.004; //[0.002:0.008:0.0005]
boss_facets = 8; //[6:16:1]

tab_L = 0.004; //[0.002:0.008:0.0005]
tab_W = 0.004; //[0.002:0.01:0.0005]
tab_T = 0.004; //[0.002:0.006:0.0005]

hole_d_small = 0.002; //[0.001:0.004:0.0005]
hole_teardrop_L = 0.003; //[0.0015:0.006:0.0005]
hole_teardrop_W = 0.002; //[0.001:0.004:0.0005]
diamond_across_flats = 0.004; //[0.002:0.008:0.0005]

hole_edge_margin = 0.002; //[0.001:0.004:0.0005]
hole_pitch_L = 0.01; //[0.005:0.02:0.0005]
hole_pitch_W = 0.008; //[0.004:0.016:0.0005]

micro_chamfer = 0.0005; //[0.0002:0.001:0.0001]
countersink_d = 0.003; //[0.002:0.006:0.0005]

// ---------- Helpers ----------
module ear_chamfer_cuts() {
  // subtract these from the plate to create chamfered corner ears
  for (sx = [-1, 1], sy = [-1, 1]) {
    translate([sx*(L/2 - ear_chamfer), sy*(W/2 - ear_chamfer), 0])
      rotate([0, 0, 45])
        cube([ear_chamfer*2, ear_chamfer*2, T + 2*overlap], center=true);
  }
}

module teardrop_hole_2d(len, w) {
  // 2D teardrop-ish profile (circle + pointed end), extruded later
  // Oriented along +X.
  hull() {
    translate([-(len/2 - w/2), 0]) circle(r=w/2);
    translate([ +(len/2 - w/2), 0]) circle(r=w/2);
    // add a small point to make it more "teardrop" than capsule
    translate([len/2, 0]) circle(r=w/6);
  }
}

module through_holes() {
  // All holes are true through-holes (cut silhouettes visible in ortho views)
  union() {
    // Two diamond (rotated-square) apertures near center, symmetric in X
    for (sx = [-1, 1]) {
      translate([sx*hole_pitch_L/2, 0, 0])
        rotate([0, 0, 45])
          cube([diamond_across_flats, diamond_across_flats, T + 2*overlap], center=true);
    }

    // Four small round holes in a symmetric rectangle
    for (sx = [-1, 1], sy = [-1, 1]) {
      translate([sx*hole_pitch_L/2, sy*hole_pitch_W/2, 0])
        cylinder(d=hole_d_small, h=T + 2*overlap, center=true);
    }

    // Two teardrop-like holes near the ends, symmetric in X
    // Keep them inside the plate footprint with edge margin.
    teardrop_x = (L/2 - hole_edge_margin - hole_teardrop_L/2);
    for (sx = [-1, 1]) {
      translate([sx*teardrop_x, 0, 0])
        linear_extrude(height=T + 2*overlap, center=true)
          rotate( sx < 0 ? 180 : 0 )  // point outward
            teardrop_hole_2d(hole_teardrop_L, hole_teardrop_W);
    }

    // Light countersink/chamfer on the four small round holes (both faces)
    for (sx = [-1, 1], sy = [-1, 1]) {
      // top face
      translate([sx*hole_pitch_L/2, sy*hole_pitch_W/2, +T/2 - micro_chamfer/2])
        cylinder(h=micro_chamfer, r1=countersink_d/2, r2=0, center=true);
      // bottom face
      translate([sx*hole_pitch_L/2, sy*hole_pitch_W/2, -T/2 + micro_chamfer/2])
        cylinder(h=micro_chamfer, r1=countersink_d/2, r2=0, center=true);
    }
  }
}

module plate_with_chamfered_ears() {
  difference() {
    cube([L, W, T], center=true);
    ear_chamfer_cuts();
  }
}

module end_tabs() {
  // Thin tab/rod-like extensions at both ends, connected with overlap
  // Place tabs centered in Y, and flush to bottom face of plate.
  tab_z = -T/2 + tab_T/2 - overlap; // overlap into plate
  for (sx = [-1, 1]) {
    tab_x = sx*(L/2 + tab_L/2 - overlap); // overlap into plate
    translate([tab_x, 0, tab_z])
      cube([tab_L, tab_W, tab_T], center=true);
  }
}

module faceted_boss() {
  // Central faceted cylindrical boss protruding from top face, connected with overlap
  boss_z = +T/2 + boss_h/2 - overlap; // overlap into plate
  translate([0, 0, boss_z])
    cylinder(d=boss_d, h=boss_h, center=true, $fn=boss_facets);
}

// ---------- Final ----------
module final_geometry() {
  difference() {
    union() {
      plate_with_chamfered_ears();
      end_tabs();
      faceted_boss();
    }
    through_holes();
  }
}

final_geometry();

// Shallow vented tray with rounded corners + wide outward flange + diamond side perforations
// Units: mm (very small part as requested)

// ---------------- Parameters ----------------
L = 0.31;   //[0.155:0.62:0.001]  // overall length (elongated axis)
W = 0.10;   //[0.05:0.20:0.001]   // overall width  (short axis)
H = 0.08;   //[0.04:0.16:0.001]   // overall height

corner_r = 0.02; //[0.01:0.05:0.001]
wall_t   = 0.006; //[0.003:0.012:0.001]
bottom_t = 0.010; //[0.004:0.020:0.001]

flange_w = 0.03;  //[0.01:0.06:0.001]  // outward lip width
flange_t = 0.004; //[0.002:0.010:0.001]

draft = 0.010; //[0.0:0.03:0.001] // outward draft amount from bottom to top (per side)

hole_w = 0.018; //[0.009:0.036:0.001] // diamond width
hole_h = 0.012; //[0.005:0.024:0.001] // diamond height
hole_pitch_x = 0.030; //[0.014:0.060:0.001] // along length
hole_pitch_z = 0.022; //[0.010:0.050:0.001] // along height

hole_margin_top = 0.012;    //[0.006:0.030:0.001]
hole_margin_bottom = 0.012; //[0.006:0.030:0.001]
hole_margin_corners = 0.020; //[0.010:0.050:0.001]

eps = 0.001;

// ---------------- Helpers ----------------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

module rounded_rect_2d(x, y, r){
  r2 = clamp(r, 0, min(x,y)/2);
  offset(r=r2) square([x-2*r2, y-2*r2], center=true);
}

module diamond_2d(w,h){
  polygon(points=[[0,h/2],[w/2,0],[0,-h/2],[-w/2,0]]);
}

// Tray outer: rounded rectangle, drafted (top larger than bottom)
module outer_shell(){
  // bottom outer dims
  Lb = L - 2*draft;
  Wb = W - 2*draft;
  // keep valid
  Lb2 = max(Lb, 2*corner_r + 2*wall_t + 0.01);
  Wb2 = max(Wb, 2*corner_r + 2*wall_t + 0.01);

  hull(){
    translate([0,0,-H/2]) linear_extrude(height=eps, center=false)
      rounded_rect_2d(Lb2, Wb2, max(corner_r - draft, 0.001));
    translate([0,0, H/2]) linear_extrude(height=eps, center=false)
      rounded_rect_2d(L, W, corner_r);
  }
}

// Inner void: drafted, starts above bottom_t to keep solid bottom
module inner_void(){
  // inner top dims
  Lt = L - 2*wall_t;
  Wt = W - 2*wall_t;

  // inner bottom dims (smaller due to draft)
  Lb = (L - 2*draft) - 2*wall_t;
  Wb = (W - 2*draft) - 2*wall_t;

  // keep valid
  Lt2 = max(Lt, 0.02);
  Wt2 = max(Wt, 0.02);
  Lb2 = max(Lb, 0.02);
  Wb2 = max(Wb, 0.02);

  // inner corner radii
  rt = max(corner_r - wall_t, 0.001);
  rb = max(corner_r - wall_t - draft, 0.001);

  hull(){
    translate([0,0,-H/2 + bottom_t]) linear_extrude(height=eps, center=false)
      rounded_rect_2d(Lb2, Wb2, rb);
    translate([0,0, H/2 + eps]) linear_extrude(height=eps, center=false)
      rounded_rect_2d(Lt2, Wt2, rt);
  }
}

// Wide outward flange/lip around top perimeter
module top_flange(){
  translate([0,0, H/2 - flange_t/2])
  difference(){
    linear_extrude(height=flange_t, center=true)
      rounded_rect_2d(L + 2*flange_w, W + 2*flange_w, corner_r + flange_w);
    translate([0,0,0])
      linear_extrude(height=flange_t + 2*eps, center=true)
        rounded_rect_2d(L, W, corner_r);
  }
}

// Diamond hole cutter oriented to cut through a wall
module diamond_cutter_x(depth){
  rotate([0,90,0])
    linear_extrude(height=depth, center=true)
      diamond_2d(hole_w, hole_h);
}
module diamond_cutter_y(depth){
  rotate([90,0,0])
    linear_extrude(height=depth, center=true)
      diamond_2d(hole_w, hole_h);
}

// Perforation pattern on all four side walls (through-holes), leaving bottom solid
module side_perforations(){
  // z range for holes (avoid top flange and bottom)
  z0 = -H/2 + bottom_t + hole_margin_bottom + hole_h/2;
  z1 =  H/2 - flange_t - hole_margin_top - hole_h/2;
  zspan = max(z1 - z0, 0);

  // x/y ranges (avoid rounded corners)
  x0 = -L/2 + hole_margin_corners + hole_w/2;
  x1 =  L/2 - hole_margin_corners - hole_w/2;
  y0 = -W/2 + hole_margin_corners + hole_w/2;
  y1 =  W/2 - hole_margin_corners - hole_w/2;

  // counts
  nx = max(1, floor((x1 - x0)/hole_pitch_x) + 1);
  ny = max(1, floor((y1 - y0)/hole_pitch_x) + 1);
  nz = max(1, floor(zspan/hole_pitch_z) + 1);

  // wall mid-planes (approx; cutters are deep enough to pass through drafted walls)
  xwall = L/2 - wall_t/2;
  ywall = W/2 - wall_t/2;

  depth = wall_t + 2*draft + 4*eps;

  union(){
    // +X and -X walls (vary along Y and Z)
    for (iz = [0:nz-1]){
      z = z0 + iz*hole_pitch_z;
      // stagger every other row
      yshift = (iz % 2) * (hole_pitch_x/2);
      for (iy = [0:ny-1]){
        y = (y0 + iy*hole_pitch_x) + yshift;
        if (y >= y0 && y <= y1){
          translate([ xwall, y, z]) diamond_cutter_x(depth);
          translate([-xwall, y, z]) diamond_cutter_x(depth);
        }
      }
    }

    // +Y and -Y walls (vary along X and Z)
    for (iz = [0:nz-1]){
      z = z0 + iz*hole_pitch_z;
      xshift = (iz % 2) * (hole_pitch_x/2);
      for (ix = [0:nx-1]){
        x = (x0 + ix*hole_pitch_x) + xshift;
        if (x >= x0 && x <= x1){
          translate([x,  ywall, z]) diamond_cutter_y(depth);
          translate([x, -ywall, z]) diamond_cutter_y(depth);
        }
      }
    }
  }
}

// ---------------- Final model ----------------
module tray(){
  difference(){
    union(){
      difference(){
        outer_shell();
        inner_void();
      }
      top_flange();
    }
    side_perforations();
  }
}

color([0.85, 0.85, 0.8])
tray();

// Thin keyed plate with asymmetric tabs on opposite Z faces
// Goal: one connected solid; visible asymmetry between front/back and left/right views.

// Parameters (mm)
plate_W = 0.30;
plate_H = 0.30;
plate_T = 0.01;

// Tab sizes
tab_out    = 0.01;   // protrusion outward from edge (in XY)
tab_w      = 0.06;   // width of top/bottom tabs (along X)
tab_side_h = 0.06;   // height of side tabs (along Y)

