body_h    = 14;

flange_af = 30;   // hex across flats
flange_h  = 6;

overlap   = 0.2;  // small overlap to guarantee one connected solid

// Helpers
function hex_R_from_AF(af) = af / sqrt(3); // circumradius for regular hex given across-flats

module hex_prism(af, h) {
    // Regular hex with flats horizontal (as in provided views)
    linear_extrude(height=h, center=true)
        polygon(points=[
            [ af/2, 0],
            [ af/4,  af*sqrt(3)/4],
            [-af/4,  af*sqrt(3)/4],
            [-af/2, 0],
            [-af/4, -af*sqrt(3)/4],
            [ af/4, -af*sqrt(3)/4]
        ]);
}

module model() {
    union() {
        // Main cylindrical body: bottom at z=0, top at z=body_h
        translate([0, 0, body_h/2])
            cylinder(h=body_h, r=body_d/2, center=true);

        // Hex flange on top end: bottom slightly overlaps body top
        translate([0, 0, body_h + flange_h/2 - overlap])
            hex_prism(flange_af, flange_h);
    }
}

color("Silver") model();

// Offset link/lever with two bosses and through hex holes
// Structural fixes:
// - Clear L-shaped/offset profile in side view via Z step between ends
// - Cylindrical bosses (no faceting)
// - Recalculated translations so parts touch with controlled overlap
// - Single connected solid, then holes subtracted
// - Optional uniform scaling to meet tiny bounding-box requirement

// ---------- Quality ----------
$fn = 96;

// ---------- Parameters (mm, before optional scaling) ----------
bbox_L = 0.13;
bbox_W = 0.05;
bbox_H = 0.05;

boss_large_d = 0.05;
boss_small_d = 0.04;

boss_large_t = 0.05;
boss_small_t = 0.03;

bar_t = 0.02;
bar_w = 0.02;
bar_L = 0.09;

hex_flat_large = 0.02;
hex_flat_small = 0.018;
hex_clearance = 0.001;

hex_h_extra = 0.01;

// Connection overlap (in mm, pre-scale). Keep small but nonzero.
overlap = 0.0015;

// L-shaped offset amount (creates the side-view step)
z_offset = 0.012;

// Optional: scale whole model so its max dimension is ~0.1mm.
// Set to 1 to keep original sizes.
target_max_dim = 0.10;
pre_max_dim = max(bbox_L, bbox_W, bbox_H);
scale_to_target = target_max_dim / pre_max_dim;  // ~0.769 for given bbox
use_scaling = true;

// ---------- Helpers ----------
function hex_R_from_flat(f) = f / sqrt(3); // circumradius for flat-to-flat = f

module hex_prism(flat, h) {
  // Regular hex with flats aligned to Y axis (rotation not critical)
  cylinder(r=hex_R_from_flat(flat), h=h, center=true, $fn=6);
}

// ---------- Geometry (centered around origin) ----------
module solid_body() {
  // Coordinate system:
  // X = length direction, Y = width, Z = thickness/offset direction
  //
  // Large boss centered at x = -bar_L/2, z = 0
  // Small boss centered at x = +bar_L/2, z = z_offset
  // Bar is a rectangular prism connecting the two boss centers, centered at z = z_offset/2

  xL = -bar_L/2;
  xS =  bar_L/2;

  zL = 0;
  zS = z_offset;

  // Bar spans between boss centers, with a little extra length to overlap into bosses
  bar_len = bar_L + overlap*2;
  bar_z   = (zL + zS)/2;

  union() {
    // Connecting bar (rectangular)
    translate([0, 0, bar_z])
      cube([bar_len, bar_w, bar_t], center=true);

    // Large boss (cylindrical), slightly overlapped with bar
    translate([xL, 0, zL])
      cylinder(d=boss_large_d, h=boss_large_t + overlap*2, center=true);

    // Small boss (cylindrical), offset in Z to create L-profile
    translate([xS, 0, zS])
      cylinder(d=boss_small_d, h=boss_small_t + overlap*2, center=true);

    // Web/step connector to make the offset visually and structurally continuous:
    // hull between two thin pads at the bar/boss junctions.
    hull() {
      translate([xL + boss_large_d/2 - overlap, 0, zL])
        cube([overlap*2, bar_w, bar_t], center=true);

      translate([xS - boss_small_d/2 + overlap, 0, zS])
        cube([overlap*2, bar_w, bar_t], center=true);
    }
  }
}

module body_with_holes() {
  xL = -bar_L/2;
  xS =  bar_L/2;

  zL = 0;
  zS = z_offset;

  difference() {
    solid_body();

    // Through hex hole in large boss
    translate([xL, 0, zL])
      hex_prism(hex_flat_large + hex_clearance, boss_large_t + hex_h_extra);

    // Through hex hole in small boss
    translate([xS, 0, zS])
      hex_prism(hex_flat_small + hex_clearance, boss_small_t + hex_h_extra);
  }
}

// ---------- Final Output ----------
if (use_scaling)
  scale([scale_to_target, scale_to_target, scale_to_target]) body_with_holes();
else
  body_with_holes();

// Textured studded micro-cube with pyramidal/diamond bosses on each face
// Bounding box target: 0.1 x 0.1 x 0.1 mm

$fn = 4; // faceted "diamond" look for pyramids

// Overall size (exact 0.1mm cube)
block_x = 0.1;
block_y = 0.1;
block_z = 0.1;

// Boss geometry
boss_h = 0.012;
boss_base = 0.020;
boss_top  = 0.001;   // near-point apex
boss_offset_xy = 0.030; // corner-adjacent placement on faces
center_boss_scale = 0.65;

// Extra small edge/corner protrusions (subtle)
edge_boss_scale = 0.45;
edge_boss_h_scale = 0.75;

// Connectivity / overlap (ensures one connected solid)
boss_overlap = 0.0015;

// Small edge chamfer (keeps cube-like but slightly softened)
edge_chamfer = 0.0015;

// ---------- Helpers ----------
module pyramid_boss(h, base, top) {
    // 4-sided pyramid/frustum (diamond-like)
    cylinder(h=h, r1=base/2, r2=top/2, center=true, $fn=4);
}

module chamfered_block(size=[block_x, block_y, block_z], c=edge_chamfer) {
    // Chamfer by subtracting small corner cubes (keeps single solid)
    difference() {
        cube(size, center=true);
        for (sx=[-1,1], sy=[-1,1], sz=[-1,1]) {
            translate([sx*(size[0]/2 - c), sy*(size[1]/2 - c), sz*(size[2]/2 - c)])
                rotate([45,45,45])
                    cube([2*c,2*c,2*c], center=true);
        }
    }
}

// Place a boss on a given face with correct outward normal and guaranteed overlap
module place_boss_on_face(face="zp", u=0, v=0, s=1.0, h=boss_h, base=boss_base, top=boss_top) {
    // face: zp, zm, xp, xm, yp, ym
    // u,v are in-plane offsets (x/y for z faces, y/z for x faces, x/z for y faces)
    if (face=="zp") {
        translate([u, v, block_z/2 + h/2 - boss_overlap])
            scale([s,s,s]) pyramid_boss(h, base, top);
    } else if (face=="zm") {
        translate([u, v, -block_z/2 - h/2 + boss_overlap])
            rotate([180,0,0])
                scale([s,s,s]) pyramid_boss(h, base, top);
    } else if (face=="xp") {
        translate([block_x/2 + h/2 - boss_overlap, u, v])
            rotate([0,-90,0])
                scale([s,s,s]) pyramid_boss(h, base, top);
    } else if (face=="xm") {
        translate([-block_x/2 - h/2 + boss_overlap, u, v])
            rotate([0,90,0])
                scale([s,s,s]) pyramid_boss(h, base, top);
    } else if (face=="yp") {
        translate([u, block_y/2 + h/2 - boss_overlap, v])
            rotate([90,0,0])
                scale([s,s,s]) pyramid_boss(h, base, top);
    } else if (face=="ym") {
        translate([u, -block_y/2 - h/2 + boss_overlap, v])
            rotate([-90,0,0])
                scale([s,s,s]) pyramid_boss(h, base, top);
    }
}

module face_pattern(face) {
    // 4 corner-adjacent bosses + smaller central boss
    union() {
        // central boss
        place_boss_on_face(face, 0, 0, center_boss_scale);

        // four corner-adjacent bosses
        for (a=[-1,1], b=[-1,1])
            place_boss_on_face(face, a*boss_offset_xy, b*boss_offset_xy, 1.0);
    }
}

module extra_edge_protrusions() {
    // Small additional protrusions near some edges/corners (subtle, not star-like)
    // Put them on a subset of edges to mimic "additional protrusions visible near some edges/corners"
    eh = boss_h * edge_boss_h_scale;
    eb = boss_base * edge_boss_scale;
    et = boss_top;

    // Along +Z top edges (midpoints)
    place_boss_on_face("zp",  block_x*0.25, 0, 0.55, eh, eb, et);
    place_boss_on_face("zp", -block_x*0.25, 0, 0.55, eh, eb, et);
    place_boss_on_face("zp", 0,  block_y*0.25, 0.55, eh, eb, et);
    place_boss_on_face("zp", 0, -block_y*0.25, 0.55, eh, eb, et);

    // Along -Z bottom edges (fewer)
    place_boss_on_face("zm",  block_x*0.25, 0, 0.50, eh, eb, et);
    place_boss_on_face("zm", 0, -block_y*0.25, 0.50, eh, eb, et);

    // A couple on side faces near edges
    place_boss_on_face("xp", 0,  block_z*0.25, 0.50, eh, eb, et);
    place_boss_on_face("ym", -block_x*0.25, 0, 0.50, eh, eb, et);
}

// ---------- Final solid ----------
union() {
    chamfered_block([block_x, block_y, block_z], edge_chamfer);

    // Boss patterns on all 6 faces (includes central boss on each face)
    face_pattern("zp");
    face_pattern("zm");
    face_pattern("xp");
    face_pattern("xm");
    face_pattern("yp");
    face_pattern("ym");

    // Additional subtle edge/corner protrusions
    extra_edge_protrusions();
}

