// Flanged cylindrical hub/bushing with central hex through-bore
// Features: wide flange, stepped OD (minor near flange), small collar near far end,
// and 4 diamond-shaped recesses on the flange face.
// Model is one connected solid. Dimensions kept within 0.1 x 0.1 x 0.1 mm bbox.

$fn = 160;

// ---------- Parameters (mm) ----------
bbox = 0.1;

flange_d = 0.1;
flange_t = 0.02;

body_d_major = 0.06;     // main OD
body_d_minor = 0.05;     // reduced OD section near flange
body_len_total = 0.1;    // total length including flange (matches bbox Z)

step_len = 0.03;         // length of reduced OD section (from flange side)

collar_d = 0.065;        // small collar near far end
collar_len = 0.01;
collar_offset_from_end = 0.005;

hex_af = 0.03;           // across flats

diamond_count = 4;
diamond_radial_pos = 0.032;
diamond_w = 0.012;
diamond_h = 0.006;
diamond_depth = 0.006;

eps = 0.0005;

// ---------- Derived ----------
body_h = body_len_total - flange_t;

z_min = -body_len_total/2;
z_max =  body_len_total/2;

z_flange_center = z_min + flange_t/2;
z_body_center   = z_min + flange_t + body_h/2;

z_step_center   = z_min + flange_t + step_len/2;

z_collar_center = z_max - collar_offset_from_end - collar_len/2;

// ---------- Helpers ----------
module hex_prism_through(af, h) {
    // Regular hex with given across-flats (af): circumradius R = af / sqrt(3)
    R = af / sqrt(3);
    cylinder(h=h, r=R, center=true, $fn=6);
}

module diamond_prism(w, h, depth) {
    linear_extrude(height=depth, center=true)
        polygon(points=[
            [ w/2, 0],
            [ 0,   h/2],
            [-w/2, 0],
            [ 0,  -h/2]
        ]);
}

// ---------- Main solid ----------
module outer_solid() {
    union() {
        // Flange
        translate([0,0,z_flange_center])
            cylinder(h=flange_t, r=flange_d/2, center=true);

        // Body (major OD)
        translate([0,0,z_body_center])
            cylinder(h=body_h, r=body_d_major/2, center=true);

        // Collar near far end
        translate([0,0,z_collar_center])
            cylinder(h=collar_len, r=collar_d/2, center=true);
    }
}

module reduced_od_cut() {
    // Remove the ring between minor and major in the step region,
    // leaving the minor OD there.
    translate([0,0,z_step_center])
        difference() {
            cylinder(h=step_len + 2*eps, r=body_d_major/2 + eps, center=true);
            cylinder(h=step_len + 4*eps, r=body_d_minor/2, center=true);
        }
}

module diamond_recesses_cut() {
    // Recesses on the flange outer face (at z_min)
    z_recess_center = z_min + diamond_depth/2 + eps;

    for (i = [0:diamond_count-1]) {
        rotate([0,0,i*360/diamond_count])
            translate([diamond_radial_pos, 0, z_recess_center])
                diamond_prism(diamond_w, diamond_h, diamond_depth + 2*eps);
    }
}

module hex_bore_cut() {
    hex_prism_through(hex_af, body_len_total + 6*eps);
}

// ---------- Final ----------
difference() {
    difference() {
        outer_solid();
        reduced_od_cut();
    }
    hex_bore_cut();
    diamond_recesses_cut();
}

// Keyed shaft/handle assembly - ONE connected solid
// Units: mm

$fn = 64;

// ---------------- Parameters ----------------
bbox_L = 0.21;
bbox_W = 0.11;
bbox_H = 0.10;

rod_L = bbox_L;
rod_d = 0.030;

rod_twist_deg = 70;     // stronger twist so faceting reads clearly
rod_facets = 8;
rod_slices = 64;

block_L = 0.060;
block_W = 0.090;
block_H = 0.080;
block_end_margin = 0.005;
block_chamfer = 0.006;  // more visible chamfer

knob1_d = 0.055;
knob1_len = 0.030;
knob1_pos_x = 0.070;    // along rod from left end

knob2_d = 0.045;
knob2_len = 0.028;
knob2_pos_x = 0.145;    // farther along rod

knob_facets = 8;

// Connectivity overlap (kept small relative to tiny model)
overlap = 0.0015;

rod_irreg_amp = 0.0022;

// ---------------- Helpers ----------------
function clamp(v, lo, hi) = v < lo ? lo : (v > hi ? hi : v);

module oct_prism(d, len, facets=8) {
    // Axis along X (because we rotate cylinder)
    rotate([0,90,0])
        cylinder(h=len, r=d/2, center=true, $fn=facets);
}

module chamfered_block(size=[10,10,10], chamfer=1) {
    // Chamfer vertical edges (along Z) by subtracting 4 corner columns
    L = size[0]; W = size[1]; H = size[2];
    c = clamp(chamfer, 0, min(W,H)/2 - 1e-6);

    difference() {
        cube([L,W,H], center=true);

        // remove 4 vertical edge strips to create chamfered look
        for (sx = [-1, 1], sy = [-1, 1]) {
            translate([sx*(L/2 - c/2), sy*(W/2 - c/2), 0])
                cube([c, c, H + 2*overlap], center=true);
        }
    }
}

module faceted_twisted_rod() {
    // Twisted faceted rod with subtle connected irregularities
    union() {
        linear_extrude(height=rod_L, center=true, twist=rod_twist_deg,
                       slices=rod_slices, convexity=10)
            circle(r=rod_d/2, $fn=rod_facets);

        // Irregular bumps (kept small, but visible)
        for (i = [0:4]) {
            t = (i+1)/6;
            zpos = (-rod_L/2) + t*rod_L;
            sgn1 = (i%2==0) ? 1 : -1;
            sgn2 = (i%3==0) ? 1 : -1;
            translate([sgn1*(rod_d/2 - rod_irreg_amp*0.6), sgn2*(rod_d/3), zpos])
                sphere(r=rod_irreg_amp, $fn=24);
        }
    }
}

// ---------------- Assembly ----------------
module assembly_union() {
    // Build along Z then rotate so final rod axis is X
    rotate([0,90,0]) {
        union() {
            // Main rod
            faceted_twisted_rod();

            // Main block near one end (connected with overlap)
            block_center_z = (-rod_L/2) + block_end_margin + block_L/2;
            translate([0, 0, block_center_z])
                chamfered_block([block_L + 2*overlap, block_W, block_H], block_chamfer);

            // --- Knobs: TWO separate faceted polyhedral knobs, clearly distinct ---
            // Place knobs by their centers along the rod axis (Z in this build orientation).
            knob1_center_z = (-rod_L/2) + knob1_pos_x;
            knob2_center_z = (-rod_L/2) + knob2_pos_x;

            // Keep both knobs centered on the rod so they read as mounted collars,
            // and ensure they are separated by a clear gap (not a merged thickening).
            // (Positions already ensure separation; overlap only ensures manifold union.)
            translate([0, 0, knob1_center_z])
                oct_prism(knob1_d, knob1_len + 2*overlap, knob_facets);

            translate([0, 0, knob2_center_z])
                oct_prism(knob2_d, knob2_len + 2*overlap, knob_facets);

            // Small root collars to guarantee manifold connection to the rod
            // (very thin along X, but enough to fuse surfaces robustly)
            collar_t = overlap * 3;

            translate([0, 0, knob1_center_z])
                rotate([0,90,0])
                    cylinder(h=collar_t, r=knob1_d/2, center=true, $fn=knob_facets);

            translate([0, 0, knob2_center_z])
                rotate([0,90,0])
                    cylinder(h=collar_t, r=knob2_d/2, center=true, $fn=knob_facets);
        }
    }
}

// Final Output
assembly_union();

// Mirrored L-shaped sheet-metal bracket pair (single connected solid)
// Units: mm

$fn = 64;

// Target bounding box (approx): 0.3 x 0.1 x 0.1
bbox_L = 0.30;
bbox_W = 0.10;
bbox_H = 0.10;

// Sheet metal + features
t = 0.005;

plate_L = bbox_L;     // along X
plate_H = bbox_H;     // along Z
flange_L = bbox_L;    // along X
flange_W = 0.07;      // along Y (each bracket)

bend_r = 0.01;

hole_d = 0.008;
hole_pitch_x = 0.06;
hole_pitch_z = 0.03;
hole_edge_x = 0.03;
hole_edge_z = 0.02;

slot_L = 0.02;
slot_W = 0.008;
slot_offset_from_bend = 0.008; // from inside corner along flange Y

pair_gap = 0.01;      // gap between the two mirrored brackets (air gap)
bridge_t = 0.001;     // thin connector to ensure ONE connected solid

overlap = 0.001;

// Derived placement
// Each bracket occupies Y in [y0, y0+flange_W], with vertical plate centered at y0 + t/2
y0_left  = -(pair_gap/2 + flange_W);
y0_right =  (pair_gap/2);

// ---------- Helpers ----------
module rounded_bend_solid(len_x, r, th) {
    // Quarter-cylinder "bend" volume that connects plate and flange.
    // Axis along X, quarter in +Y/+Z from the inside corner.
    // Built as intersection of a cylinder with a cube to keep only the quadrant.
    intersection() {
        rotate([0,90,0]) cylinder(r=r+th, h=len_x, center=true);
        // Keep +Y and +Z quadrant relative to local origin
        translate([0, (r+th)/2, (r+th)/2])
            cube([len_x + 2*overlap, r+th + 2*overlap, r+th + 2*overlap], center=true);
    }
}

module bracket_at_y(y0) {
    // Inside corner (bend) reference:
    // - Flange top surface at z = t
    // - Plate starts at z = t (so plate does not extend below flange)
    // - Inside corner line at y = y0 + t
    y_inside = y0 + t;

    module raw_body() {
        union() {
            // Horizontal flange: spans y0..y0+flange_W, thickness t at z=0..t
            translate([0, y0 + flange_W/2, t/2])
                cube([flange_L, flange_W, t], center=true);

            // Vertical plate: thickness t in Y, height plate_H above flange (z=t..t+plate_H)
            translate([0, y0 + t/2, t + plate_H/2])
                cube([plate_L, t, plate_H], center=true);

            // Radiused bend volume at inside corner (y=y_inside, z=t)
            translate([0, y_inside, t])
                rounded_bend_solid(plate_L, bend_r, t);
        }
    }

    module hole_pattern_cut() {
        // Holes through the vertical plate (along Y)
        // Place on plate mid-thickness at y = y0 + t/2, with Z measured from bottom of plate (z=t)
        y_hole = y0 + t/2;
        z0 = t + hole_edge_z;
        x0 = -plate_L/2 + hole_edge_x;

        for (ix = [0,1])
            for (iz = [0,1])
                translate([x0 + ix*hole_pitch_x, y_hole, z0 + iz*hole_pitch_z])
                    rotate([90,0,0])
                        cylinder(d=hole_d, h=t + 2*overlap, center=true);
    }

    module flange_slot_cut() {
        // Small central slot on flange near the bend (through thickness)
        // Centered in X, located near inside corner along Y.
        y_slot = y_inside + slot_offset_from_bend;
        translate([0, y_slot, t/2])
            cube([slot_L, slot_W, t + 2*overlap], center=true);
    }

    difference() {
        raw_body();
        union() {
            hole_pattern_cut();
            flange_slot_cut();
        }
    }
}

module connector_bridge() {
    // Thin bridge between the two brackets to make the overall model ONE connected solid.
    // Placed near the inside corners, low profile so it doesn't dominate the shape.
    // Spans the air gap between brackets.
    y_left_inner  = y0_left  + flange_W; // left bracket inner edge at y = -pair_gap/2
    y_right_inner = y0_right;            // right bracket inner edge at y = +pair_gap/2
    y_mid = (y_left_inner + y_right_inner)/2;

    // Bridge spans across the gap plus a tiny overlap into each bracket
    bridge_w = (y_right_inner - y_left_inner) + 2*overlap;

    // Put bridge near the bend region (z around t) and centered in X
    translate([0, y_mid, t/2])
        cube([bbox_L*0.25, bridge_w, bridge_t], center=true);
}

// ---------- Final model ----------
color("Silver")
union() {
    bracket_at_y(y0_left);
    bracket_at_y(y0_right);
    connector_bridge();
}

// Spool / standoff-like double-ended bracket
// Units: mm
// One connected solid, obround end flanges, through-holes near outer edges, raised lugs on opposite sides.

$fn = 96;

// -------------------- Parameters --------------------
web_L = 26;
web_W = 12;
web_H = 12;

flange_L = 12;          // length of obround along X
flange_W = 30;          // width of obround along Y
flange_H = 12;

hole_d = 4;
hole_edge_offset = 4;   // from outermost end of flange along X

lug_L = 4;
lug_W = 6;
lug_H = 8;
lug_side_offset = 6;    // Y offset from centerline

overlap = 0.6;          // small overlap to guarantee connectivity
hole_extra_h = 2;       // extra height for clean subtraction

// -------------------- Helpers --------------------
module obround2d(len, wid) {
    // 2D capsule/obround: overall length=len, width=wid
    r = wid/2;
    hull() {
        translate([-(len/2 - r), 0]) circle(r=r);
        translate([ +(len/2 - r), 0]) circle(r=r);
    }
}

module flange_at(xc) {
    translate([xc, 0, 0])
        linear_extrude(height=flange_H, center=true)
            obround2d(flange_L, flange_W);
}

module web() {
    cube([web_L, web_W, web_H], center=true);
}

module lug_at(xc, ysign) {
    // Lug sits on top of flange, offset in Y; overlaps slightly into flange for connectivity
    translate([xc, ysign*lug_side_offset, flange_H/2 + lug_H/2 - overlap])
        cube([lug_L, lug_W, lug_H], center=true);
}

module hole_at(xc, xsign) {
    // Hole near outer edge of flange (toward +/-X)
    // Outer end of flange is at xc + xsign*(flange_L/2)
    x_hole = xc + xsign*(flange_L/2 - hole_edge_offset);
    translate([x_hole, 0, 0])
        cylinder(h=max(web_H, flange_H) + hole_extra_h, r=hole_d/2, center=true);
}

// -------------------- Build --------------------
x_flange = web_L/2 + flange_L/2 - overlap;

module solid_no_holes() {
    union() {
        web();
        flange_at(-x_flange);
        flange_at( x_flange);

        // Opposed lugs for symmetric double-ended mounting geometry
        lug_at(-x_flange, +1);
        lug_at( x_flange, -1);
    }
}

module final_model() {
    difference() {
        solid_no_holes();
        hole_at(-x_flange, -1);
        hole_at( x_flange, +1);
    }
}

// -------------------- Output --------------------
color("Silver") final_model();

// Parameters
L = 0.1; //[0.05:0.2:0.001]
W = 0.08; //[0.04:0.16:0.001]
T = 0.03; //[0.015:0.06:0.001]
frame_wall = 0.012; //[0.006:0.024:0.001]
opening_L = 0.07; //[0.035:0.09:0.001]
opening_W = 0.05; //[0.025:0.07:0.001]
end_block_L = 0.02; //[0.01:0.04:0.001]
end_block_extra_T = 0.01; //[0.005:0.02:0.001]
tab_L = 0.018; //[0.009:0.036:0.001]
tab_W = 0.02; //[0.01:0.04:0.001]
tab_T = 0.018; //[0.009:0.03:0.001]
tab_angle_deg = 20; //[0:45:1]
step_drop = 0.006; //[0.003:0.012:0.001]
gap_H = 0.008; //[0.004:0.016:0.001]
gap_L = 0.01; //[0.005:0.02:0.001]
overlap = 0.001; //[0.0005:0.002:0.0005]
chamfer = 0.001; //[0.0005:0.003:0.0005]
fillet_r = 0.0008; //[0.0004:0.002:0.0002]

// Base Shapes
module outer_frame_plate() {
  cube([L, W, T], center=true);
}

module central_through_opening() {
  cube([opening_L, opening_W, T + 2*overlap], center=true);
}

module end_block_thick_region() {
  translate([L/2 - end_block_L/2, 0, T/2 + end_block_extra_T/2 - overlap])
    cube([end_block_L, W, end_block_extra_T], center=true);
}

module cantilever_hook_tab_raw() {
  translate([opening_L/2 - tab_L/2 + overlap, 0, T/2 - tab_T/2 + overlap])
    cube([tab_L, tab_W, tab_T], center=true);
}

module hook_step_raw() {
  translate([opening_L/2 - (tab_L*0.35)/2 + overlap, 0, T/2 - tab_T/2 - step_drop/2 + overlap])
    cube([tab_L*0.35, tab_W, step_drop], center=true);
}

module undercut_gap_raw() {
  translate([opening_L/2 - gap_L/2 + overlap, 0, T/2 - tab_T/2 + gap_H/2])
    cube([gap_L, tab_W*0.8, gap_H], center=true);
}

module chamfer_wedge_xp() {
  translate([L/2 - chamfer/2, 0, end_block_extra_T/2])
    rotate([0, 45, 0])
    cube([chamfer, W + 2*overlap, T + end_block_extra_T + 2*overlap], center=true);
}

module chamfer_wedge_xn() {
  translate([-L/2 + chamfer/2, 0, 0])
    rotate([0, -45, 0])
    cube([chamfer, W + 2*overlap, T + 2*overlap], center=true);
}

module chamfer_wedge_yp() {
  translate([0, W/2 - chamfer/2, end_block_extra_T/2])
    rotate([45, 0, 0])
    cube([L + 2*overlap, chamfer, T + end_block_extra_T + 2*overlap], center=true);
}

module chamfer_wedge_yn() {
  translate([0, -W/2 + chamfer/2, end_block_extra_T/2])
    rotate([-45, 0, 0])
    cube([L + 2*overlap, chamfer, T + end_block_extra_T + 2*overlap], center=true);
}

module small_fillet_rounding_sphere() {
  sphere(r=fillet_r, center=true);
}

// Operations
module frame_minus_opening() {
  difference() {
    outer_frame_plate();
    central_through_opening();
  }
}

module frame_with_end_block() {
  union() {
    frame_minus_opening();
    end_block_thick_region();
  }
}

module hook_tab_with_step() {
  union() {
    cantilever_hook_tab_raw();
    hook_step_raw();
  }
}

module hook_tab_angled() {
  rotate([0, -tab_angle_deg, 0])
    hook_tab_with_step();
}

module frame_with_hook_tab() {
  union() {
    frame_with_end_block();
    hook_tab_angled();
  }
}

module frame_hook_with_undercut_gap() {
  difference() {
    frame_with_hook_tab();
    undercut_gap_raw();
  }
}

module edge_chamfers() {
  difference() {
    frame_hook_with_undercut_gap();
    chamfer_wedge_xp();
    chamfer_wedge_xn();
    chamfer_wedge_yp();
    chamfer_wedge_yn();
  }
}

module small_fillet_rounding() {
  minkowski() {
    edge_chamfers();
    small_fillet_rounding_sphere();
  }
}

// Final Output
small_fillet_rounding();

// Thin stepped mounting plate with 6 diamond (rotated-square) through-holes
// Bounding box target: 0.1 x 0.1 x ~0 (very thin plate)

$fn = 48;

// --- Parameters (mm) ---
bbox_X = 0.10;
bbox_Y = 0.10;
T      = 0.001;          // very thin plate (keeps Z ~ 0.0 in many viewers)

step_depth  = 0.018;     // side notch depth
step_length = 0.028;     // notch length from each end

// Outer corner rounding (2D) and small Z fillet (kept tiny to preserve thinness)
corner_r_2d = 0.004;
z_fillet_r  = 0.00015;

// Holes (diamond appearance = rotated square)
hole_square_side = 0.010;
hole_rotation_deg = 45;
hole_pitch_Y = 0.020;
group_offset_X = 0.028;

// Small overlap for robust boolean cuts
cut_overlap = 0.002;

// --- Helpers ---
module rounded_polygon_2d(pts, r) {
    // Offset out then in to round/chamfer corners in 2D
    // (works well for plate-like parts)
    offset(delta = r) offset(delta = -r) polygon(points = pts);
}

module plate_profile_2d() {
    // Stepped outline: rectangular plate with side notches centered in Y
    // Points are CCW
    pts = [
        [-bbox_X/2, -bbox_Y/2],
        [ bbox_X/2, -bbox_Y/2],
        [ bbox_X/2, -bbox_Y/2 + step_length],
        [ bbox_X/2 - step_depth, -bbox_Y/2 + step_length],
        [ bbox_X/2 - step_depth,  bbox_Y/2 - step_length],
        [ bbox_X/2,  bbox_Y/2 - step_length],
        [ bbox_X/2,  bbox_Y/2],
        [-bbox_X/2,  bbox_Y/2],
        [-bbox_X/2,  bbox_Y/2 - step_length],
        [-bbox_X/2 + step_depth,  bbox_Y/2 - step_length],
        [-bbox_X/2 + step_depth, -bbox_Y/2 + step_length],
        [-bbox_X/2, -bbox_Y/2 + step_length]
    ];

    rounded_polygon_2d(pts, corner_r_2d);
}

module plate_solid() {
    // Keep as a constant-thickness plate; optional tiny Z fillet via minkowski
    // (z_fillet_r is tiny so it still reads as flat)
    if (z_fillet_r > 0) {
        minkowski() {
            linear_extrude(height = max(T - 2*z_fillet_r, 0.0001), center = true)
                plate_profile_2d();
            sphere(r = z_fillet_r);
        }
    } else {
        linear_extrude(height = T, center = true)
            plate_profile_2d();
    }
}

module diamond_hole_tool() {
    rotate([0,0,hole_rotation_deg])
        cube([hole_square_side, hole_square_side, T + 2*cut_overlap], center = true);
}

module holes_all() {
    // Two groups of 3 holes each, symmetric about X=0, centered about Y=0
    for (sx = [-1, 1]) {
        for (iy = [-1, 0, 1]) {
            translate([sx*group_offset_X, iy*hole_pitch_Y, 0])
                diamond_hole_tool();
        }
    }
}

// --- Final model (ONE connected solid) ---
difference() {
    plate_solid();
    holes_all();
}

// C-shaped circular clip (planar extrusion) with rounded ends and one slightly bulbous end.
// Single connected solid, no extra bodies.

// ---------- Parameters (meters in original; keep as-is) ----------
bbox_X = 0.03; //[0.015:0.06:0.001]
bbox_Y = 0.02; //[0.01:0.04:0.001]
bbox_Z = 0.0;  //[0.0:0.2:0.001]

t_eps = 0.001; //[0.0005:0.01:0.0005]

R_outer = 0.01; //[0.005:0.02:0.0005]
band_W  = 0.003; //[0.0015:0.006:0.0005]

gap_ang_deg = 60; //[20:140:5]   // total opening angle

end_round_r = 0.0015; //[0.00075:0.003:0.00025]
bulb_scale  = 1.25;   //[1.0:1.8:0.05]

// ---------- Derived ----------
thickness    = max(bbox_Z, t_eps);
R_inner      = max(R_outer - band_W, 0.0001);
R_mid        = (R_outer + R_inner) / 2;
gap_half     = gap_ang_deg / 2;

// Resolution
$fn = 128;

// ---------- Helpers ----------
module ring2d() {
    difference() {
        circle(r = R_outer);
        circle(r = R_inner);
    }
}

// 2D wedge that removes the gap (centered on +X axis)
module gap_wedge2d() {
    // Make wedge large enough to cover the ring area
    Rw = R_outer + 2*end_round_r + 0.002;
    polygon(points = [
        [0, 0],
        [Rw*cos(-gap_half), Rw*sin(-gap_half)],
        [Rw*cos( gap_half), Rw*sin( gap_half)]
    ]);
}

// Rounded end caps (2D) placed at the two gap edges on the mid-radius
module end_caps2d() {
    // Edge angles of the remaining arc are +/- gap_half
    for (s = [-1, 1]) {
        a = s * gap_half;
        translate([R_mid*cos(a), R_mid*sin(a)])
            circle(r = end_round_r);
    }
}

// Slightly bulbous enlargement on one end (choose +gap_half end)
module bulb2d() {
    a = gap_half;
    translate([R_mid*cos(a), R_mid*sin(a)])
        circle(r = end_round_r * bulb_scale);
}

// ---------- Main 2D profile ----------
module clip_profile2d() {
    // Build a smooth C-clip: ring minus wedge, then add rounded ends and bulb.
    union() {
        difference() {
            ring2d();
            gap_wedge2d();
        }
        end_caps2d();
        bulb2d();
    }
}

// ---------- 3D ----------
linear_extrude(height = thickness, center = true, convexity = 10)
    clip_profile2d();

$fn = 96;

// Parameters (meters; original values kept)
bbox_x = 0.02; //[0.01:0.04:0.001]
bbox_y = 0.01; //[0.005:0.02:0.001]
bbox_z = 0.02; //[0.01:0.04:0.001]
shaft_d = 0.006; //[0.003:0.012:0.0005]
shaft_len_total = 0.01; //[0.006:0.02:0.001]
collar_thk = 0.006; //[0.003:0.01:0.0005]
hex_flat_to_flat = 0.01; //[0.005:0.02:0.0005]
overlap = 0.0005; //[0.0002:0.001:0.0001]
chamfer_len = 0.0006; //[0.0002:0.0012:0.0001]
chamfer_d_reduction = 0.001; //[0.0004:0.002:0.0001]

// Derived
shaft_r = shaft_d/2;
hex_R = hex_flat_to_flat / sqrt(3); // circumradius for flat-to-flat size
end_len_each = max(0, (shaft_len_total - collar_thk)/2);

// Helpers
module bbox_limit() { cube([bbox_x, bbox_y, bbox_z], center=true); }

module hex_prism(h) {
    // Hex with flats aligned to X axis (wrench flats)
    rotate([0,0,30]) cylinder(h=h, r=hex_R, center=true, $fn=6);
}

module shaft_body() {
    // Axis along Y to match original orientation
    rotate([90,0,0]) cylinder(h=shaft_len_total, r=shaft_r, center=true);
}

module collar_hex() {
    rotate([90,0,0]) hex_prism(collar_thk);
}

module end_chamfer_cut(sign=1) {
    // Conical cut at each shaft end to create a small chamfer
    // sign = +1 (positive Y end), -1 (negative Y end)
    translate([0, sign*(shaft_len_total/2 - chamfer_len/2), 0])
        rotate([90,0,0])
            cylinder(
                h=chamfer_len,
                r1=shaft_r,
                r2=max(0.00001, (shaft_d - chamfer_d_reduction)/2),
                center=true
            );
}

module final_model() {
    intersection() {
        difference() {
            union() {
                // Main connected solid: cylinder shaft + central hex collar
                shaft_body();
                collar_hex();
            }
            // Chamfer both ends of the shaft (cuts remain connected)
            end_chamfer_cut(+1);
            end_chamfer_cut(-1);
        }
        // Keep within requested bounding box limits (non-zero)
        bbox_limit();
    }
}

final_model();
